const GRAMMAR_SECTIONS = {"yeongyeol": [{"num": 1, "term": "-거나", "meaning": "Hoặc, hay (liệt kê các lựa chọn/hành động tương đương)", "blocks": [["p", "'-거나' có thể gắn vĩ tố thì (thì và sự hoàn thành của hành động) '-었(았, 였)-' ở phía trước, nhưng không dùng vĩ tố phỏng đoán '-겠-'. Dùng để biểu thị việc liệt kê từ hai hành động, trạng thái, sự tồn tại trở lên. Danh từ sẽ dùng dưới dạng 'Danh từ + (이)나'."], ["p", "<b>1. Trường hợp '-거나' được dùng đơn lẻ</b>"], ["ex", "내일은 <b>춥거나</b> 눈이 오겠습니다.", "Ngày mai trời sẽ lạnh hoặc có tuyết rơi."], ["ex", "일요일에 낮잠을 <b>자거나</b> 영화를 봅니다.", "Vào Chủ nhật tôi ngủ nướng hoặc xem phim."], ["p", "<b>2. Trường hợp '-거나' được lặp lại: Dùng khi liệt kê từ hai động từ trở lên có tính chất đối lập hoặc tương đương nhau.</b>"], ["ex", "일찍 <b>왔거나</b> 늦게 <b>왔거나</b> 하여튼 도착해서 다행입니다. (O)", "Dù đến sớm hay đến trễ thì dù sao cũng đã đến nơi, thật may mắn."], ["ex", "밥을 <b>먹거나</b> 빵을 <b>먹거나</b> 마음대로 하세요. (X)", "Dù ăn cơm hay ăn bánh mì thì hãy làm theo ý bạn."]], "practice": [{"vn": "Cuối tuần tôi nghỉ ở nhà hoặc gặp bạn bè.", "hint": "주말/집/쉬다/친구/만나다", "answer": "주말에는 집에서 쉬거나 친구를 만나요."}, {"vn": "Nếu có từ không biết thì hãy tra từ điển hoặc hỏi giáo viên.", "hint": "모르다/단어/있다/사전/찾다/선생님/물어보다", "answer": "모르는 단어가 있으면 사전을 찾거나 선생님께 물어보세요."}, {"vn": "Dù bận hay mệt thì tôi cũng cố gắng tập thể dục.", "hint": "바쁘다/피곤하다/운동/꼭/하다", "answer": "바쁘거나 피곤하거나 운동은 꼭 하려고 해요."}]}, {"num": 2, "term": "-거늘", "meaning": "Đương nhiên là..., huống chi (nhấn mạnh điều hiển nhiên)", "blocks": [["p", "Dùng trong trường hợp nói về thực tế ở mệnh đề trước và thể hiện mệnh đề sau cũng đương nhiên phải như vậy (mệnh đề sau thường đi kèm với '-는가?', '-(으)랴' hoặc câu hỏi), hoặc dùng để hưởng ứng theo thực tế ở mệnh đề trước. Đây là biểu hiện mang tính cổ điển/sách vở."], ["ex", "불우 이웃 돕기도 <b>하거늘</b> 하물며 가족을 안 도울 수 있겠는가?", "Đến việc giúp đỡ hàng xóm khó khăn còn làm được, huống chi lại không thể giúp đỡ gia đình mình sao?"], ["ex", "남의 자식도 <b>귀엽거늘</b> 자기 자식이면 얼마나 귀여울까?", "Con cái nhà người khác còn thấy đáng yêu, huống chi là con của chính mình thì đáng yêu biết chừng nào?"]], "practice": [{"vn": "Động vật còn yêu thương con cái, huống chi con người thì khỏi phải nói.", "hint": "동물/자식/사랑하다/하물며/사람/말하다", "answer": "동물도 자식을 사랑하거늘 하물며 사람이야 말할 것도 없다."}, {"vn": "Người lớn còn mắc lỗi, huống chi trẻ con mắc lỗi thì có gì lạ?", "hint": "어른/실수/하다/아이/당연하다", "answer": "어른도 실수를 하거늘 아이가 실수하는 건 당연하지 않겠는가?"}, {"vn": "Người giàu còn sống tiết kiệm, huống chi người như chúng ta thì khỏi phải nói.", "hint": "부자/아끼다/살다/우리/사람/말하다", "answer": "부자도 아끼며 살거늘 우리 같은 사람이야 말할 것도 없다."}]}, {"num": 3, "term": "-거니와", "meaning": "Không những... mà còn... (vừa công nhận vế trước, vừa bổ sung thêm vế sau)", "blocks": [["p", "<b>1.</b> Dùng khi vừa công nhận nội dung ở mệnh đề trước, vừa bổ sung thêm thực tế ở mệnh đề sau. Thường dùng khi muốn nói rằng không chỉ có thực tế ở mệnh đề trước mà còn thêm cả thực tế ở mệnh đề sau nữa nên càng như thế nào đó."], ["ex", "그는 열심히 <b>일하거니와</b> 운도 좋아서 하는 일마다 성공을 거두었다.", "Anh ấy không những làm việc chăm chỉ mà may mắn cũng tốt nên làm việc gì cũng thu được thành công."], ["ex", "정은이는 얼굴도 <b>예쁘거니와</b> 마음씨까지 착해서 인기가 최고다.", "Jung-eun không những có khuôn mặt đẹp mà tấm lòng cũng tốt nên rất được yêu thích."], ["p", "<b>2.</b> [Gắn vào các từ như '다시 말하다' (nói lại), '다시 설명하다' (giải thích lại), '거듭 덧붙이다' (thêm vào đó)], dùng để thể hiện việc nhắc lại một lần nữa nội dung có liên quan đến thực tế ở mệnh đề sau."], ["ex", "다시 한번 <b>말하거니와</b> 이번 시험은 매우 중요합니다.", "Tôi xin nói lại một lần nữa, kỳ thi lần này vô cùng quan trọng."], ["ex", "거듭 <b>덧붙이거니와</b> 오늘은 절대로 늦으시면 안 됩니다.", "Tôi xin nhấn mạnh thêm, hôm nay tuyệt đối không được đến trễ."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-았거니와' và '-겠거니와'</b>", "<b>1. -았거니와:</b> Dùng khi nói về việc đã kết thúc hoặc sự việc trong", "quá khứ."]], ["ex", "그는 열심히 <b>했거니와</b> 운도 좋아서 하는 일마다 성공을 거두었다.", "Anh ấy không những đã làm việc chăm chỉ mà may mắn cũng tốt nên làm việc gì cũng thành công."], ["ex", "부모님도 <b>돌아가셨거니와</b> 하나 남은 동생마저 얼마 전에 죽었다.", "Bố mẹ không những đã qua đời mà ngay cả người em duy nhất còn lại cũng mới mất cách đây không lâu."], ["bq", ["<b>2. -겠거니와:</b> Dùng khi muốn thể hiện tương lai hoặc ý chí."]], ["ex", "대학에도 <b>가겠거니와</b> 공부를 열심히 해서 은혜를 갚겠습니다.", "Tôi không những sẽ vào đại học mà còn sẽ học tập chăm chỉ để đáp lại ơn nghĩa."], ["ex", "승화를 보려고 전화도 <b>하겠거니와</b> 직접 찾아가서 만나자고 할 것이다.", "Để gặp Seung-hwa, anh ấy không những sẽ gọi điện mà chắc chắn sẽ trực tiếp tìm đến gặp."]], "practice": [{"vn": "Diễn viên đó không những diễn xuất giỏi mà khả năng ca hát cũng xuất sắc.", "hint": "배우/연기/잘하다/노래/실력/뛰어나다", "answer": "그 배우는 연기도 잘하거니와 노래 실력도 뛰어나다."}, {"vn": "Quán này không những giá rẻ mà còn ngon nên đông khách.", "hint": "식당/값/싸다/맛/좋다/손님/많다", "answer": "이 식당은 값도 싸거니와 맛도 좋아서 손님이 많다."}, {"vn": "Tôi xin nhấn mạnh lại một lần nữa, an toàn là điều quan trọng nhất.", "hint": "다시/한번/강조하다/안전/가장/중요하다", "answer": "다시 한번 강조하거니와 안전이 가장 중요합니다."}]}, {"num": 4, "term": "-거든", "meaning": "Nếu... thì (điều kiện, thường dùng khi vế sau là đề nghị/mệnh lệnh/câu hỏi)", "blocks": [["p", "<b>1.</b> Mang ý nghĩa \"Nếu nội dung trước là sự thật hoặc trở thành sự thật\"."], ["ex", "어려운 일이 <b>생기거든</b> 언제든지 연락 주십시오.", "Nếu có việc gì khó khăn phát sinh, hãy liên lạc cho tôi bất cứ lúc nào."], ["ex", "고향에 <b>가거든</b> 선생님께 이 편지를 꼭 전해 주세요.", "Nếu có về quê, nhất định hãy chuyển lá thư này cho thầy/cô nhé."], ["p", "<b>2.</b> Dùng khi nội dung ở mệnh đề trước là như vậy nên nội dung ở mệnh đề sau đương nhiên cũng là sự thật."], ["ex", "언니가 저토록 <b>지혜롭거든</b>, 동생이야 더 말할 것도 없다.", "Chị gái mà thông minh đến nhường ấy thì em gái lại càng không cần phải nói thêm nữa."], ["ex", "고슴도치도 제 자식은 예쁘다고 <b>하거든</b>, 하물며 사람이야.", "Ngay cả con nhím còn thấy con mình đẹp, huống chi là con người."], ["bq", ["<b>Tìm hiểu thêm | Vĩ tố kết thúc câu '-거든'</b>", "'-거든' còn được dùng như một vĩ tố kết thúc câu nhằm đưa ra nguyên", "nhân hoặc căn cứ mà người nói nghĩ như vậy về nội dung ở mệnh đề", "trước, hoặc đưa ra tiền đề cho nội dung tiếp theo."]], ["ex", "강아지가 많이 아픈가 봐. 밥을 이렇게 많이 <b>남겼거든</b>.", "Có vẻ chú chó bị đau nhiều lắm. Nó đã bỏ lại nhiều cơm thế này cơ mà."], ["ex", "어제 백화점에서 옷을 <b>샀거든</b>. 그런데 오늘 보니까 더 싸게 팔더라고.", "Hôm qua tôi đã mua áo ở trung tâm thương mại đấy. Nhưng hôm nay xem lại thấy người ta bán rẻ hơn."]], "practice": [{"vn": "Nếu có thời gian thì tối nay cùng đi xem phim nhé.", "hint": "시간/있다/저녁/같이/영화/보다/가다", "answer": "시간이 있거든 저녁에 같이 영화 보러 가요."}, {"vn": "Nếu bị lạc đường thì hãy gọi điện cho tôi.", "hint": "길/잃다/저/전화하다", "answer": "길을 잃거든 저한테 전화하세요."}, {"vn": "Nếu trời mưa thì hãy hoãn buổi dã ngoại sang tuần sau.", "hint": "비/오다/소풍/다음 주/미루다", "answer": "비가 오거든 소풍을 다음 주로 미룹시다."}]}, {"num": 5, "term": "-건대", "meaning": "Nghĩ rằng..., cho rằng... (nêu căn cứ/suy đoán của người nói cho đề nghị/mệnh lệnh ở sau, văn viết)", "blocks": [["p", "[Gắn vào một số động từ] Là biểu hiện thông báo trước rằng người nói sắp nói ra suy nghĩ hoặc mong muốn của mình ở mệnh đề sau."], ["p", "<b>1.</b> [Gắn vào các động từ như '생각하다' (suy nghĩ), '추측하다' (dự đoán), '보다' (thấy)] Dùng để thông báo trước rằng người nói sắp nói ra suy nghĩ hoặc quan điểm của mình. Tức là thể hiện nội dung mệnh đề sau chính là suy nghĩ của người nói."], ["ex", "제가 <b>생각하건대</b> 이 음식이 가장 맛있습니다.", "Theo suy nghĩ của tôi thì món ăn này là ngon nhất."], ["ex", "제가 <b>짐작하건대</b> 누군가가 우리 일을 방해하는 게 분명합니다.", "Theo đoán chừng của tôi thì rõ ràng là có ai đó đang cản trở công việc của chúng ta."], ["p", "<b>2.</b> [Gắn vào các động từ như '바라다' (mong muốn), '부탁하다' (nhờ vả), '기대하다' (kỳ vọng)] Thể hiện người nói mong muốn hoặc nhờ vả nội dung ở mệnh đề sau."], ["ex", "<b>바라건대</b> 이번 모임에 꼭 참석해 주십시오.", "Rất mong mọi người sẽ nhất định tham dự buổi gặp mặt lần này."], ["ex", "<b>당부하건대</b> 앞으로 공부를 열심히 하세요.", "Tôi xin dặn dò/nhắc nhở là từ nay về sau hãy học tập thật chăm chỉ."], ["bq", ["<b>Tìm hiểu thêm | Dạng rút gọn của '-하건대'</b>", "Rút gọn '-하건대' có thể viết thành <b>'-건대'</b> hoặc <b>'-건대'</b>."]], ["ex", "<b>부탁건대</b> 앞으로 공부를 열심히 하세요.", "Xin nhờ rằng từ nay hãy học hành chăm chỉ."], ["ex", "<b>원건대</b> 저희 편을 응원해 주세요.", "Mong rằng hãy ủng hộ cho phe chúng tôi."], ["ex", "<b>회상건대</b> 우리가 같이 일했을 때가 좋았어요.", "Nhớ lại thì thời gian chúng ta cùng làm việc với nhau thật đẹp."]], "practice": [{"vn": "Nếu nghĩ rằng tình hình gấp thì mong bạn liên lạc trước.", "hint": "사정/급하다/먼저/연락/바라다", "answer": "사정이 급하건대 먼저 연락을 주시기 바랍니다."}, {"vn": "Theo tôi nghĩ thì cách này là tốt nhất, hãy thử một lần xem.", "hint": "생각/방법/최선이다/한번/시도하다", "answer": "내 생각으로는 이 방법이 최선이건대 한번 시도해 봅시다."}, {"vn": "Mong rằng anh/chị luôn khỏe mạnh, tôi sẽ thường xuyên liên lạc.", "hint": "몸/건강히/잘 지내다/자주/연락드리다", "answer": "부디 몸 건강히 잘 지내시건대 자주 연락드리겠습니다."}]}, {"num": 6, "term": "-건만", "meaning": "Nhưng, thế mà (nêu thực tế vế trước, nhưng vế sau lại trái ngược, không như mong đợi)", "blocks": [["p", "Thể hiện việc xảy ra nội dung, tình huống hoặc kết quả trái ngược với thực tế mà mệnh đề trước biểu thị."], ["ex", "그는 열심히 공부하기는 <b>하건만</b> 한국말을 잘 못 해요.", "Anh ấy thì đúng là học hành chăm chỉ thật đấy nhưng lại không giỏi tiếng Hàn."], ["ex", "물건은 <b>좋건만</b> 값이 비싸서 살 수 없어요.", "Hàng hóa thì tốt đấy nhưng giá đắt nên không thể mua được."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-았건만', '-겠건만' và '-지만'</b>", "<b>1.</b> Khi thể hiện việc đã hoàn thành, dùng thì quá khứ '-았/었-'", "ghép thành <b>'-았건만'</b>."]], ["ex", "한 시간이나 <b>기다렸건만</b> 경아는 오지 않았다.", "Đã đợi suốt một tiếng đồng hồ rồi nhưng Gyeong-ah vẫn không đến."], ["ex", "한국에 삼 년이나 <b>살았건만</b> 한국말을 하지 못한다.", "Đã sống ở Hàn Quốc tới 3 năm rồi nhưng vẫn không nói được tiếng Hàn."], ["bq", ["<b>2.</b> Khi thể hiện ý nghĩa ý chí hoặc dự đoán, dùng <b>'-겠건만'</b>."]], ["ex", "도와 달라고 하면 도와 <b>주겠건만</b> 통 말이 없네요.", "Nếu bảo giúp thì tôi đã giúp rồi nhưng đằng này chẳng thấy nói năng gì cả."], ["ex", "그때 출발했으면 벌써 <b>도착했겠건만</b> 아직 오지 않았습니다.", "Nếu xuất phát lúc đó thì chắc giờ đã đến nơi rồi nhưng hiện vẫn chưa tới."], ["bq", ["<b>3.</b> '-건만' có thể thay đổi bằng <b>'-지만'</b>, và thông thường", "'-지만' được sử dụng nhiều hơn."]], ["ex", "그는 일을 열심히 하기는 <b>하지만</b> 성과가 별로 없다.", "Anh ấy làm việc chăm chỉ thật đấy nhưng thành quả chẳng có bao nhiêu."], ["ex", "한국에 삼 년이나 <b>살았지만</b> 한국말을 하지 못한다.", "Tuy đã sống ở Hàn Quốc 3 năm nhưng không nói được tiếng Hàn."]], "practice": [{"vn": "Đã học chăm chỉ vậy mà kết quả lại không tốt.", "hint": "열심히/공부하다/결과/좋다", "answer": "열심히 공부했건만 결과가 좋지 않았다."}, {"vn": "Có người tiền nhiều mà lại không hạnh phúc.", "hint": "돈/많다/행복하다/사람", "answer": "돈은 많건만 행복하지 않은 사람들이 있다."}, {"vn": "Đã hẹn rồi mà anh ấy lại không xuất hiện.", "hint": "약속/하다/그/나타나다", "answer": "약속을 했건만 그는 나타나지 않았다."}]}, {"num": 7, "term": "-게", "meaning": "Để, sao cho (mục đích, tiêu chuẩn); hoặc dùng thành '-게 하다' để chỉ sự sai khiến", "blocks": [["h4", "1. Vĩ tố nối phụ thuộc"], ["p", "[Gắn vào động từ, '있다/없다'] Thể hiện mệnh đề trước trở thành mục đích, tiêu chuẩn,... cho mệnh đề sau. Mang ý nghĩa '~하도록' (để/sao cho), '~할 수 있도록' (để có thể), '-게끔'."], ["ex", "친구들과 함께 먹을 수 <b>있게</b> 과자를 많이 만들자.", "Hãy làm nhiều bánh kẹo để có thể ăn cùng các bạn nào."], ["ex", "부모님이 깨시지 <b>않게</b> 조용조용 방으로 들어갔다.", "Tôi đã đi vào phòng thật nhẹ nhàng để bố mẹ không bị thức giấc."], ["h4", "2. Vĩ tố nối bổ trợ"], ["p", "① [Gắn sau dũng từ chỉ hành động] Dùng kết hợp thành dạng '-게 하다', '-게 만들기' để thể hiện <b>sự sai khiến (사동)</b>. Mang ý nghĩa '누가 무엇을 하도록 시키다' (bắt/khiến ai đó làm gì)."], ["ex", "어머니는 내가 어릴 때부터 피아노를 <b>치게 하셨다</b>.", "Mẹ tôi đã bắt tôi chơi đàn piano từ khi tôi còn nhỏ."], ["ex", "친구를 앉아서 <b>기다리게 한다</b>.", "Bắt bạn phải ngồi chờ đợi."], ["p", "② [Dùng dưới dạng '-게 하다', '-게 만들기'] Thể hiện việc dẫn đến một tình huống như vậy."], ["ex", "<b>놀라게 해서</b> 미안합니다.", "Xin lỗi vì đã làm bạn ngạc nhiên."], ["ex", "나는 아버지를 <b>기쁘게 해</b> 드리고 싶었다.", "Tôi đã muốn làm cho bố được vui lòng."], ["p", "③ [Dùng dưới dạng '-게 되다'] Thể hiện việc dẫn đến một tình huống như vậy."], ["ex", "회사가 문을 <b>닫게 되었거든요</b>.", "Công ty đã bị đóng cửa rồi đấy."], ["ex", "풀이 <b>누렇게 되었다</b>.", "Cỏ đã bị úa vàng."], ["h4", "3. Chức năng phó từ"], ["p", "① Thể hiện việc người nói nghĩ rằng sự việc là như vậy. Mang ý nghĩa '-다고' (rằng/cho là)."], ["ex", "주영이는 사람들을 <b>가볍게</b> 여긴다.", "Ju-yeong coi thường người khác."], ["ex", "나이를 먹어 갈수록 아내가 <b>소중하게</b> 느껴진다.", "Càng nhiều tuổi, tôi càng cảm thấy vợ mình quý giá/trân trọng hơn."], ["p", "② [Gắn vào tính từ hoặc tự động từ] Thể hiện mức độ, phương thức."], ["ex", "나는 목을 <b>길게</b> 뺐다.", "Tôi đã kéo dài cổ ra (dài cổ chờ đợi)."], ["ex", "눈이 <b>부시게</b> 푸르른 날.", "Một ngày bầu trời xanh đến chói mắt."], ["h4", "4. Cách dùng vĩ tố kết thúc câu (종결 어미의 용법)"], ["p", "① Thể hiện ý nghĩa của '-(으)ㄹ 수 있도록' (để có thể...)."], ["ex", "음식 좀 많이 만들어, 여러 사람이 먹을 수 <b>있게</b>.", "Hãy làm nhiều thức ăn một chút, để nhiều người cùng ăn được."], ["p", "② Kết thúc câu với thái độ thể hiện sự bất mãn của người nói về nội dung câu nói."], ["ex", "웃기지 마, <b>유치하게</b>.", "Đừng có nực cười thế, trẻ con quá đấy."]], "practice": [{"vn": "Hãy tắt đèn để cho đứa trẻ ngủ ngon.", "hint": "아이/잘 자다/불/끄다", "answer": "아이가 잘 잘 수 있게 불을 꺼 주세요."}, {"vn": "Em tôi đã làm cho tôi tức giận.", "hint": "동생/나/화나다/만들다", "answer": "동생은 나를 화나게 만들었다."}, {"vn": "Mẹ đã bắt tôi viết nhật ký mỗi ngày.", "hint": "엄마/매일/일기/쓰다", "answer": "엄마는 내가 매일 일기를 쓰게 하셨다."}]}, {"num": 8, "term": "-게끔", "meaning": "Để, sao cho (mục tiêu/điều kiện cho hành động phía sau — tương tự '-게')", "blocks": [["p", "Thể hiện mệnh đề trước trở thành mục tiêu, lý do, điều kiện cho hành động hoặc trạng thái phía sau."], ["ex", "부모님이 <b>안심하게끔</b> 말씀드렸다.", "Tôi đã nói chuyện để bố mẹ được yên tâm."], ["ex", "내가 능력을 <b>발휘하게끔</b> 뒷받침을 해 주세요.", "Xin hãy hỗ trợ để tôi có thể phát huy năng lực của mình."], ["ex", "강에서 물고기들이 살 수 <b>있게끔</b> 깨끗하게 합시다.", "Chúng ta hãy giữ gìn dòng sông sạch sẽ để cá có thể sinh sống được."]], "practice": [{"vn": "Hãy giải thích chi tiết để tất cả mọi người có thể hiểu.", "hint": "모두/이해하다/자세히/설명하다", "answer": "모두가 이해할 수 있게끔 자세히 설명해 주세요."}, {"vn": "Tôi luôn theo dõi để bọn trẻ được an toàn.", "hint": "아이들/안전하다/늘/지켜보다", "answer": "아이들이 안전하게끔 늘 지켜보고 있어요."}, {"vn": "Hãy xuất phát sớm để không bị trễ.", "hint": "늦다/일찍/출발하다", "answer": "늦지 않게끔 일찍 출발합시다."}]}, {"num": 9, "term": "-고 해서", "meaning": "Vì... nên (nêu lý do một cách nhẹ nhàng, không chắc chắn hoàn toàn)", "blocks": [["p", "<b>1.</b> Thể hiện nội dung ở mệnh đề trước là một trong số vài lý do thực hiện hành động ở mệnh đề sau."], ["ex", "새 학기도 <b>시작했고 해서</b> 한국어 공부를 시작했다.", "Học kỳ mới cũng đã bắt đầu rồi nên tôi đã bắt đầu học tiếng Hàn."], ["ex", "내가 집에서 <b>맏딸이고 해서</b> 늘 어머니를 돕고 있다.", "Vì tôi là con gái lớn trong nhà nên luôn giúp đỡ mẹ."], ["p", "<b>2.</b> [Dùng dưới dạng '-고 -고 해서'] Dùng khi liệt kê từ hai lý do trở lên trong số nhiều lý do dẫn đến hành động ở mệnh đề sau."], ["ex", "손님도 <b>오시고</b> 집에 음식도 <b>없고 해서</b> 시장에 갔다 왔어요.", "Khách cũng đến mà ở nhà lại không có thức ăn nên tôi đã đi chợ về."], ["ex", "배도 <b>고프고</b> 목도 <b>마르고 해서</b> 하던 일을 멈추고 밖으로 나갔다.", "Bụng thì đói mà cổ lại khô nên tôi đã dừng công việc đang làm lại và đi ra ngoài."]], "practice": [{"vn": "Vì trời cũng lạnh nên hôm nay tôi định ở nhà.", "hint": "날씨/춥다/오늘/집/있다", "answer": "날씨도 춥고 해서 오늘은 집에 있으려고요."}, {"vn": "Vì cũng đói bụng nên chúng ta đi ăn gì đó nhé.", "hint": "배/고프다/뭐/먹다/가다", "answer": "배도 고프고 해서 우리 뭐 좀 먹으러 갑시다."}, {"vn": "Vì cũng đã muộn rồi nên hôm nay kết thúc ở đây thôi.", "hint": "시간/늦다/오늘/여기/끝내다", "answer": "시간도 늦고 해서 오늘은 여기서 끝냅시다."}]}, {"num": 10, "term": "-고도", "meaning": "Mặc dù... nhưng, dù đã... nhưng (nhượng bộ)", "blocks": [["p", "Thể hiện sự đối lập với thực tế hay cảm xúc ở mệnh đề trước, hoặc tiếp nối thêm một đặc tính khác."], ["ex", "그렇게 혼이 <b>나고도</b> 아직 정신을 못 차렸다.", "Bị mắng/bị mắng cho một trận như thế rồi mà vẫn chưa tỉnh ngộ ra."], ["ex", "정은이는 일을 <b>망치고도</b> 책임을 지지 않는다.", "Jeong-eun làm hỏng việc rồi mà lại không chịu trách nhiệm."], ["bq", ["<b>Tìm hiểu thêm | Thì (시제) của '-고도'</b>", "Trước '-고도' không được sử dụng các vĩ tố chỉ quá khứ như '-았/었-'", "hoặc chỉ tương lai như '-겠-'."]], ["ex", "그는 실수를 <b>하고도</b> 사과하지 않았다. (O)", "Anh ấy phạm lỗi rồi mà không xin lỗi."], ["ex", "그는 실수하였고도 사과하지 않았다. (X)", ""], ["ex", "그는 <b>떠나고도</b> 연락하지 않을 것이다. (O)", "Dù anh ấy có rời đi thì cũng sẽ không liên lạc đâu."], ["ex", "그는 떠나겠고도 연락하지 않을 것이다. (X)", ""]], "practice": [{"vn": "Bộ quần áo này dù đắt nhưng chất lượng không tốt lắm.", "hint": "옷/비싸다/품질/별로/좋다", "answer": "이 옷은 비싸고도 품질이 별로 안 좋아요."}, {"vn": "Anh ấy dù có nhiều tiền nhưng luôn sống giản dị.", "hint": "돈/많다/항상/검소하다/살다", "answer": "그는 돈이 많고도 항상 검소하게 산다."}, {"vn": "Dù đã uống thuốc rồi nhưng cảm vẫn chưa khỏi.", "hint": "약/먹다/감기/낫다", "answer": "약을 먹고도 감기가 낫지 않았다."}]}, {"num": 11, "term": "-고서", "meaning": "...xong rồi mới... (hành động trước hoàn tất rồi mới thực hiện hành động sau)", "blocks": [["p", "Thể hiện từ hai hành động trở lên xảy ra theo thứ tự thời gian."], ["p", "<b>1.</b> Dùng khi hành động xảy ra trước về mặt thời gian đứng trước, hành động xảy ra sau đứng ở mệnh đề sau. Trường hợp này có thể thay thế thành '-고' và '-고 나서'."], ["ex", "손을 <b>씻고서</b> 밥을 먹어라.", "Hãy rửa tay rồi ăn cơm đi."], ["ex", "수연이가 <b>떠나고 나서</b> 누리도 떠났다.", "Su-yeon rời đi rồi Nuri cũng rời đi."], ["p", "<b>2.</b> Thể hiện trạng thái hoặc kết quả của hành동 phía trước được duy trì trong khi hành động phía sau tiến hành."], ["ex", "무거운 가방을 <b>들고서</b> 갔어요.", "Tôi đã xách/mang cái túi nặng rồi đi."], ["ex", "코트를 <b>입고서</b> 춥다고 한다.", "Mặc áo khoác vào rồi lại kêu lạnh."], ["p", "<b>3.</b> Trong trường hợp nhiều hành động tiếp nối nhau, hành động phía trước chỉ dùng '-고', và chỉ hành động cuối cùng mới dùng '-고서'."], ["ex", "장갑을 끼고 목도리를 <b>하고서</b> 나가라.", "Hãy đeo găng tay, quàng khăn cổ rồi đi ra ngoài."], ["ex", "청소를 하고 빨래를 <b>하고서</b> 쉬었습니다.", "Tôi dọn dẹp, giặt giũ rồi nghỉ ngơi."]], "practice": [{"vn": "Hãy rửa tay xong rồi mới ăn cơm.", "hint": "손/씻다/밥/먹다", "answer": "손을 씻고서 밥을 먹읍시다."}, {"vn": "Tôi sẽ làm xong bài tập rồi mới xem tivi.", "hint": "숙제/다/하다/텔레비전/보다", "answer": "숙제를 다 하고서 텔레비전을 볼게요."}, {"vn": "Suy nghĩ kỹ xong rồi mới đưa ra quyết định.", "hint": "충분히/생각하다/결정/내리다", "answer": "충분히 생각하고서 결정을 내렸다."}]}, {"num": 12, "term": "-고자", "meaning": "Để, với ý định (mục đích, thường dùng trong văn viết trang trọng)", "blocks": [["p", "Là biểu hiện trang trọng của '-(으)려고'. Chủ yếu được dùng trong văn viết, bài phát biểu, phỏng vấn, v.v."], ["p", "<b>1. Trường hợp '-고자 하다' được dùng như một biểu hiện cố định:</b>"], ["ex", "저는 1년 동안 한국어를 <b>배우고자 합니다</b>.", "Tôi muốn/có ý định học tiếng Hàn trong 1 năm."], ["ex", "이번 설날에 고향에 <b>돌아가고자 합니다</b>.", "Tết này tôi muốn/có ý định trở về quê hương."], ["p", "<b>2. Trường hợp '-고자 + Động từ khác':</b>"], ["ex", "친구에게 <b>주고자</b> 책을 샀습니다.", "Tôi đã mua sách để tặng cho bạn."], ["ex", "일찍 <b>일어나고자</b> 일찍 자갑니다.", "Tôi đi ngủ sớm để thức dậy sớm."], ["ex", "한국어를 <b>배우고자</b> 한국에 왔습니다.", "Tôi đã đến Hàn Quốc để học tiếng Hàn."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-고자' và '-(으)러'</b>", "Ý nghĩa cơ bản giống nhau nhưng mệnh đề theo sau có sự khác biệt nhỏ.", "<b>1. -고자:</b> Thể hiện việc mang một mục đích, ý định, hy vọng nào đó.", "Mệnh đề sau có thể đi cùng dạng mệnh lệnh (명령형) hoặc rủ rê", "(청유형)."]], ["ex", "남에게 존중을 <b>받고자</b> 한다면 먼저 남을 존중해야 한다. (명령형, 청유형 가능)", "Nếu muốn nhận sự tôn trọng từ người khác thì trước tiên phải tôn trọng người khác.) <i>→ 남에게 존중을 <b>받고자</b> 한다면 먼저 남을 존중하라/존중하자. </i>(Nếu muốn nhận sự tôn trọng từ người khác thì hãy tôn trọng / cùng tôn trọng người khác trước tiên. - Có thể dùng câu mệnh lệnh, rủ rê"], ["bq", ["<b>2. -(으)러:</b> Thể hiện mục đích của các hành động di chuyển như", "\"đi\" hoặc \"đến\". Mệnh đề sau không thể đi cùng dạng mệnh lệnh hoặc", "rủ rê."]], ["ex", "그녀는 내일 건강 검진을 <b>받으러</b> 병원에 갈 예정이다. 청유형 불가능)", "Cô ấy dự định đến bệnh viện để khám sức khỏe vào ngày mai.) <i>→ 그녀는 내일 건강 검진을 <b>받으러</b> 병원에 가라/가자. (명령형, </i>(Không thể dùng câu mệnh lệnh, rủ rê"]], "practice": [{"vn": "Chúng tôi đã mở cuộc họp để giải quyết vấn đề này.", "hint": "문제/해결하다/회의/열다", "answer": "이 문제를 해결하고자 회의를 열었습니다."}, {"vn": "Chúng tôi đã chuẩn bị sự kiện này để giới thiệu văn hóa Hàn Quốc.", "hint": "한국/문화/알리다/행사/준비하다", "answer": "한국 문화를 알리고자 이 행사를 준비했습니다."}, {"vn": "Tôi có ý định đi du học vào năm sau.", "hint": "내년/유학/가다", "answer": "저는 내년에 유학을 가고자 합니다."}]}, {"num": 23, "term": "-다가는/다간", "meaning": "Cứ... thì (cảnh báo về kết quả xấu nếu tiếp tục hành động)", "blocks": [["p", "Dùng khi lo lắng về một kết quả xấu nên cảnh báo hoặc cẩn trọng. '-다간' là dạng rút gọn của '-다가는'."], ["p", "<b>1. Dự đoán rằng nếu cứ thực hiện hành động ở mệnh đề trước nhiều lần thì có thể sẽ dẫn đến kết quả xấu.</b>"], ["ex", "그렇게 <b>놀다가는</b> 시험에서 떨어질 텐데.......", "Cứ chơi bời như thế thì chắc là sẽ trượt kỳ thi mất......."], ["ex", "저렇게 사탕을 많이 <b>먹다가는</b> 이가 썩을 거예요.", "Cứ ăn nhiều kẹo như thế kia thì sẽ bị sâu răng đấy."], ["ex", "담배를 계속 <b>피우다간</b> 건강이 나빠질 거예요.", "Cứ tiếp tục hút thuốc thì sức khỏe sẽ xấu đi đấy."], ["p", "<b>2. Thể hiện khi thực hiện hành động ở mệnh đề trước thì kết quả ở mệnh đề sau thường xuất hiện như một lẽ thông thường.</b>"], ["ex", "술을 마시고 <b>운전하다가는</b> 사고가 나요.", "Uống rượu rồi lái xe thì sẽ xảy ra tai nạn."], ["ex", "엄마한테 자주 거짓말을 <b>하다간</b> 야단맞아요.", "Cứ thường xuyên nói dối mẹ thì sẽ bị mắng đấy."], ["ex", "도둑질을 <b>하다간</b> 감옥에 가요.", "Trộm cắp thì sẽ phải đi tù."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-다가는', '-다 보면', '-다 보니(까)'</b>"]], ["p", "+---------+---------------------+-------------------+-----------------+ | > <b>Cấu | > </b>Sự việc ở mệnh  | > <b>Kết quả ở     | > </b>Thái độ đối | | >       | > đề trước<b>        | > mệnh đề sau</b>   | > với kết quả<b> | |  trúc</b> |                     |                   |                 | +=========+=====================+===================+=================+ | > <b>-다 | > Xảy ra nhiều lần  | > Kết quả không   | > Dự đoán kết   | | 가는</b>  | > (Tần suất)        | > tốt             | > quả xấu       | +---------+---------------------+-------------------+-----------------+ | > <b>-다 | > Xảy ra liên tục   | > Kết quả tốt     | > Nói bằng cách | | >       | > (Lưu xót/Tăng     | > hoặc Kết quả    | > dự đoán kết   | |  보면</b> | > tiến)             | > không tốt       | > quả           | +---------+---------------------+-------------------+-----------------+ | > <b>-다 | > Xảy ra liên tục   | > Kết quả tốt     | > Nói về kết    | | > 보니  | > (Lưu xót/Tăng     | > hoặc Kết quả    | > quả đã xuất   | | (까)</b>  | > tiến)             | > không tốt       | > hiện          | +---------+---------------------+-------------------+-----------------+"]], "practice": [{"vn": "Cứ chơi bời như thế thì chắc là sẽ trượt kỳ thi mất.", "hint": "그렇게/놀다/시험/떨어지다", "answer": "그렇게 놀다가는 시험에서 떨어질 텐데......."}, {"vn": "Cứ đi trễ liên tục thì có thể sẽ bị công ty đuổi việc đấy.", "hint": "자꾸/지각하다/회사/잘리다", "answer": "자꾸 지각하다가는 회사에서 잘릴지도 몰라요."}, {"vn": "Cứ lái xe quá tốc độ thì có thể xảy ra tai nạn lớn.", "hint": "과속/운전하다/큰/사고/나다", "answer": "과속으로 운전하다가는 큰 사고가 날 수 있어요."}]}, {"num": 24, "term": "-다마는/다만", "meaning": "...nhưng, ...song (thừa nhận điều vế trước nhưng vế sau có phần trái ngược/giới hạn)", "blocks": [["p", "<b>1. Dùng khi công nhận một thực tế hay nội dung nào đó, nhưng bổ sung thêm nội dung trái ngược với nó.</b>"], ["ex", "네 처지는 <b>안타깝다마는</b> 내가 도와줄 수가 없구나.", "Hoàn cảnh của cháu thật đáng tiếc nhưng ta lại không thể giúp được gì."], ["ex", "집이 아주 <b>좋다마는</b> 우리 형편에는 안 맞는 것 같구나.", "Căn nhà thì rất tốt đấy nhưng có vẻ không phù hợp với hoàn cảnh của chúng ta."], ["p", "<b>2. '-다마는' có thể rút gọn thành '-다만'.</b>"], ["ex", "네 처지는 <b>안타깝다만</b> 내가 도와줄 수가 없구나.", "Hoàn cảnh của cháu thật đáng tiếc nhưng ta lại không thể giúp được gì."], ["ex", "집이 아주 <b>좋다만</b> 우리 형편에는 안 맞는 것 같구나.", "Căn nhà thì rất tốt đấy nhưng có vẻ không phù hợp với hoàn cảnh của chúng ta."]], "practice": [{"vn": "Tôi muốn ăn nhưng vì đang ăn kiêng nên đã nhịn.", "hint": "먹다/싶다/다이어트/중/참다", "answer": "먹고 싶다마는 다이어트 중이라서 참았어요."}, {"vn": "Tôi muốn đi nhưng vì không có thời gian nên không đi được.", "hint": "가다/싶다/시간/없다", "answer": "가고 싶다마는 시간이 없어서 못 가요."}, {"vn": "Tốt thì tốt đấy nhưng giá quá đắt nên không mua nổi.", "hint": "좋다/가격/너무/비싸다/사다", "answer": "좋다마는 가격이 너무 비싸서 못 사겠어요."}]}, {"num": 25, "term": "-다면", "meaning": "Nếu... thì (giả định)", "blocks": [["p", "<b>1. Giả định về một việc không chắc chắn. Không phù hợp khi dùng cho việc xảy ra mang tính thông thường hoặc lặp đi lặp lại.</b>"], ["ex", "만약 복권에 <b>당첨된다면</b> 차를 사겠어요.", "Nếu trúng số thì tôi sẽ mua xe ô tô."], ["ex", "만일 회사에서 <b>승진한다면</b> 한턱낼게요.", "Nếu được thăng chức ở công ty thì tôi sẽ khao một chấu."], ["ex", "만약 책을 다 <b>읽는다면</b> 좀 빌려주세요.", "Nếu đọc xong sách thì hãy cho tôi mượn nhé."], ["ex", "만일 모르는 것이 <b>있다면</b> 질문하세요.", "Nếu có chỗ nào không biết thì hãy hỏi nhé."], ["p", "<b>2. Hy vọng, mong ước: Dạng '-다면 좋겠다' có khả năng thực hiện thấp hơn so với '-(으)면 좋겠다'.</b>"], ["p", "① <b>Mong ước của bản thân</b>"], ["ex", "저는 이번 방학 때 <b>여행간다면</b> 좋겠어요.", "Kỳ nghỉ lần này nếu được đi du lịch thì tốt biết mấy."], ["ex", "나는 내년에 <b>취직한다면</b> 좋겠어.", "Năm sau nếu tôi xin được việc làm thì tốt biết mấy."], ["p", "② <b>Mong muốn đối với người khác:</b> Bất kể khả năng thực hiện thế nào, người ta vẫn thường dùng '-다면 좋겠다'. Lý do là vì '-다면 좋겠다' mang lại cảm giác mềm mỏng, không gây áp lực cho người nghe hơn là '-(으)면 좋겠다'."], ["ex", "자주 연락해 <b>주신다면</b> 좋겠습니다.", "Nếu quý vị thường xuyên liên lạc cho thì thật tốt ạ."], ["ex", "음식을 남기지 않고 다 <b>드신다면</b> 좋겠어요.", "Nếu mọi người ăn hết mà không để thừa thức ăn thì tốt biết mấy."], ["ex", "친구와 사이좋게 <b>지낸다면</b> 좋겠어요.", "Nếu con hòa thuận với bạn bè thì tốt biết mấy."]], "practice": [{"vn": "Nếu có nhiều tiền thì tôi muốn đi du lịch vòng quanh thế giới.", "hint": "돈/많다/세계/여행/하다/싶다", "answer": "돈이 많다면 세계 여행을 하고 싶어요."}, {"vn": "Nếu có thể quay ngược thời gian thì tôi muốn làm học sinh lần nữa.", "hint": "시간/되돌리다/다시/학생/되다", "answer": "시간을 되돌릴 수 있다면 다시 학생이 되고 싶어요."}, {"vn": "Nếu ngày mai trời mưa thì hãy hủy chuyến leo núi.", "hint": "내일/비/오다/등산/취소하다", "answer": "내일 비가 온다면 등산은 취소합시다."}]}, {"num": 26, "term": "-다시피", "meaning": "Như đã..., đúng như (nhấn mạnh sự việc đúng như đã biết/thấy)", "blocks": [["p", "Mang nghĩa 'gần như giống với hành động ở phía trước' hoặc dùng để xác nhận lại."], ["p", "<b>1. Dùng với nghĩa 'gần như giống với hành động ở phía trước'</b>"], ["ex", "우리는 <b>싸우다시피</b> 회의를 했다.", "Chúng tôi đã họp mà gần như là cãi nhau."], ["ex", "사업 실패로 수연이의 집은 거의 <b>망하다시피</b> 하였다.", "Vì thất bại trong kinh doanh nên nhà Su-yeon gần như là phá sản."], ["p", "<b>2. Dùng làm trạng từ xác nhận lại một thực tế mà người nghe vốn đã biết</b>"], ["ex", "<b>보다시피</b>, 요즘은 신문 볼 틈도 없다.", "Như bạn thấy đấy, dạo này đến thời gian xem báo cũng không có."], ["ex", "이미 <b>아시다시피</b>, 지금은 중소기업의 사정이 좋지 않습니다.", "Như quý vị đã biết rồi đấy, hiện tại tình hình của các doanh nghiệp vừa và nhỏ không được tốt."]], "practice": [{"vn": "Như các bạn cũng đã biết, vấn đề này rất nghiêm trọng.", "hint": "여러분/알다/문제/매우/심각하다", "answer": "여러분도 아다시피 이 문제는 매우 심각합니다."}, {"vn": "Như các bạn thấy đấy, hôm nay thời tiết rất đẹp.", "hint": "보다/오늘/날씨/아주/좋다", "answer": "보다시피 오늘 날씨가 아주 좋습니다."}, {"vn": "Như mọi người đều biết, anh ấy là người rất chăm chỉ.", "hint": "다들/알다/사람/매우/성실하다", "answer": "다들 알다시피 그는 매우 성실한 사람입니다."}]}, {"num": 27, "term": "-더니(마는/만)", "meaning": "Đã... (rồi) mà, vậy mà (kể lại điều đã quan sát/trải qua ở quá khứ rồi dẫn đến kết quả bất ngờ)", "blocks": [["p", "Dùng khi so sánh quá khứ và hiện tại, hoặc nói về kết quả xảy ra do sự việc trong quá khứ. Mệnh đề trước phải viết về thực tế mà người nói <b>trực tiếp nhìn thấy</b>. Chủ ngữ của mệnh đề trước và sau thường giống nhau. Thường thì chủ ngữ của mệnh đề trước là 'người khác'. Không thể đổi '-더니' thành '-았/었더니'."], ["p", "<b>1. So sánh sự thay đổi giữa quá khứ và hiện tại: Có thể thay bằng '-는데'.</b>"], ["ex", "시험 기간에는 도서관에 사람이 <b>많더니</b> 시험이 끝나니까 적어졌어요.", "Trong kỳ thi thì thư viện đông người, nhưng thi xong cái là thưa thớt hẳn."], ["ex", "처음에는 김치가 <b>맵더니</b> 지금은 안 매워요.", "Bắt đầu thì kim chi cay, nhưng giờ thì không cay nữa."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-더니' và '-는데'</b>", "<b>1. -더니:</b> Dùng khi hồi tưởng lại việc bản thân trực tiếp nhìn", "thấy."]], ["ex", "어제는 길이 <b>복잡하더니</b> 오늘은 그렇지 않아요.", "Hồi tưởng lại tình trạng tắc đường hôm qua để so sánh với hôm nay."], ["bq", ["<b>2. -는데:</b> Dùng khi hồi tưởng lại thực tế mà bản thân biết (dù", "không trực tiếp nhìn thấy)."]], ["ex", "어제는 길이 <b>복잡했는데</b> 오늘은 그렇지 않아요.", "Đơn thuần so sánh thực tế hôm qua tắc đường với hôm nay."], ["p", "+--------+-----------------+------------------+------------------------+ | >      | > <b>Mệnh đề     | > </b>Mệnh đề      | > <b>Người nói trực     | |  </b>Cấu | > trước<b>       | > sau</b>          | > tiếp nhìn thấy/cảm   | | >      |                 |                  | > nhận<b>               | | trúc</b> |                 |                  |                        | +========+=================+==================+========================+ | > <b>-  | > Quá khứ       | > Việc xảy ra    | > $bigcirc$        | | 더니</b> |                 | > sau mệnh đề    |                        | |        |                 | > trước          |                        | +--------+-----------------+------------------+------------------------+ | > <b>-  | > Quá khứ, Hiện | > Quá khứ, Hiện  | > Không liên quan      | | 는데</b> | > tại, Tương    | > tại, Tương lai |                        | |        | > lai           |                  |                        | +--------+-----------------+------------------+------------------------+"], ["p", "<b>2. Kết quả xuất hiện do sự việc trong quá khứ: Có thể thay bằng '-아/어서'.</b>"], ["ex", "친구가 시험공부를 열심히 <b>하더니</b> 시험에서 1등을 했어요.", "Bạn tôi học ôn thi chăm chỉ nên đã đứng nhất trong kỳ thi."], ["ex", "어릴 때부터 노래를 <b>좋아하더니</b> 가수가 됐어요.", "Từ nhỏ đã thích hát ca nên lớn lên đã trở thành ca sĩ."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-더니' và '-아/어서'</b>", "<b>1. -더니:</b> Chủ yếu nhấn mạnh mệnh đề sau."]], ["ex", "어릴 때부터 노래를 <b>좋아하더니</b> 가수가 됐어요.", "Nhấn mạnh việc bây giờ đã trở thành ca sĩ. Mang ý nghĩa người nói đã trực tiếp nhìn thấy hình ảnh thích hát từ nhỏ."], ["bq", ["<b>2. -아/어서:</b> Chủ yếu nhấn mạnh mệnh đề trước."]], ["ex", "어릴 때 노래를 <b>좋아서</b> 가수가 됐어요.", "Lý do trở thành ca sĩ là vì hồi nhỏ thích hát. Ngay cả khi không trực tiếp thấy hình ảnh hồi nhỏ vẫn có thể nói câu này."], ["p", "+--------------+--------------------+----------------------------------+ | > <b>Cấu      | > </b>Cái được nhấn  | > <b>Người nói trực tiếp nhìn     | | > trúc</b>     | > mạnh<b>           | > thấy/cảm nhận</b>                | +==============+====================+==================================+ | > <b>-더니    | > Mệnh đề sau (Kết | > $bigcirc$                  | | > (Kết       | > quả)             |                                  | | > quả)</b>     |                    |                                  | +--------------+--------------------+----------------------------------+ | > <b>-아/어서 | > Mệnh đề trước    | > Không liên quan                | | > (Lý do)</b>  | > (Lý do)          |                                  | +--------------+--------------------+----------------------------------+"]], "practice": [{"vn": "Hôm qua trời trong xanh vậy mà hôm nay lại mưa.", "hint": "어제/날씨/맑다/오늘/비/오다", "answer": "어제는 날씨가 맑더니 오늘은 비가 오네요."}, {"vn": "Em tôi cứ khóc mãi vậy mà bỗng nhiên im lặng.", "hint": "동생/계속/울다/갑자기/조용해지다", "answer": "동생이 계속 울더니 갑자기 조용해졌다."}, {"vn": "Anh ấy đã trăn trở một hồi lâu rồi cuối cùng từ bỏ.", "hint": "한참/고민하다/결국/포기하다", "answer": "그는 한참 고민하더니 결국 포기했다."}]}, {"num": 28, "term": "-더라도", "meaning": "Dù có... đi nữa thì (nhượng bộ mạnh, giả định)", "blocks": [["p", "Mặc dù giả định như mệnh đề trước, nhưng ở mệnh đề sau lại xuất hiện sự trái ngược với giả định của mệnh đề trước."], ["ex", "화가 <b>나더라도</b> 참으세요.", "Dù có nổi giận thì cũng hãy nhẫn nại."], ["ex", "문제가 <b>쉽더라도</b> 잘 생각해서 대답하십시오.", "Dù câu hỏi có dễ thì cũng hãy suy nghĩ kỹ rồi mới trả lời."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-더라도' và '-아/어/여도'</b>", "'-더라도' có khả năng thực hiện tương đối thấp hơn so với", "'-아/어/여도'."]], ["ex", "얘기하기 <b>싫더라도 / 싫어도</b> 하세요.", "Dù không thích nói chuyện thì cũng hãy nói đi."], ["ex", "수연이를 <b>만나더라도 / 만나도</b> 얘기는 안 할 거예요.", "Dù có gặp Su-yeon thì tôi cũng sẽ không nói chuyện đâu."], ["ex", "이민을 <b>가더라도 / 가도</b> 김치는 먹을 거예요.", "Dù có đi nhập cư thì tôi vẫn sẽ ăn kim chi."]], "practice": [{"vn": "Dù có bận đến mấy thì cũng phải ăn cơm chứ.", "hint": "아무리/바쁘다/밥/먹다", "answer": "아무리 바쁘더라도 밥은 먹고 다녀야지요."}, {"vn": "Dù trời có mưa đi nữa thì chúng tôi vẫn sẽ xuất phát theo kế hoạch.", "hint": "비/오다/예정대로/출발하다", "answer": "비가 오더라도 우리는 예정대로 출발할 거예요."}, {"vn": "Dù có thất bại đi nữa thì tôi sẽ thử thách lại lần nữa.", "hint": "실패하다/다시/도전하다", "answer": "실패하더라도 다시 도전할 거예요."}]}, {"num": 29, "term": "-도록", "meaning": "Để, sao cho (đến mức/mục tiêu nào đó, thường dùng với động từ chỉ nỗ lực)", "blocks": [["p", "<b>1. Nói một cách nói khéo léo, nhẹ nhàng. Không nói mang tính khẳng định tuyệt đối. Đứng sau động từ. Nhấn mạnh ý chí của người nói.</b>"], ["ex", "조용히 <b>하도록</b> 하세요. (조용히 하세요.)", "Hãy giữ trật tự nhé. / Hãy giữ trật tự."], ["ex", "수업 시간에 늦지 <b>않도록</b> 하십시오. (수업에 늦지 마십시오.)", "Xin đừng đến muộn giờ học nhé. / Đừng đến muộn giờ học."], ["ex", "앞으로 매일 운동<b>하도록</b> 할 거예요. (앞으로 매일 운동할 거예요.)", "Sau này tôi sẽ tập thể dục mỗi ngày. / Sau này tôi sẽ tập thể dục mỗi ngày."], ["ex", "자주 <b>만나도록</b> 하자. (자주 만나자.)", "Chúng mình hãy thường xuyên gặp nhau nhé. / Thường xuyên gặp nhau nào."], ["p", "<b>2. Thời gian, Mức độ: Dùng với nghĩa 'cho đến khi -(으)ㄹ', 'đến mức -(으)ㄹ'.</b>"], ["ex", "10시가 <b>되도록</b> 학생들이 학교에 오지 않았습니다. (10시가 될 때까지)", "Cho đến tận 10 giờ mà học sinh vẫn chưa đến trường."], ["ex", "시험 전날에 밤새<b>도록</b> 공부했습니다. (밤이 샐 때까지)", "Tôi đã học suốt đêm cho đến sáng vào ngày trước kỳ thi."], ["ex", "집을 떠난 지 3년이 <b>지나도록</b> 소식이 없어서 부모님이 걱정하셨어요. (지날 때까지)", "Rời nhà đã hơn 3 năm mà không có tin tức gì nên bố mẹ rất lo lắng."], ["p", "<b>3. -게: Thể hiện sự sai khiến (bắt người khác làm như vậy), Phó từ (bổ nghĩa cho động từ phía sau)</b>"], ["p", "① <b>Biểu hiện sai khiến:</b> Thể hiện tình huống chủ ngữ làm cho đối tượng khác thực hiện một hành động nào đó. Mọi '-도록' đều có thể đổi thành '-게'."], ["ex", "부모님은 내가 한국에서 공부<b>하도록</b> 허락하셨어요. $rightarrow$ 부모님은 내가 한국에서 공부<b>하게</b> 허락하셨어요.", "Bố mẹ đã cho phép tôi học tập tại Hàn Quốc."], ["ex", "엄마가 나에게 슈퍼에서 우유를 사 <b>오도록</b> 하셨어요. $rightarrow$ 엄마가 나에게 슈퍼에서 우유를 사 <b>오게</b> 하셨어요.", "Mẹ đã bảo tôi đi siêu thị mua sữa về."], ["p", "② <b>Biểu hiện phó từ:</b> Giải thích cụ thể cho động từ đứng trước động từ. Mọi '-도록' đều có thể đổi thành '-게'."], ["ex", "실수하지 <b>않도록</b> 조심하세요. $rightarrow$ 실수하지 <b>않게</b> 조심하세요.", "Hãy cẩn thận để không mắc sai lầm."], ["ex", "약속을 잊어버리지 <b>않도록</b> 공책에 적습니다. $rightarrow$ 약속을 잊어버리지 <b>않게</b> 공책에 적습니다.", "Tôi ghi vào sổ tay để không quên cuộc hẹn."]], "practice": [{"vn": "Tôi sẽ nỗ lực để mọi người có thể sống thoải mái.", "hint": "모두/편하다/지내다/노력하다", "answer": "모두가 편하게 지낼 수 있도록 노력하겠습니다."}, {"vn": "Hãy mặc ấm để không bị cảm.", "hint": "감기/걸리다/따뜻하다/입다", "answer": "감기에 걸리지 않도록 따뜻하게 입으세요."}, {"vn": "Hãy nhanh lên để không bị trễ.", "hint": "늦다/서두르다", "answer": "늦지 않도록 서두릅시다."}]}, {"num": 30, "term": "-든지", "meaning": "Dù là... đi nữa, bất kể (liệt kê các lựa chọn, không quan trọng cái nào)", "blocks": [["p", "<b>1. Khi '-든지' được dùng với nghĩa 'không liên quan dù thế nào đi nữa', nó bất luận được dùng đơn lẻ hay lặp lại, đều có thể thêm '간에' vào phía sau để nhấn mạnh thêm ý nghĩa của từ đó.</b>"], ["ex", "<b>뛰어가든지 걸어가든지</b> 간에 늦지는 않는다.", "Dù chạy đi hay đi bộ đi thì cũng không bị trễ đâu."], ["ex", "수연이가 <b>좋아하든지 싫어하든지</b> 간에 선물을 주었다.", "Dù Su-yeon thích hay ghét thì tôi vẫn tặng quà."], ["p", "<b>2. Khi '-든지' được dùng với nghĩa chọn một trong nhiều cái được liệt kê ra thì cũng không sao, thường hai từ đi kèm sẽ mang ý nghĩa trái ngược nhau.</b>"], ["ex", "<b>가든지 오든지</b> 네가 하고 싶은 대로 해라.", "Đi hay đến thì tùy bạn làm theo ý mình muốn."], ["ex", "선물이 <b>많든지 적든지</b> 고마울 뿐이다.", "Quà nhiều hay ít thì tôi cũng đều biết ơn cả."], ["p", "<b>3. '-든지' còn kết hợp với vĩ tố kết thúc câu '다, 라, 자'. Trường hợp này là dạng rút gọn của '...고(라, 자) 하다' + '-든지'.</b>"], ["ex", "오늘 오라고 <b>하든지</b> 내일 오라고 <b>하든지</b> 무슨 얘기가 있을 거야. $rightarrow$ 오늘 <b>오라든지</b> 내일 <b>오라든지</b> 무슨 얘기가 있을 거야.", "Bảo hôm nay đến hay bảo ngày mai đến thì chắc cũng sẽ có chuyện gì đó thôi."]], "practice": [{"vn": "Dù mưa hay tuyết thì trận đấu vẫn diễn ra theo kế hoạch.", "hint": "비/오다/눈/오다/경기/예정대로/진행되다", "answer": "비가 오든지 눈이 오든지 경기는 예정대로 진행됩니다."}, {"vn": "Dù em làm gì đi nữa thì anh cũng sẽ ủng hộ.", "hint": "무엇/하다/응원하다", "answer": "네가 무엇을 하든지 나는 응원할게."}, {"vn": "Uống cà phê hay uống trà cũng được, cứ tùy ý bạn.", "hint": "커피/마시다/차/마시다/편하다/하다", "answer": "커피를 마시든지 차를 마시든지 편한 대로 하세요."}]}, {"num": 31, "term": "-듯(이)", "meaning": "Như, giống như (so sánh, minh họa cách thức)", "blocks": [["p", "<b>1. Thể hiện mệnh đề sau cũng như vậy giống như nội dung mà mệnh đề trước hàm ý. Mang nghĩa 'giống như việc...'.</b>"], ["ex", "사람마다 얼굴이 <b>다르듯</b> 나라마다 풍습도 다르다.", "Giống như khuôn mặt mỗi người mỗi khác, phong tục mỗi quốc gia cũng khác nhau."], ["ex", "앞에서도 얘기<b>했듯이</b> 광고는 하나의 예술이다.", "Giống như đã nói ở trước, quảng cáo là một nghệ thuật."], ["p", "<b>2. Dùng khi so sánh các thực tế tương tự nhau.</b>"], ["ex", "땀이 비 <b>오듯</b> 쏟아진다.", "Mồ hôi rơi xuống như mưa trút."], ["ex", "이 <b>잡듯</b> 뒤져도 반지를 찾을 수 없었다.", "Dù có lục tìm kỹ như bắt rận thì vẫn không thể tìm thấy chiếc nhẫn."]], "practice": [{"vn": "Đúng như tôi đã nghe đồn, anh ấy thật sự là người rất tốt bụng.", "hint": "소문/듣다/정말/친절하다/사람", "answer": "소문으로 들었듯이 그는 정말 친절한 사람이었다."}, {"vn": "Đúng như đã dự đoán, đề thi rất khó.", "hint": "예상하다/시험/문제/어렵다", "answer": "예상했듯이 시험 문제가 어려웠다."}, {"vn": "Hãy nói chuyện tự nhiên như dòng nước chảy.", "hint": "물/흐르다/자연스럽다/이야기하다", "answer": "물 흐르듯이 자연스럽게 이야기하세요."}]}, {"num": 32, "term": "-아/어/여 가지고", "meaning": "...rồi (hành động trước hoàn tất, giữ nguyên trạng thái đó để làm hành động sau — khẩu ngữ)", "blocks": [["p", "Thực hiện hành động ở mệnh đề trước, duy trì/nắm giữ kết quả đó rồi thực hiện hành động ở mệnh đề sau. Dùng nhiều trong văn nói (khẩu ngữ)."], ["p", "<b>1. Kết hợp với động từ hành động: Thực hiện hành động ở mệnh đề trước, sau đó dựa trên kết quả đó để hành động ở mệnh đề sau được diễn ra.</b>"], ["ex", "편지를 <b>써 가지고</b> 우체통에 넣었어요.", "Tôi viết thư xong rồi bỏ vào hòm thư."], ["ex", "음식을 너무 많이 <b>해 가지고</b> 남았어요.", "Làm quá nhiều đồ ăn nên đã bị thừa."], ["p", "<b>2. Kết hợp với tính từ/động từ trạng thái: Trạng thái ở mệnh đề trước thường gây ảnh hưởng đến mệnh đề sau nhiều hơn là mang nghĩa nắm giữ/duy trì.</b>"], ["ex", "사무실이 <b>추워 가지고</b> 아무 일도 못 했어요.", "Văn phòng lạnh quá nên tôi chẳng làm được việc gì cả."], ["ex", "선생님과 정이 <b>들어 가지고</b> 헤어지기 싫었습니다.", "Đã nảy sinh tình cảm với thầy/cô nên tôi không muốn chia tay."]], "practice": [{"vn": "Tôi đã gói ghém hành lý xong rồi xuất phát.", "hint": "짐/다/싸다/출발하다", "answer": "짐을 다 싸 가지고 출발했어요."}, {"vn": "Tôi đã dành dụm tiền rồi mua nhà.", "hint": "돈/모으다/집/사다", "answer": "돈을 모아 가지고 집을 샀어요."}, {"vn": "Tôi đã ăn cơm xong rồi đi học.", "hint": "밥/먹다/학교/가다", "answer": "밥을 먹어 가지고 학교에 갔어요."}]}, {"num": 33, "term": "-아/어/여다(가)", "meaning": "...rồi mang đi (hành động trước hoàn tất, mang kết quả đó đến nơi khác)", "blocks": [["p", "<b>1. Hành động ở mệnh đề trước được thực hiện tại một địa điểm nhất định, rồi mang kết quả thu được từ đó đến địa điểm thứ hai để thực hiện hành động ở mệnh đề sau. Có đặc trưng là 'sự di chuyển địa điểm'.</b>"], ["ex", "만두를 <b>사다가</b> 먹었어요.", "Tôi mua bánh xếp về rồi ăn."], ["ex", "숙제를 <b>해다가</b> 선생님께 드렸어요.", "Tôi làm bài tập về nhà rồi nộp cho giáo viên."], ["p", "<b>2. Nhìn thì có vẻ giống với '-아/어서' vốn chỉ thứ tự, nhưng trường hợp của '-아/어/여다(가)' thì địa điểm xảy ra ở mệnh đề trước và mệnh đề sau phải khác nhau, còn '-아/어서' thì không bị giới hạn bởi địa điểm xảy ra hành động.</b>"], ["bq", ["<b>Tìm hiểu thêm | So sánh '-아/어/여다가' và '-아/어/여 가지고'</b>", "'-아/어/여다가' thể hiện hành động ở mệnh đề trước và mệnh đề sau được", "thực hiện ở hai nơi khác nhau, còn '-아/어/여 가지고' thì không có ý", "nghĩa chuyển đổi địa điểm."]]], "practice": [{"vn": "Tôi đã làm đồ ăn rồi mang đến nhà bạn.", "hint": "음식/만들다/친구/집/가져가다", "answer": "음식을 만들어다가 친구 집에 가져갔어요."}, {"vn": "Tôi đã mượn sách rồi mang cho em.", "hint": "책/빌리다/동생/주다", "answer": "책을 빌려다가 동생에게 줬어요."}, {"vn": "Tôi đã mua hoa rồi mang tặng mẹ.", "hint": "꽃/사다/어머니/드리다", "answer": "꽃을 사다가 어머니께 드렸어요."}]}, {"num": 34, "term": "-아/어/여서 그런지", "meaning": "Có lẽ vì... nên (phỏng đoán lý do)", "blocks": [["p", "Mang nghĩa 'không thể khẳng định chắc chắn là do mệnh đề trước nên mới dẫn đến kết quả ở mệnh đề sau, nhưng có vẻ là vậy'."], ["ex", "밥을 <b>먹어서 그런지</b> 잠이 와요.", "Không biết có phải do ăn cơm xong không mà tôi thấy buồn ngủ."], ["ex", "30분이나 <b>기다려서 그런지</b> 승현이는 약간 화가 나 있었다.", "Không biết có phải vì đã chờ suốt 30 phút không mà Seung-hyun có chút giận dữ."], ["bq", ["<b>Tìm hiểu thêm | '-(이)라서 그런지'</b>", "Khi gắn vào '이다' (là) thì dùng dưới dạng <b>'-(이)라서 그런지'</b>."]], ["ex", "너는 <b>교포라서 그런지</b> 한국말을 쉽게 배우는구나.", "Không biết có phải vì cậu là kiều bào không mà học tiếng Hàn dễ dàng thật đấy."], ["ex", "유명한 배우가 출연하는 <b>영화라서 그런지</b> 극장에 사람이 많다.", "Không biết có phải vì là bộ phim có diễn viên nổi tiếng đóng không mà rạp chiếu phim đông người thế."]], "practice": [{"vn": "Có lẽ vì trời lạnh nên trên đường không có người.", "hint": "날씨/춥다/거리/사람/없다", "answer": "날씨가 추워서 그런지 거리에 사람이 없다."}, {"vn": "Có lẽ vì không ngủ được nên cứ buồn ngủ suốt.", "hint": "잠/못 자다/계속/졸리다", "answer": "잠을 못 자서 그런지 계속 졸리다."}, {"vn": "Có lẽ vì công việc nhiều nên dạo này trông bạn mệt mỏi.", "hint": "일/많다/요즘/피곤하다/보이다", "answer": "일이 많아서 그런지 요즘 피곤해 보여요."}]}, {"num": 35, "term": "-아/어/여야(만)", "meaning": "Phải... mới (điều kiện bắt buộc, nhấn mạnh)", "blocks": [["p", "Không dùng trong câu mệnh lệnh và rủ rê. Thường dùng để biểu thị nguyên tắc hoặc chân lý."], ["p", "<b>1. Thể hiện tính bắt buộc hoặc điều kiện tất yếu tối thiểu của mệnh đề trước.</b>"], ["ex", "한국말을 <b>알아야</b> 한국에서 살기가 편하지요.", "Phải biết tiếng Hàn thì sống ở Hàn Quốc mới thuận tiện chứ."], ["ex", "택시를 <b>타야</b> 학교에 늦지 않습니다.", "Phải đi xe taxi thì mới không bị trễ học."], ["p", "<b>2. Cũng có thể dùng trong trường hợp lấy thực tế trái ngược làm điều kiện tùy theo mệnh đề sau. Lúc này có thể dùng kết hợp với vĩ tố thì '-았/었/였-'.</b>"], ["ex", "비가 안 <b>왔어야</b> 소풍을 갔을 텐데요.", "Phải chi trời không mưa thì đã đi dã ngoại rồi."], ["ex", "컴퓨터를 잘 <b>해야</b> 취직을 할 텐데.", "Phải giỏi máy tính thì mới xin được việc chứ."], ["p", "<b>3. '-아/어/여야' kết hợp với vĩ tố kết thúc câu '-지' hoặc tiểu từ '만' có nghĩa là 'duy nhất' để thể hiện sự nhấn mạnh mạnh mẽ hơn.</b>"], ["ex", "말하기 연습을 <b>해야지</b> 발음을 고칠 수 있어요.", "Phải luyện nói thì mới sửa được phát âm."], ["ex", "자주 <b>만나야만</b> 정이 들어요.", "Phải thường xuyên gặp nhau thì mới nảy sinh tình cảm."], ["p", "<b>4. Giả định rằng mình đưa ra tính bắt buộc tất yếu nhưng cũng chẳng có tác dụng gì. Mang nghĩa tương tự '-어/아/여도', '-어/아/여 봤자'.</b>"], ["ex", "아무리 <b>졸라야</b> 아버지는 꺼떡도 안 하신다.", "Dù cho có nằmnheo thế nào thì bố cũng chẳng nhúc nhích."], ["ex", "정직하게 <b>살아야</b> 알아주는 사람은 아무도 없을 것이다.", "Dù có sống trung thực thì cũng chẳng có ai công nhận đâu."], ["p", "<b>5. Khi gắn thì vào thành dạng '-았/었/였어야' thì nó thể hiện sự hối hận về một trường hợp cụ thể chứ không phải chân lý thông thường.</b>"], ["ex", "정기 검진을 <b>받았어야</b> 초기에 병을 발견했을 텐데요.", "Giá mà đã đi khám sức khỏe định kỳ thì đã phát hiện ra bệnh từ giai đoạn đầu rồi."], ["ex", "미리 약속을 <b>했어야</b> 오늘 만날 수 있었을 것이다.", "Giá mà đã hẹn trước từ sớm thì hôm nay đã có thể gặp nhau rồi."]], "practice": [{"vn": "Phải nỗ lực chăm chỉ thì mới có thể thành công.", "hint": "열심히/노력하다/성공하다", "answer": "열심히 노력해야 성공할 수 있어요."}, {"vn": "Phải xây dựng nền tảng tốt thì thực lực mới tiến bộ.", "hint": "기초/잘/다지다/실력/늘다", "answer": "기초를 잘 다져야 실력이 늘어요."}, {"vn": "Phải đích thân đến xem thì mới biết được bộ mặt thật.", "hint": "직접/가 보다/진짜/모습/알다", "answer": "직접 가 봐야 진짜 모습을 알 수 있어요."}]}, {"num": 36, "term": "-았/었/였더니", "meaning": "Đã... thì ra, hóa ra (kể lại phát hiện bất ngờ sau khi thực hiện hành động ở quá khứ)", "blocks": [["p", "Dùng khi người nói hồi tưởng lại hành động mà chính mình đã làm trong quá khứ."], ["ex", "약을 <b>먹었더니</b> 다 나았어요.", "Tôi uống thuốc vào cái là khỏi hẳn luôn."], ["ex", "생일 축하 카드를 <b>보냈더니</b> 고맙다는 전화가 왔어요.", "Tôi gửi thiệp chúc mừng sinh nhật thì nhận được điện thoại cảm ơn."], ["bq", ["<b>Tìm hiểu thêm | Chủ ngữ ngôi thứ 3 và '-았/었/였더니'</b>", "Khi chủ ngữ của mệnh đề trước là ngôi thứ 3, người nói quan sát thấy", "hành động của người đó đã hoàn thành và nói về kinh nghiệm đó."]], ["ex", "그녀가 질문을 <b>했더니</b> 선생님은 자세히 설명하셨다.", "Khi cô ấy đặt câu hỏi, giáo viên đã giải thích rất chi tiết."], ["ex", "그가 춤을 <b>췄더니</b> 모두 박수를 쳤습니다.", "Khi anh ấy nhảy, tất cả mọi người đều vỗ tay."]], "practice": [{"vn": "Tôi mở cửa sổ ra thì hóa ra bên ngoài đang có tuyết rơi.", "hint": "창문/열다/밖/눈/오다", "answer": "창문을 열었더니 밖에 눈이 오고 있었다."}, {"vn": "Tôi uống thuốc thì hóa ra khỏi bệnh ngay.", "hint": "약/먹다/금방/낫다", "answer": "약을 먹었더니 금방 나았다."}, {"vn": "Tôi đã tập thể dục chăm chỉ thì hóa ra giảm được nhiều cân.", "hint": "열심히/운동하다/살/많이/빠지다", "answer": "열심히 운동했더니 살이 많이 빠졌다."}]}, {"num": 37, "term": "-았/었/였더라면", "meaning": "Nếu như đã... thì (giả định trái với quá khứ, tiếc nuối)", "blocks": [["p", "Về mặt nội dung câu, có 2 trường hợp: Hồi tưởng lại sự việc đã hoàn thành trong quá khứ rồi hối hận, hoặc cảm thấy may mắn."], ["p", "<b>1. Trường hợp cảm thấy hối hận vì đã làm (hoặc không làm) như vậy trong quá khứ: Là lời hối hận rằng nếu không hành động như vậy thì đã có kết quả tốt hơn. Mệnh đề sau thường dùng các dạng như '-(으)ㄹ 것이다', '-(으)ㄹ 걸', '-(으)ㄹ 텐데'. Cụm '-(으)ㄹ 걸 그랬다' biểu thị sự lặp lại của lời nói phía trước với nghĩa là 'nếu... thì đã... rồi'.</b>"], ["ex", "일찍 <b>떠났더라면</b> 어둡기 전에 도착할 텐데.", "Giá mà xuất phát sớm hơn thì đã đến nơi trước khi trời tối rồi."], ["ex", "아파도 <b>참았더라면</b> 좋았을 걸 그랬어요.", "Dù đau nhưng giá mà cố chịu đựng thì đã tốt biết mấy."], ["p", "<b>2. Trường hợp cảm thấy may mắn vì đã làm như vậy trong quá khứ:</b> Là lời nói nghĩ về trường hợp nếu không làm như vậy thì đã gặp chuyện không hay, cho thấy hành động trong quá khứ là việc làm đúng đắn. Mệnh đề sau thường dùng các dạng như '-(으)ㄹ 것이다', '-(으)ㄹ 뻔했다'."], ["ex", "수영을 안 <b>했더라면</b> 굉장히 뚱뚱했을 거예요.", "Nếu hồi đó không tập bơi thì chắc bây giờ tôi đã rất béo rồi."], ["ex", "누리가 도와주지 <b>않았더라면</b> 고생할 뻔했다.", "Nếu Nuri không giúp đỡ thì tôi đã vất vả rồi."]], "practice": [{"vn": "Nếu như đã cố gắng thêm một chút thì có lẽ đã đậu rồi.", "hint": "조금/더/노력하다/합격하다", "answer": "조금만 더 노력했더라면 합격했을 텐데."}, {"vn": "Nếu như lúc đó không gặp người đó thì có lẽ giờ tôi đang sống một cuộc đời khác.", "hint": "그때/사람/만나다/지금/다르다/삶/살다", "answer": "그때 그 사람을 만나지 않았더라면 지금과 다른 삶을 살고 있을 거예요."}, {"vn": "Nếu như đã biết trước thì có lẽ tôi đã chuẩn bị rồi.", "hint": "미리/알다/준비하다", "answer": "미리 알았더라면 준비를 했을 텐데요."}]}, {"num": 38, "term": "-았/었/였던들", "meaning": "Nếu như đã... thì (giả định trái với quá khứ, mang tính văn chương/trang trọng hơn '-더라면')", "blocks": [["p", "Thể hiện sự hối hận về một hành động hoặc trạng thái trong quá khứ. Mệnh đề sau sẽ viết về sự thật trái ngược với thực tế hoặc sự thật không thể xảy ra trên thực tế."], ["ex", "미리 미리 발표 준비를 <b>했던들</b> 이렇게 밤을 새우지 않았을 텐데.", "Giá mà chuẩn bị bài phát biểu từ trước thì đã không phải thức đêm thế này."], ["ex", "점수가 1점만 더 <b>높았던들</b> 떨어지지는 않았을 텐데.", "Giá mà điểm số cao hơn chỉ 1 điểm thôi thì đã không bị trượt rồi."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-았/었/였던들' và '-았/었/였더라면'</b>", "<b>1. -았/었/였던들:</b> Chỉ dùng trong trường hợp nghĩ về sự việc với sự", "hối hận."]], ["ex", "조금만 더 건강에 신경을 <b>썼던들</b> 이만한 일에 쓰러지지는 않았을 텐데.", "Giá mà chú ý đến sức khỏe hơn một chút thì đã không bị gục ngã vì việc chừng này.) *→ Hối hận vì đã không chăm sóc sức khỏe."], ["bq", ["<b>2. -았/었/였더라면:</b> Dùng cho cả trường hợp hối hận về sự việc", "trong quá khứ lẫn trường hợp cảm thấy may mắn."]], ["ex", "네 말을 <b>들었더라면</b> 좋았을 텐데.", "Giá mà nghe lời cậu thì đã tốt rồi.) *→ Đang hối hận vì đã không nghe lời."], ["ex", "조금만 늦게 <b>도착했더라면</b> 기차를 못 탔을 것이다.", "Nếu đến muộn chỉ một chút thôi thì đã không đi kịp chuyến tàu rồi.) *→ Cảm thấy may mắn vì đã đến nơi không bị trễ nên đã đi được tàu."]], "practice": [{"vn": "Nếu như anh ấy đã cẩn thận thêm một chút thì tai nạn đã không xảy ra.", "hint": "조금/더/조심하다/사고/나다", "answer": "그가 조금만 더 조심했던들 사고가 나지 않았을 것이다."}, {"vn": "Nếu như đã đi bệnh viện sớm hơn thì có lẽ đã không nặng thế này.", "hint": "진작/병원/가다/심해지다", "answer": "진작 병원에 갔던들 이렇게 심해지지 않았을 텐데."}, {"vn": "Nếu như lúc đó đã từ bỏ thì đã không có thành công như hôm nay.", "hint": "그때/포기하다/지금/성공/없다", "answer": "그때 포기했던들 지금의 성공은 없었을 것이다."}]}, {"num": 39, "term": "-자", "meaning": "Vừa... thì (ngay sau khi, hành động sau nối tiếp lập tức)", "blocks": [["p", "<b>1. [Sau động từ] Thể hiện sau khi hành động ở mệnh đề trước kết thúc, hành động ở mệnh đề sau lập tức nối tiếp xảy ra.</b>"], ["ex", "문을 <b>열자</b> 새로운 세상이 펼쳐졌다.", "Vừa mở cửa ra, một thế giới mới liền mở ra trước mắt."], ["ex", "한국에는 까마귀 <b>날자</b> 배 떨어진다는 속담이 있다.", "Ở Hàn Quốc có câu tục ngữ \"Thậm chí quạ vừa bay lên thì lê đã rơi\" - Ngẫu nhiên gặp xui xẻo)."], ["p", "<b>2. [Sau một số động từ] Thể hiện nội dung ở mệnh đề trước trở thành nguyên nhân hoặc động cơ cho mệnh đề sau.</b>"], ["ex", "그를 <b>보자</b> 내 심장이 터질 듯이 뛰기 시작했어요.", "Vừa nhìn thấy anh ấy, tim tôi đã bắt đầu đập liên hồi như muốn nổ tung."], ["ex", "차에서 연기가 <b>나자</b> 운전자는 즉시 차에서 튀어나왔다.", "Ngay khi khói bùng lên từ xe, người tài xế liền lập tức lao ra khỏi xe."], ["p", "<b>3. [Sau '이다'] Thể hiện một sự vật/người nào đó sở hữu từ hai tư cách hoặc đặc điểm trở lên.</b>"], ["ex", "준형이는 유명한 <b>배우이자</b> 가수이다.", "Jun-hyeong vừa là diễn viên nổi tiếng vừa là ca sĩ."], ["ex", "활발하고 당찬 것은 나의 <b>장점이자</b> 단점입니다.", "Năng nổ và mạnh mạn vừa là ưu điểm vừa là khuyết điểm của tôi."], ["p", "<b>4. Thể hiện rằng dù hành động hay trạng thái ở mệnh đề trước có diễn ra thì cũng vô ích. Chủ yếu dùng dưới dạng '-아/어 보았자'.</b>"], ["ex", "기다려 <b>봤자</b> 이미 떠난 버스가 돌아오지는 않을 겁니다.", "Dù có chờ đợi thì chuyến xe bus đã rời đi cũng sẽ không quay lại đâu."], ["ex", "아무리 애원해 <b>봤자</b> 지금은 이연이의 마음을 돌릴 수 없을 거야.", "Dù có van xin thế nào thì bây giờ cũng chẳng thể làm thay đổi lòng I-yeon đâu."], ["p", "<b>5. Dùng khi nói về nội dung ở mệnh đề sau dựa trên căn cứ là những gì đã nhìn thấy hoặc nghe thấy. Chủ yếu dùng dưới dạng '보자 하니(까)', '듣자 하니(까)'.</b>"], ["ex", "<b>보자 하니</b> 내일도 날씨가 안 좋을 것 같네요.", "Xem chừng thì có vẻ ngày mai thời tiết cũng không tốt đâu."], ["ex", "<b>듣자 하니</b> 그녀가 드디어 귀국을 한다던데요.", "Nghe nói thì nghe bảo cuối cùng cô ấy cũng về nước rồi đấy."], ["p", "<b>6. Dùng khi thể hiện một tình huống hoàn toàn không thể nhẫn nại thêm được nữa. Chủ yếu dùng dưới dạng '보자 보자 하니까', '듣자 듣자 하니까'.</b>"], ["ex", "<b>보자 보자 하니까</b> 내가 우수워 보이니?", "Nhẫn nhịn xem mãi nên nhòm tôi trông buồn cười lắm à/coi thường tôi đấy à?"], ["ex", "정말 <b>듣자 듣자 하니까</b> 말이 너무 심하신 것 아닌가요?", "Thực sự nhẫn nhịn nghe mãi rồi, không phải lời nói của anh quá đáng lắm rồi sao?"], ["p", "<b>7. [Sau động từ] Dùng khi thể hiện người nói mang một ý đồ, mục đích, hy vọng nào đó.</b>"], ["ex", "몸을 <b>씻자 하니</b> 하필 그때 물이 안 나오지 뭐예요.", "Vừa định tắm rửa thì đúng lúc đó lại bị mất nước chứ nị."], ["ex", "여름옷을 세탁소에 <b>맡기자 하니</b> 날씨가 다시 더워지네요.", "Vừa định mang quần áo mùa hè ra tiệm giặt ủi thì thời tiết lại nóng trở lại."], ["bq", ["<b>Tìm hiểu thêm | Vĩ tố kết thúc câu '-자'</b>", "'-자' còn là vĩ tố kết thúc câu dùng khi rủ rê hoặc yêu cầu đối phương", "cùng làm một việc gì đó."]], ["ex", "우리 주말에 수영하러 <b>가자</b>.", "Cuối tuần này chúng mình cùng đi bơi đi."], ["ex", "시간이 늦었는데 조용히 좀 <b>하자</b>.", "Muộn rồi, chúng mình giữ trật tự một chút đi."]], "practice": [{"vn": "Vừa về đến nhà thì trời bắt đầu đổ mưa.", "hint": "집/도착하다/비/쏟아지다/시작하다", "answer": "집에 도착하자 비가 쏟아지기 시작했다."}, {"vn": "Vừa nghe tin đó thì tôi đã rơi nước mắt.", "hint": "소식/듣다/눈물/나다", "answer": "그 소식을 듣자 눈물이 났다."}, {"vn": "Vừa mở cửa ra thì gió mát ùa vào.", "hint": "문/열다/시원하다/바람/들어오다", "answer": "문을 열자 시원한 바람이 들어왔다."}]}, {"num": 40, "term": "-자마자", "meaning": "Ngay khi vừa... (nhấn mạnh tính tức thời hơn '-자')", "blocks": [["p", "Ngay sau khi sự việc ở mệnh đề trước kết thúc thì sự việc ở mệnh đề sau lập tức xảy ra. Đây là biểu hiện mang tính văn nói (khẩu ngữ), và chủ ngữ ở mệnh đề trước có thể là '나' (tôi). Mệnh đề sau có thể đi kèm với tất cả các thì quá khứ, hiện tại, tương lai."], ["ex", "아침에 <b>일어나자마자</b> 물을 마셔요.", "Sáng ra ngay khi vừa thức dậy là tôi uống nước."], ["ex", "한국에 <b>오자마자</b> 한국어를 배우기 시작했어요.", "Ngay khi vừa đến Hàn Quốc, tôi đã bắt đầu học tiếng Hàn."], ["ex", "졸업<b>하자마자</b> 취직할 거예요.", "Ngay khi vừa tốt nghiệp là tôi sẽ xin việc làm ngay."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-자마자' và '-자'</b>", "Mọi '-자' đều có thể thay thế bằng '-자마자'. Tuy nhiên, có nhiều", "trường hợp '-자마자' không thể thay thế bằng '-자'."]], ["p", "-------------------------------------------------------------------------------- <b>Tiêu chí</b>  <b>Khẩu    </b>Ý nghĩa thời  <b>Ý nghĩa kết   </b>Sự việc   <b>Thì của ngữ / Văn gian (Xảy ra    quả (Sau khi sự thông       mệnh đề viết</b>    ngay sau khi    việc phát       thường<b>    sau</b> xong)<b>         sinh)</b> ------------- --------- --------------- --------------- ----------- ------------ <b>-자</b>       Khẩu ngữ  ◯               ⊙               ×           Quá khứ < Văn viết"], ["p", "<b>-자마자</b>   Khẩu ngữ  ⊙               ×               ◯           Quá khứ, > Văn                                                Hiện tại, viết                                                  Tương lai --------------------------------------------------------------------------------"]], "practice": [{"vn": "Ngay khi tiết học vừa kết thúc, học sinh đã chạy ùa ra ngoài.", "hint": "수업/끝나다/학생들/뛰어나가다", "answer": "수업이 끝나자마자 학생들이 뛰어나갔다."}, {"vn": "Ngay khi vừa mở mắt là tôi kiểm tra điện thoại trước tiên.", "hint": "눈/뜨다/핸드폰/확인하다", "answer": "눈을 뜨자마자 핸드폰부터 확인해요."}, {"vn": "Ngay khi về đến nhà thì hãy đi tắm rửa nhé.", "hint": "집/도착하다/씻다", "answer": "집에 도착하자마자 씻으세요."}]}, {"num": 41, "term": "-자면", "meaning": "Nếu định... thì (giả định về ý định, thường kèm theo điều kiện/lưu ý)", "blocks": [["p", "<b>1. Dùng khi giả định một ý đồ hay mục đích nào đó và diễn đạt rằng theo điều kiện đó thì sẽ thực hiện hành động khác hoặc ở trong một trạng thái khác.</b>"], ["ex", "학교에 <b>가자면</b> 차를 타야 한다.", "Nếu muốn đến trường thì phải đi xe."], ["ex", "시험에 <b>합격하자면</b> 열심히 공부할 수밖에 없다.", "Nếu muốn đỗ kỳ thi thì không còn cách nào khác là phải học tập chăm chỉ."], ["p", "<b>2. Dùng khi đưa ra một tình huống dự kiến và diễn đạt trạng thái theo điều kiện đó.</b>"], ["ex", "달이 <b>뜨자면</b> 얼마나 더 기다려야 할까요?", "Nếu muốn trăng mọc thì còn phải chờ bao lâu nữa đây?"], ["ex", "날이 <b>밝자면</b> 아직 멀었구나.", "Nếu muốn trời sáng thì vẫn còn lâu lắm đấy."], ["p", "<b>3. Không thể dùng chung với các biểu hiện phủ định như '못' hoặc '-지 못하다', '-지 말다'. Nếu muốn dùng biểu hiện phủ định thì phải dùng các dạng phủ định như '안' hoặc '-지 않다'.</b>"], ["ex", "공부를 안 <b>하자면</b> 책을 살 필요가 없다. (O)", "Nếu không muốn học thì không cần mua sách."], ["ex", "공부를 하지 <b>않자면</b> 책을 살 필요가 없다. (O)", "Nếu không muốn học thì không cần mua sách."], ["ex", "공부를 못 <b>하자면</b> 책을 살 필요가 없다. (X)", ""], ["bq", ["<b>Tìm hiểu thêm | So sánh '-자면' và '-(으)려면'</b>", "'-자면' có thể thay thế bằng '-(으)려면' mà không có sự khác biệt lớn", "về mặt ý nghĩa."]], ["ex", "시험에 <b>합격하자면</b> 더 열심히 공부해야 해요. → 시험에 <b>합격하려면</b> 더 열심히 공부해야 해요.", "Nếu muốn đỗ kỳ thi thì phải học tập chăm chỉ hơn."]], "practice": [{"vn": "Nếu định thành công thì không được từ bỏ.", "hint": "성공하다/포기하다", "answer": "성공하자면 포기하지 말아야 한다."}, {"vn": "Nếu định để dành tiền thì phải tiết kiệm.", "hint": "돈/모으다/절약하다", "answer": "돈을 모으자면 절약해야 해요."}, {"vn": "Nếu định giải thích chi tiết thì sẽ mất chút thời gian.", "hint": "자세히/설명하다/시간/걸리다", "answer": "자세히 설명하자면 시간이 좀 걸려요."}]}, {"num": 42, "term": "-(느/으)니만큼", "meaning": "Vì... nên càng, tương xứng với mức độ (thể hiện lý do/mức độ tương ứng)", "blocks": [["p", "<b>1. Thể hiện mệnh đề trước là căn cứ để đo lường/ước lượng mức độ nói ở mệnh đề sau. Giống với nghĩa 'chỉ căn cứ mức độ' của '-ㄴ 만큼' nên có thể thay đổi cho nhau.</b>"], ["ex", "바람이 불고 날씨가 <b>추우니만큼</b> 출발을 연기해 봅시다.", "Vì gió thổi và thời tiết lạnh như thế này, chúng ta hãy hoãn lại việc xuất phát xem sao."], ["ex", "이것은 <b>유물이니만큼</b> 제대로 보존을 해야 할 겁니다.", "Vì cái này là di vật nên chắc chắn phải bảo tồn một cách đàng hoàng."], ["p", "<b>2. Có trường hợp một số danh từ chỉ thời gian hoặc địa điểm được lặp lại dưới dạng '-이/가 -(이)니만큼'. Lúc này, mệnh đề trước thể hiện thời gian hoặc địa điểm đặc biệt mà người nói và người nghe đều hiểu rõ, và mệnh đề sau được thực hiện dựa trên căn cứ đó.</b>"], ["ex", "<b>시대가 시대니만큼</b> 말조심해요. (자유롭게 말할 수 없는, 언론의 자유가 없는 시대)", "Thời buổi này là thời buổi như thế nên hãy cẩn thận lời ăn tiếng nói. - Thời đại không thể tự do nói năng, không có tự do ngôn luận"], ["ex", "<b>때가 때니만큼</b> 한잔하고 싶은 생각이 나는데요. (저녁 퇴근 때)", "Thời điểm này là thời điểm như thế nên tôi lại thấy muốn làm một ly đấy. - Lúc tan làm buổi tối"], ["ex", "<b>나이가 나이니만큼</b> 인생에 대한 고민이 있겠지요. (젊은 시절)", "Lứa tuổi này là lứa tuổi như thế nên chắc là sẽ có những trăn trở về cuộc đời rồi. - Thời trẻ"]], "practice": [{"vn": "Vì càng lớn tuổi nên càng phải chú ý sức khỏe hơn.", "hint": "나이/들다/건강/신경/쓰다", "answer": "나이가 들니만큼 건강에 더 신경을 써야 한다."}, {"vn": "Vì đã nỗ lực chăm chỉ nên chắc sẽ có kết quả tốt.", "hint": "열심히/노력하다/좋다/결과/있다", "answer": "열심히 노력했으니만큼 좋은 결과가 있을 거예요."}, {"vn": "Vì giá đắt nên chất lượng chắc cũng tốt.", "hint": "값/비싸다/품질/좋다", "answer": "값이 비싸니만큼 품질도 좋겠지요."}]}, {"num": 43, "term": "-(으)ㄴ/는 데다가", "meaning": "Không những... mà còn thêm (bổ sung thêm một đặc điểm/tình huống nữa)", "blocks": [["p", "Thể hiện hành động hoặc trạng thái ở mệnh đề sau được bổ sung thêm vào hành động/trạng thái ở mệnh đề trước. Động từ ở mệnh đề trước và mệnh đề sau phải có cùng tính chất, mang tính thống nhất để có thể tổng kết thành một kết luận duy nhất nối bằng '그래서' (Vì vậy)."], ["ex", "수연이는 머리가 <b>좋은 데다가</b> 열심히 해요.", "Su-yeon không những thông minh mà còn chăm chỉ nữa."], ["ex", "정은이는 술을 <b>마시는 데다가</b> 담배도 피워요.", "Jeong-eun không những uống rượu mà còn hút cả thuốc lá nữa."]], "practice": [{"vn": "Đường đã tắc, lại còn thêm mưa nên tôi bị trễ.", "hint": "길/막히다/비/오다/늦다", "answer": "길이 막히는 데다가 비까지 와서 늦었어요."}, {"vn": "Quán đó đã ngon, lại còn rẻ nữa.", "hint": "식당/맛있다/값/싸다", "answer": "그 식당은 맛있는 데다가 값도 싸요."}, {"vn": "Đã bận, lại còn ốm nữa nên rất vất vả.", "hint": "바쁘다/몸/아프다/힘들다", "answer": "바쁜 데다가 몸까지 아파서 힘들었어요."}]}, {"num": 44, "term": "-(으)ㄴ 채(로)", "meaning": "Trong trạng thái... (giữ nguyên trạng thái đó mà làm việc khác)", "blocks": [["p", "Mang nghĩa 'giữ nguyên trạng thái vốn có mà không thay đổi'. Thể hiện hành động ở mệnh đề sau được thực hiện trong trạng thái đang làm hành động ở mệnh đề trước."], ["ex", "아기는 과자를 손에 <b>쥔 채</b> 잠이 들었다.", "Em bé đã ngủ thiếp đi trong khi tay vẫn đang cầm chặt chiếc bánh/kẹo."], ["ex", "문을 열어 <b>놓은 채로</b> 자더니 감기가 들었어요.", "Tôi ngủ trong khi vẫn mở cửa ra nên đã bị cảm lạnh rồi."]], "practice": [{"vn": "Tôi đã ngủ quên trong khi đèn vẫn đang bật.", "hint": "불/켜다/잠/들다", "answer": "불을 켠 채로 잠이 들었어요."}, {"vn": "Anh ấy đã vào phòng trong khi vẫn đang mang giày.", "hint": "신발/신다/방/들어오다", "answer": "신발을 신은 채로 방에 들어왔어요."}, {"vn": "Tôi đã ra ngoài trong khi cửa sổ vẫn đang mở.", "hint": "창문/열다/외출하다", "answer": "창문을 연 채로 외출했어요."}]}, {"num": 45, "term": "-(으)ㄴ/는 대로", "meaning": "Theo như, đúng như (làm đúng theo cách/nội dung đã nêu)", "blocks": [["p", "Gắn vào động từ thể hiện ý nghĩa 'theo đúng hình dáng/trạng thái ở mệnh đề trước' hoặc 'ngay tại thời điểm sự việc nào đó xảy ra'."], ["p", "<b>1. Dùng với nghĩa 'theo đúng hình dáng, trạng thái của động từ phía trước': Dùng chung cho cả động từ hành động và động từ trạng thái.</b>"], ["ex", "선생님이 <b>부르시는 대로</b> 썼습니다.", "Tôi đã viết theo đúng những gì thầy/cô đọc."], ["ex", "<b>생각한 대로</b> 말해 봐요.", "Hãy thử nói theo đúng những gì bạn nghĩ xem nào."], ["p", "<b>2. Dùng với nghĩa 'ngay lập tức tại thời điểm sự việc xảy ra': Chỉ dùng với động từ hành động và chỉ dùng dưới dạng '-는 대로'.</b>"], ["ex", "<b>도착하는 대로</b> 문자를 드리겠습니다.", "Ngay khi đến nơi tôi sẽ gửi tin nhắn cho bạn."], ["ex", "그 사람을 <b>만나는 대로</b> 이 말을 전하겠습니다.", "Ngay khi gặp người đó tôi sẽ chuyển lại lời này."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄴ/는 대로' và '-자마자'</b>", "<b>1. -(으)ㄴ/는 대로:</b> Thể hiện hành động ở mệnh đề trước xảy ra và", "trạng thái đó đang tiếp diễn thì hành động ở mệnh đề sau diễn ra."]], ["ex", "그날 네가 <b>본 대로</b> 자세히 말해 주렴.", "Hãy nói chi tiết đúng như những gì con đã thấy hôm đó nhé."], ["ex", "지금부터는 설명을 <b>들은 대로</b> 선생님을 따라해 보세요.", "Từ bây giờ, hãy thử làm theo giáo viên đúng như những gì đã nghe giải thích nhé."], ["bq", ["<b>2. -자마자:</b> Chỉ chỉ thời điểm khi hành động ở mệnh đề trước vừa", "xảy ra, và thường mang tính ngẫu nhiên."]], ["ex", "그것은 내가 가게에서 <b>보자마자</b> 바로 산 옷이다.", "Đó là bộ quần áo tôi vừa nhìn thấy ở cửa hàng là mua ngay lập tức."], ["ex", "나는 침대에 <b>눕자마자</b> 잠이 들었다.", "Tôi vừa nằm xuống giường là ngủ thiếp đi ngay."], ["p", "<b>3. Dùng trong biểu hiện mạnh mẽ với nghĩa 'đến mức giới hạn không thể làm gì hơn được nữa': Nhập lặp lại một số động từ hành động dưới dạng '-ㄹ 대로'.</b>"], ["ex", "이젠 나도 모르겠다. <b>될 대로</b> 되어라.", "Bây giờ tôi cũng chịu rồi. Ra sao thì ra / Đến đâu thì đến."], ["ex", "<b>노력할 대로</b> 했는데도 일은 안 되었다.", "Tôi đã cố gắng hết mức có thể rồi mà công việc vẫn không thành."]], "practice": [{"vn": "Hãy làm theo đúng như lời tôi nói.", "hint": "제/말하다/따라 하다", "answer": "제가 말하는 대로 따라 하세요."}, {"vn": "Mọi việc đã diễn ra đúng như kế hoạch.", "hint": "계획하다/진행되다", "answer": "계획한 대로 진행됐어요."}, {"vn": "Hãy vẽ tranh đúng như những gì bạn đã thấy.", "hint": "보다/그림/그리다", "answer": "본 대로 그림을 그려 보세요."}]}, {"num": 46, "term": "-(으)ㄴ/는 대신에", "meaning": "Thay vì (thay thế cho vế trước bằng vế sau)", "blocks": [["p", "Thể hiện việc thay thế hành động hay trạng thái của mệnh đề trước bằng cái của mệnh đề sau, hoặc thể hiện sự vật/hành động khác chiếm vị trí đó chứ không phải là thứ vốn dĩ đương nhiên phải có."], ["ex", "윤수는 피아노를 <b>치는 대신에</b> 노래를 했다.", "Yun-su đã hát thay vì chơi piano."], ["ex", "규민이는 부모님을 안 <b>모시는 대신에</b> 용돈을 많이 드린다고 했다.", "Gyu-min nói rằng thay vì không phụng dưỡng bố mẹ thì sẽ biếu nhiều tiền tiêu dùng."]], "practice": [{"vn": "Tôi đã ăn bánh mì thay vì ăn cơm.", "hint": "밥/먹다/빵/먹다", "answer": "밥을 먹는 대신에 빵을 먹었어요."}, {"vn": "Thay vì cho tiền thì hãy dành thời gian cho tôi.", "hint": "돈/주다/시간/내다", "answer": "돈을 주는 대신에 시간을 내 주세요."}, {"vn": "Tôi đã viết thư thay vì nói bằng lời.", "hint": "말/하다/편지/쓰다", "answer": "말로 하는 대신에 편지를 썼어요."}]}, {"num": 47, "term": "-(으)ㄴ/는 반면(에)", "meaning": "Trái lại, ngược lại (đối lập giữa hai vế)", "blocks": [["p", "Thể hiện mệnh đề trước và mệnh đề sau là các thực tế đối lập/trái ngược nhau."], ["ex", "연아네 회사는 업무량은 <b>적은 반면에</b> 월급은 많다.", "Công ty của Yeon-ah khối lượng công việc thì ít nhưng ngược lại lương lại cao."], ["ex", "리카는 한국어를 <b>잘하는 반면에</b> 중국어는 못하는 편이다.", "Rika giỏi tiếng Hàn nhưng ngược lại tiếng Trung thì thuộc dạng kém."]], "practice": [{"vn": "Anh trai thì hoạt bát, trái lại em trai lại trầm tính.", "hint": "형/활발하다/동생/조용하다", "answer": "형은 활발한 반면에 동생은 조용해요."}, {"vn": "Vùng này mùa đông lạnh, trái lại mùa hè lại mát mẻ.", "hint": "지역/겨울/춥다/여름/시원하다", "answer": "이 지역은 겨울에 추운 반면에 여름에는 시원해요."}, {"vn": "Lương thì cao, trái lại công việc lại quá nhiều.", "hint": "월급/많다/일/너무/많다", "answer": "월급은 많은 반면에 일이 너무 많아요."}]}, {"num": 48, "term": "-(으)ㄴ/는데", "meaning": "Nhưng, mà (nêu bối cảnh/hoàn cảnh dẫn dắt cho vế sau)", "blocks": [["p", "<b>1. Giải thích tình huống, chuyển cảnh: Rất hay dùng khi bắt đầu cuộc hội thoại hoặc khi muốn đổi chủ đề một cách nhẹ nhàng.</b>"], ["ex", "오늘 내 <b>생일인데</b> 우리 집에 놀러 와.", "Hôm nay là sinh nhật tớ đấy, sang nhà tớ chơi đi."], ["ex", "감기에 <b>걸렸는데</b> 병원에 안 가요?", "Bị cảm rồi mà không đi bệnh viện sao?"], ["ex", "날씨가 <b>좋은데</b> 산에 갈까요?", "Thời tiết đẹp thế này, chúng mình đi núi nhé?"], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄴ/는데' và '-(으)니까'</b>", "<b>1. -(으)ㄴ/는데:</b> Nói trước về tình huống liên quan đến đối tượng", "để chuẩn bị đưa ra lời nói tiếp theo."]], ["ex", "날씨가 <b>좋은데</b> 산에 갈까요?", "→ Giải thích tình huống thời tiết đẹp rồi rủ đi núi."], ["bq", ["<b>2. -(으)니까:</b> Nhấn mạnh lời nói ở mệnh đề trước chính là nguyên", "nhân, căn cứ, tiền đề cho lời nói ở mệnh đề sau."]], ["ex", "날씨가 <b>좋으니까</b> 산에 갈까요?", "→ Lý do rủ đi núi là vì thời tiết đẹp."], ["p", "<b>2. So sánh: Có thể đổi vị trí mệnh đề trước và mệnh đề sau cho nhau.</b>"], ["ex", "키는 <b>큰데</b> 발은 작아요. (발은 작은데 키는 커요.)", "Chiều cao thì cao nhưng chân lại nhỏ. / Chân nhỏ nhưng chiều cao lại cao."], ["ex", "말하기는 <b>쉬운 데</b> 쓰기는 어려워요. (쓰기는 어려운 데 말하기는 쉬워요.)", "Nói thì dễ nhưng viết thì khó. / Viết thì khó nhưng nói thì dễ."], ["ex", "운동은 <b>잘하는데</b> 노래는 못해요. (노래는 못하는데 운동은 잘해요.)", "Tập thể thao thì giỏi nhưng hát thì kém. / Hát kém nhưng tập thể thao lại giỏi."], ["p", "<b>3. Tương phản/Đối chiếu: Kết quả ở mệnh đề sau xuất hiện trái ngược với kỳ vọng ở mệnh đề trước. Không thể đổi vị trí mệnh đề trước và mệnh đề sau.</b>"], ["ex", "항상 열심히 <b>공부하는데</b> 시험을 못 봐요.", "Lúc nào cũng học hành chăm chỉ nhưng thi cử lại kém."], ["ex", "좋아했던 사람이 <b>있었는데</b> 헤어졌어요.", "Đã từng có người tôi yêu thích nhưng chúng tôi đã chia tay rồi."]], "practice": [{"vn": "Thời tiết đẹp thế này, chúng ta đi leo núi nhé?", "hint": "날씨/좋다/등산/가다", "answer": "날씨가 좋은데 등산하러 갈까요?"}, {"vn": "Tôi thích đồ ăn cay nhưng chồng tôi lại không ăn được.", "hint": "매운 음식/좋아하다/남편/못 먹다", "answer": "저는 매운 음식을 좋아하는데 남편은 못 먹어요."}, {"vn": "Bây giờ ngoài trời đang mưa đấy, bạn có ô không?", "hint": "밖/비/오다/우산/있다", "answer": "지금 밖에 비가 오는데 우산 있으세요?"}]}, {"num": 49, "term": "-(으)ㄴ/는데도", "meaning": "Mặc dù... nhưng vẫn (nhượng bộ, thể hiện điều bất ngờ)", "blocks": [["p", "Là cấu trúc ghép thêm '도' (cũng/ngay cả) mang tính nhấn mạnh vào cấu trúc đối chiếu '-(으)ㄴ/는데'. Dùng khi người nói muốn nhấn mạnh hơn nữa ý nghĩa đối chiếu, tương phản."], ["ex", "열심히 <b>운동하는데도</b> 살을 못 빼요.", "Mặc dù tập thể dục rất chăm chỉ nhưng tôi vẫn không giảm được cân."], ["ex", "시간이 <b>많았는데도</b> 아무것도 못 했어요.", "Mặc dù có nhiều thời gian nhưng tôi vẫn chẳng làm được gì."]], "practice": [{"vn": "Mặc dù đã học chăm chỉ nhưng điểm vẫn không tăng.", "hint": "열심히/공부하다/성적/오르다", "answer": "열심히 공부했는데도 성적이 오르지 않았어요."}, {"vn": "Mặc dù đã uống thuốc nhưng sốt vẫn không hạ.", "hint": "약/먹다/열/떨어지다", "answer": "약을 먹었는데도 열이 안 떨어져요."}, {"vn": "Mặc dù đã giải thích nhiều lần nhưng vẫn không hiểu.", "hint": "여러 번/설명하다/이해하다", "answer": "여러 번 설명했는데도 이해를 못 해요."}]}, {"num": 50, "term": "-(으)ㄴ즉", "meaning": "Xét thấy, nếu xét... thì (văn viết trang trọng, cổ điển)", "blocks": [["p", "Thể hiện mệnh đề trước trở thành lý do hoặc điều kiện cho mệnh đề sau."], ["ex", "튀어가 <b>본즉</b> 그는 병원으로 실려 가고 있었다.", "Chạy lại xem thử thì anh ấy đang được đưa đi bệnh viện rồi."], ["ex", "내가 <b>물은즉</b> 그는 마지못해 대답을 했다.", "Tôi hỏi thì anh ấy mới miễn cưỡng trả lời."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄴ즉' và '-(으)니까'</b>", "<b>1.</b> '-(으)ㄴ즉' có thể thay đổi bằng '-(으)니까'. '-(으)니까' hay", "dùng trong văn nói, còn '-(으)ㄴ즉' phù hợp với từ hán tự và văn phong", "trang trọng, chuẩn mực."]], ["ex", "모든 문제는 자신에게 <b>달린즉</b> 자신이 달라지면 문제는 해결될 것이다. → 모든 문제는 자신에게 <b>달렸으니까</b> 자신이 달라지면 문제는 해결될 것이다.", "Mọi vấn đề đều phụ thuộc vào bản thân nên nếu bản thân thay đổi thì vấn đề sẽ được giải quyết."], ["bq", ["<b>2.</b> Khi kết hợp với danh từ thành dạng <b>'-인즉'</b>, nó mang nghĩa", "'không phải cái gì khác mà chính là/nếu nói là...', dùng để nêu ra", "chủ đề (có thể thay bằng tiểu từ '는/은')."]], ["ex", "<b>사실인즉</b> 옳으신 말씀이지만 그렇게 하기에는 어렵습니다. → <b>사실은</b> 옳으신 말씀이지만 그렇게 하기에는 어렵습니다.", "Nói thực ra thì lời ngài nói là đúng, nhưng làm như thế thì rất khó."]], "practice": [{"vn": "Xét thấy tình hình như vậy nên tôi đành phải đồng ý.", "hint": "사정/그러하다/어쩔 수 없이/동의하다", "answer": "사정이 그러한즉 어쩔 수 없이 동의했다."}, {"vn": "Xét thấy lý lẽ như vậy nên không thể phản bác được.", "hint": "이치/이러하다/반박하다", "answer": "이치가 이러한즉 반박할 수가 없었다."}, {"vn": "Xét thấy tình hình nghiêm trọng nên phải lập tức đưa ra đối sách.", "hint": "사태/심각하다/즉시/대책/세우다", "answer": "사태가 심각한즉 즉시 대책을 세워야 한다."}]}, {"num": 51, "term": "-(으)ㄹ 만큼", "meaning": "Đến mức, chừng nào (mức độ tương xứng)", "blocks": [["p", "<b>1. Thể hiện ý nghĩa 'với số lượng/mức độ giống như cái đó', 'giống như cái đó'.</b>"], ["ex", "음식을 <b>먹을 만큼</b> 가져가세요.", "Hãy lấy thức ăn vừa đủ lượng mình sẽ ăn."], ["ex", "죽을 때까지 쓸 수 <b>있을 만큼</b> 돈을 벌고 싶어요.", "Tôi muốn kiếm tiền nhiều đến mức có thể tiêu đến tận lúc chết."], ["ex", "선생님, 숙제를 할 수 <b>있을 만큼</b> 주세요.", "Thầy/cô ơi, xin hãy cho bài tập về nhà ở mức chúng em có thể làm được thôi ạ."], ["p", "<b>2. '-(으)ㄴ/는 만큼' cũng dùng để thể hiện mệnh đề trước là lý do hoặc căn cứ của mệnh đề sau.</b>"], ["ex", "시간이 <b>이른 만큼</b> 식사보다는 차를 마셨으면 좋겠어요.", "Vì thời gian còn sớm nên thay vì ăn cơm, tôi muốn uống trà hơn."], ["ex", "나는 <b>아는 만큼</b> 느낄 뿐이고, <b>느낀 만큼</b> 보인다는 말을 좋아한다.", "Tôi thích câu nói \"Bạn chỉ cảm nhận được nhiều như những gì bạn biết, và nhìn thấy được nhiều như những gì bạn cảm nhận\"."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄹ 만큼' và '-(으)ㄹ 정도'</b>"]], ["ex", "배고파서 쓰러질 <b>만큼이다</b>. (X)", ""], ["ex", "배고파서 쓰러질 <b>정도이다</b>. (O)", "Đói đến mức muốn gục ngã."], ["bq", ["'-(으)ㄹ 정도' và '-(으)ㄹ 만큼' có nghĩa tương tự nhau nên nhiều", "trường hợp có thể thay đổi cho nhau. Tuy nhiên, cũng có trường hợp", "không thể thay '-(으)ㄹ 만큼' thành '-(으)ㄹ 정도'."]], ["p", "------------------------------------------------------------------------ <b>Cấu trúc</b>  <b>Ý nghĩa</b>               <b>Có thể đứng ở cuối câu không?</b> ------------- ------------------------- -------------------------------- <b>-(으)ㄹ     Giống như cái đó (Y hệt)  Không thể dùng 만큼</b>"], ["p", "<b>-(으)ㄹ     Tương tự như cái đó       Có thể dùng 정도</b> ------------------------------------------------------------------------"]], "practice": [{"vn": "Đó là câu chuyện cảm động đến mức khiến người ta rơi nước mắt.", "hint": "눈물/나다/감동적이다/이야기", "answer": "눈물이 날 만큼 감동적인 이야기였어요."}, {"vn": "Tôi đã cố gắng hết sức trong khả năng có thể.", "hint": "할 수 있다/최선/다하다", "answer": "할 수 있는 만큼 최선을 다했어요."}, {"vn": "Hãy ăn nhiều tùy theo mức bạn muốn ăn.", "hint": "먹다/싶다/드시다", "answer": "먹고 싶은 만큼 드세요."}]}, {"num": 52, "term": "-(으)ㄹ 뿐만 아니라", "meaning": "Không những... mà còn (nhấn mạnh mức độ tăng thêm)", "blocks": [["p", "Thể hiện ý nghĩa 'không chỉ dừng lại ở lời nói/sự việc phía trước mà còn cộng thêm cả những gì lời nói/sự việc phía sau chỉ đến'."], ["p", "<b>1. Khi '뿐' dùng như một danh từ phụ thuộc: Gắn vào động từ hành động, động từ trạng thái, '이다' dưới dạng '-(으)ㄹ 뿐(만) 아니라'. Nếu mệnh đề trước là tích cực thì mệnh đề sau cũng tích cực, nếu mệnh đề trước là tiêu cực thì mệnh đề sau cũng là tiêu cực.</b>"], ["ex", "정은이는 마음이 <b>고울 뿐 아니라</b> 능력도 좋아요.", "Jeong-eun không những có tâm hồn đẹp mà năng lực cũng tốt."], ["ex", "그 식당은 음식이 <b>맛있을 뿐 아니라</b> 종업원도 친절합니다.", "Nhà hàng đó không những thức ăn ngon mà nhân viên cũng thân thiện."], ["p", "<b>2. Khi '뿐' dùng như một trợ từ: Gắn trực tiếp vào danh từ dưới dạng '~뿐(만) 아니라'.</b>"], ["ex", "<b>점심뿐만 아니라</b> 아침도 굶었어요.", "Không chỉ bữa trưa mà bữa sáng tôi cũng bỏ đói."], ["ex", "<b>방청소뿐만 아니라</b> 옷장 청소도 했어요.", "Không chỉ dọn dẹp phòng mà tôi còn dọn dẹp cả tủ quần áo nữa."]], "practice": [{"vn": "Anh ấy không những thông minh mà còn chăm chỉ nữa.", "hint": "똑똑하다/성실하다", "answer": "그는 똑똑할 뿐만 아니라 성실하기도 하다."}, {"vn": "Bộ phim này không những thú vị mà còn mang lại bài học.", "hint": "영화/재미있다/교훈/주다", "answer": "이 영화는 재미있을 뿐만 아니라 교훈도 준다."}, {"vn": "Tôi không chỉ học tiếng Hàn mà còn học cả tiếng Nhật.", "hint": "한국어/일본어/공부하다", "answer": "저는 한국어뿐만 아니라 일본어도 공부해요."}]}, {"num": 53, "term": "-(으)ㄹ 텐데", "meaning": "Chắc là sẽ... đấy (nhưng), dự đoán kèm gợi ý/lo lắng ở vế sau", "blocks": [["p", "Dự đoán [-(으)ㄹ 테] + Tình huống [-(으)ㄴ데]: Chủ ngữ ở mệnh đề sau có thể giống hoặc khác với mệnh đề trước."], ["ex", "시험이 <b>어려울 텐데</b> 열심히 공부해야 해요.", "Kỳ thi chắc là sẽ khó đấy nên phải học hành chăm chỉ vào."], ["ex", "친구들이 <b>기다릴 텐데</b> 빨리 가 보세요.", "Các bạn chắc là đang chờ đấy, hãy mau đi xem sao."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄹ 텐데' và '-(으)ㄹ 테니까'</b>", "<b>1. -(으)ㄹ 텐데:</b> Dùng khi vừa thể hiện sự dự đoán mạnh mẽ của", "người nói về lời nói đứng trước, vừa tiếp nối nói nội dung có liên", "quan đến nó."]], ["ex", "차가 <b>막힐 텐데</b> 지하철을 탑시다.", "Xe chắc là sẽ tắc đấy, chúng ta đi tàu điện ngầm đi."], ["ex", "차가 <b>막힐 텐데</b> 어떡하지요?", "Xe chắc là sẽ tắc đấy, phải làm sao đây?"], ["bq", ["<b>2. -(으)ㄹ 테니까:</b> Dùng khi nhấn mạnh lời nói đứng trước chính là", "điều kiện cho lời nói đứng sau. Khi đặt câu hỏi (câu nghi vấn),", "<b>không thể</b> dùng '-(으)ㄹ 테니까'."]], ["ex", "차가 <b>막힐 테니까</b> 지하철을 탑시다. (O)", "Vì xe chắc chắn sẽ tắc nên chúng ta hãy đi tàu điện ngầm."], ["ex", "차가 막힐 테니까 어떡하지요? (X)", ""], ["p", "------------------------------------------------------------------------ <b>Cấu       </b>Cấu tạo<b>    </b>Ý nghĩa<b>          </b>Có dùng trong câu hỏi trúc<b>                                          được không?</b> ----------- -------------- -------------------- ------------------------ <b>-(으)ㄹ   -(으)ㄹ 테 +   Nói về tình huống dự Có thể dùng (◯) 텐데</b>      -(으)ㄴ데      đoán"], ["p", "<b>-(으)ㄹ   -(으)ㄹ 테 +   Nói về lý do/điều    Không thể dùng (×) 테니까</b>    -(으)니까      kiện dự đoán ------------------------------------------------------------------------"]], "practice": [{"vn": "Trời chắc sẽ mưa đấy, hãy mang theo ô.", "hint": "비/오다/우산/챙기다", "answer": "비가 올 텐데 우산을 챙기세요."}, {"vn": "Chắc bạn mệt lắm đấy, hãy nghỉ ngơi một chút.", "hint": "많이/피곤하다/좀/쉬다", "answer": "많이 피곤할 텐데 좀 쉬세요."}, {"vn": "Đường chắc sẽ tắc đấy, hãy xuất phát sớm.", "hint": "길/막히다/일찍/출발하다", "answer": "길이 막힐 텐데 일찍 출발합시다."}]}, {"num": 54, "term": "-(으)ㄹ까 봐(서)", "meaning": "Vì sợ rằng, e rằng (lo lắng nên làm gì đó để tránh)", "blocks": [["p", "Thể hiện sự lo lắng, e ngại rằng hành động đó sẽ phát sinh hoặc sẽ rơi vào tình huống như vậy."], ["ex", "결혼식에 비가 <b>올까 봐</b> 걱정했어요.", "Tôi đã lo lắng vì sợ trời sẽ mưa vào lễ cưới."], ["ex", "어른 앞에서 <b>실수할까 봐</b> 얼마나 긴장했는지 몰라요.", "Không biết tôi đã căng thẳng thế nào vì sợ sẽ mắc lỗi trước mặt người lớn."]], "practice": [{"vn": "Vì sợ trời mưa nên tôi đã mang theo ô.", "hint": "비/오다/우산/챙기다", "answer": "비가 올까 봐서 우산을 챙겼어요."}, {"vn": "Vì sợ bị trễ nên tôi đã vội vàng xuất phát.", "hint": "늦다/서두르다/출발하다", "answer": "늦을까 봐서 서둘러 출발했어요."}, {"vn": "Vì sợ đứa trẻ bị thương nên tôi đã theo dõi liên tục.", "hint": "아이/다치다/계속/지켜보다", "answer": "아이가 다칠까 봐서 계속 지켜봤어요."}]}, {"num": 55, "term": "-(으)ㄹ라치면", "meaning": "Mỗi khi định... thì (điều kiện lặp lại, cổ điển/ít dùng)", "blocks": [["p", "Dùng khi giả định một cách trừu tượng về sự việc đã trải qua vài lần."], ["ex", "잘 놀다가도 엄마가 밖에 <b>나갈라치면</b> 아기가 울더군요.", "Đang chơi ngoan là thế mà cứ hễ mẹ định đi ra ngoài là em bé lại khóc."], ["ex", "비가 <b>올라치면</b> 반드시 먹구름이 끼어요.", "Cứ hễ trời sắp mưa là nhất định mây đen sẽ kéo đến."]], "practice": [{"vn": "Mỗi khi định rời đi thì trời lại luôn đổ mưa.", "hint": "떠나다/항상/비/오다", "answer": "떠나려니까 항상 비가 왔다."}, {"vn": "Mỗi khi định nói thì cổ họng lại nghẹn lại.", "hint": "말/하다/목/메다", "answer": "말을 하려니까 목이 메었다."}, {"vn": "Mỗi khi định quên thì lại cứ nhớ đến.", "hint": "잊다/자꾸/생각/나다", "answer": "잊으려니까 자꾸 생각이 났다."}]}, {"num": 56, "term": "-(으)ㄹ뿐더러", "meaning": "Không những... mà còn (tương tự '-(으)ㄹ 뿐만 아니라' nhưng trang trọng hơn)", "blocks": [["p", "Thể hiện ý nghĩa 'không chỉ là thực tế ở mệnh đề trước mà cộng thêm vào đó, thực tế ở mệnh đề sau cũng như vậy'. Lúc này, nếu động từ đi trước thể hiện sự tích cực thì động từ đi sau cũng thể hiện sự tích cực, nếu động từ đi trước thể hiện sự tiêu cực thì động từ đi sau cũng thể hiện sự tiêu cực."], ["ex", "그 선수는 개인 기술이 <b>좋을뿐더러</b> 체력도 강합니다.", "Vận động viên đó không những kỹ thuật cá nhân tốt mà thể lực cũng mạnh mẽ."], ["ex", "신인 가수가 노래를 잘 <b>불렀을뿐더러</b> 춤 솜씨도 대단했습니다.", "Ca sĩ tân binh đó không những hát hay mà vũ đạo cũng rất tuyệt vời."]], "practice": [{"vn": "Anh ấy không những chăm chỉ mà năng lực còn xuất sắc nữa.", "hint": "부지런하다/능력/뛰어나다", "answer": "그는 부지런할뿐더러 능력도 뛰어나다."}, {"vn": "Cuốn sách này không những bổ ích mà còn thú vị nữa.", "hint": "책/유익하다/재미/있다", "answer": "이 책은 유익할뿐더러 재미도 있다."}, {"vn": "Bộ phim đó không những cảm động mà diễn xuất của diễn viên còn xuất sắc nữa.", "hint": "영화/감동적이다/배우들/연기/훌륭하다", "answer": "그 영화는 감동적일뿐더러 배우들의 연기도 훌륭했다."}]}, {"num": 57, "term": "-(으)ㄹ세라", "meaning": "Sợ rằng, e rằng (lo sợ điều gì xảy ra nên cẩn thận — cổ điển)", "blocks": [["p", "Thể hiện ý nghĩa mong sao không bị như thế, nhưng lại lo lắng sợ rằng biết đâu chừng sẽ trở nên như thế."], ["ex", "<b>늦을세라</b> 얼마나 열심히 달렸는지 몰라요.", "Tôi không biết là mình đã chạy bán sống bán chết thế nào vì sợ sẽ bị trễ."]], "practice": [{"vn": "Sợ đứa trẻ thức giấc nên tôi bước đi thật khẽ.", "hint": "아이/깨다/조용히/걷다", "answer": "아이가 깰세라 조용히 걸었다."}, {"vn": "Sợ người khác nghe thấy nên tôi đã hạ giọng.", "hint": "남/듣다/목소리/낮추다", "answer": "남이 들을세라 목소리를 낮췄다."}, {"vn": "Sợ đồ ăn bị nguội nên tôi đã vội mang đến ngay.", "hint": "음식/식다/서둘러/가져오다", "answer": "음식이 식을세라 서둘러 가져왔다."}]}, {"num": 58, "term": "-(으)ㄹ수록", "meaning": "Càng... càng (mức độ tăng dần theo)", "blocks": [["p", "<b>1. Thể hiện hành động hoặc trạng thái nào đó ngày càng tăng thêm/được cộng thêm.</b>"], ["ex", "한국말은 <b>공부할수록</b> 재미있습니다.", "Tiếng Hàn càng học càng thấy thú vị."], ["ex", "<b>바쁠수록</b> 운전을 조심해야 합니다.", "Càng bận rộn thì càng phải cẩn thận khi lái xe."], ["p", "<b>2. Kết hợp với '-(으)면' để thể hiện mức độ tăng thêm một cách mạnh mẽ hơn.</b>"], ["ex", "노래를 <b>들으면 들을수록</b> 새로운 느낌이 듭니다.", "Bài hát này càng nghe thì lại càng cảm thấy có một cảm giác mới mẻ."], ["ex", "여행을 <b>하면 할수록</b> 견문이 넓어집니다.", "Đi du lịch càng nhiều thì tầm mắt/kiến thức lại càng mở rộng."]], "practice": [{"vn": "Càng nghĩ thì càng thấy tức giận.", "hint": "생각하다/화/나다", "answer": "생각할수록 화가 났다."}, {"vn": "Càng lên cao thì không khí càng lạnh.", "hint": "높이/올라가다/공기/차갑다", "answer": "높이 올라갈수록 공기가 차가워진다."}, {"vn": "Càng luyện tập thì thực lực càng tiến bộ.", "hint": "연습하다/실력/늘다", "answer": "연습할수록 실력이 늘어요."}]}, {"num": 59, "term": "-(으)ㄹ진대", "meaning": "Nếu xét thấy... thì tất yếu (văn viết trang trọng, hiếm dùng)", "blocks": [["p", "Thừa nhận sự thật ở mệnh đề trước đương nhiên là sẽ như thế, đồng thời thể hiện sự thật ở mệnh đề trước trở thành căn cứ hoặc điều kiện cho lời nói ở mệnh đề sau."], ["ex", "나라를 사랑하고 <b>아낄진대</b> 어찌 군 복무를 마다하겠어요?", "Đã yêu và trân trọng đất nước thì cớ sao lại từ chối việc thực hiện nghĩa vụ quân sự chứ?"], ["ex", "지구의 앞날을 <b>걱정할진대</b> 환경 오염을 어찌 방관하겠어요.", "Đã lo lắng cho tương lai của Trái Đất thì cớ sao lại khoanh tay đứng nhìn ô nhiễm môi trường chứ."]], "practice": [{"vn": "Xét thấy tính mạng con người quý giá thì không được đối xử tùy tiện.", "hint": "사람/목숨/중하다/함부로/하다", "answer": "사람의 목숨이 중할진대 함부로 해서는 안 된다."}, {"vn": "Xét thấy chân lý là như vậy thì ai có thể phủ nhận được.", "hint": "진리/이러하다/부정하다", "answer": "진리가 이러할진대 누가 부정할 수 있으랴."}, {"vn": "Xét thấy tình hình cấp bách thì không có thời gian trì hoãn.", "hint": "사정/급하다/지체하다/시간", "answer": "사정이 급할진대 지체할 시간이 없다."}]}, {"num": 60, "term": "-(으)련마는/(으)련만", "meaning": "Đáng lẽ... nhưng (tiếc nuối, cổ điển)", "blocks": [["p", "<b>1. Dùng khi người nói dự đoán về một thực tế trong tương lai hoặc một thực tế mang tính giả định, mang nghĩa tương đương với '-겠지만' (nhưng/dù... nhưng).</b>"], ["ex", "건물 안에 매점도 <b>있으련마는</b> 눈에 띄지 않는군요.", "Trong tòa nhà chắc là cũng có cửa hàng tiện lợi đấy nhưng chẳng thấy đâu cả."], ["ex", "약을 먹었으면 <b>나으련만</b> 아직도 아프다고 합니다.", "Uống thuốc vào thì chắc là sẽ khỏi đấy nhưng nghe nói hiện tại vẫn còn đau."], ["p", "<b>2. Bổ sung '-(으)련만' vào cấu trúc thể hiện nguyện vọng '-(으)면 좋겠다' thành dạng '-(으)면 좋으련만'.</b>"], ["ex", "일이 잘 <b>해결되면 좋으련만</b> 안 될까 봐 걱정이 됩니다.", "Công việc nếu được giải quyết êm đẹp thì tốt biết mấy, nhưng tôi lại lo là sẽ không được."], ["ex", "주말에는 날씨가 <b>맑았으면 좋으련만</b> 어떨지 모르겠네요.", "Cuối tuần thời tiết nếu đẹp thì tốt biết mấy, nhưng không biết sẽ thế nào đây."]], "practice": [{"vn": "Đáng lẽ nên nghỉ ngơi một chút nhưng việc nhiều nên không nghỉ được.", "hint": "좀/쉬다/일/많다", "answer": "좀 쉬련마는 일이 많아서 쉴 수가 없다."}, {"vn": "Đáng lẽ muốn giúp đỡ nhưng vì không có khả năng nên tiếc nuối.", "hint": "돕다/싶다/능력/없다/안타깝다", "answer": "돕고 싶으련마는 능력이 없어서 안타깝다."}, {"vn": "Đáng lẽ muốn đi nhưng hoàn cảnh không cho phép.", "hint": "가다/싶다/형편/안 되다", "answer": "가고 싶으련마는 형편이 안 된다."}]}, {"num": 61, "term": "-(으)려거든", "meaning": "Nếu định/có ý muốn... thì (điều kiện cho ý định)", "blocks": [["p", "Có nghĩa là nếu muốn thực hiện ý đồ của chủ ngữ thì phải có điều kiện giống như ở mệnh đề sau."], ["ex", "라면을 <b>먹으려거든</b> 물을 끓여요.", "Nếu muốn ăn mì gói thì hãy nấu nước sôi đi."], ["ex", "의사가 <b>되려거든</b> 지금부터 열심히 공부를 해라.", "Nếu muốn trở thành bác sĩ thì từ bây giờ hãy học hành chăm chỉ vào."]], "practice": [{"vn": "Nếu có ý định thành công thì đừng từ bỏ.", "hint": "성공하다/포기하다", "answer": "성공하려거든 포기하지 마세요."}, {"vn": "Nếu định rời đi thì hãy đi ngay bây giờ.", "hint": "떠나다/지금", "answer": "떠나려거든 지금 떠나라."}, {"vn": "Nếu định học thì hãy học cho đến nơi đến chốn.", "hint": "배우다/제대로", "answer": "배우려거든 제대로 배워라."}]}, {"num": 62, "term": "-(으)려니와", "meaning": "Không những... mà còn (tương tự '-거니와' nhưng gắn vào động từ tương lai/ý chí)", "blocks": [["p", "Dùng khi muốn bổ sung thêm nội dung ở mệnh đề trước vào mệnh đề sau, mang ý nghĩa 'sự việc như thế là lẽ đương nhiên rồi, mà lại còn...' đối với sự việc trong tương lai hoặc sự việc mang tính giả định."], ["ex", "동대문 시장은 물건도 <b>많으려니와</b> 값도 쌉니다.", "Chợ Dongdaemun không những hàng hóa nhiều mà giá cả cũng rẻ."], ["ex", "그 여자는 마음씨도 <b>고우려니와</b> 부지런하기도 합니다.", "Người phụ nữ đó không những tấm lòng đẹp mà lại còn chăm chỉ nữa."]], "practice": [{"vn": "Việc này tuy khó khăn nhưng tôi nhất định sẽ làm được.", "hint": "이번 일/힘들다/반드시/해내다", "answer": "이번 일은 힘들려니와 반드시 해내겠습니다."}, {"vn": "Thời gian cũng không đủ nhưng tôi sẽ cố gắng hết sức.", "hint": "시간/부족하다/최선/다하다", "answer": "시간도 부족하려니와 최선을 다하겠습니다."}, {"vn": "Khó khăn tuy nhiều nhưng tôi sẽ không từ bỏ.", "hint": "어려움/많다/포기하다", "answer": "어려움이 많으려니와 포기하지 않겠습니다."}]}, {"num": 63, "term": "-(으)며", "meaning": "Vừa... vừa (hai hành động/trạng thái diễn ra đồng thời)", "blocks": [["p", "<b>1. Liệt kê: Liệt kê từ hai sự thật trở lên mà không liên quan đến thứ tự thời gian, do đó có thể đổi thứ tự giữa mệnh đề trước và mệnh đề sau. Có trường hợp chủ ngữ ở mệnh đề trước và sau giống nhau, cũng có trường hợp khác nhau. Có thể thay thế bằng '-고 (liệt kê)'. Chủ yếu dùng trong văn viết (문어체).</b>"], ["ex", "그 사람은 키가 <b>크며</b> 성격도 좋습니다.", "Người đó dáng cao mà tính cách cũng tốt."], ["ex", "부모님은 고향에 <b>계시며</b> 나는 한국에 삽니다.", "Bố mẹ tôi ở quê, còn tôi thì sống ở Hàn Quốc."], ["p", "<b>2. Hành động đồng thời: Dùng khi thực hiện hai việc cùng một lúc, do đó có thể đổi thứ tự giữa mệnh đề trước và mệnh đề sau. Chủ ngữ ở mệnh đề trước và sau giống nhau, có thể thay thế bằng '-(으)면서 (hành động đồng thời)'. Chủ yếu dùng trong văn viết (문어체).</b>"], ["ex", "동생이 음악을 <b>들으며</b> 공부합니다.", "Em tôi vừa nghe nhạc vừa học bài."], ["ex", "나는 텔레비전을 <b>보며</b> 식사를 해요.", "Tôi vừa xem tivi vừa ăn cơm."], ["ex", "언니가 학교에 <b>다니며</b> 회사에 다녔어요.", "Chị tôi vừa đi học vừa đi làm ở công ty."]], "practice": [{"vn": "Tôi vừa nghe nhạc vừa học bài.", "hint": "음악/듣다/공부하다", "answer": "음악을 들으며 공부해요."}, {"vn": "Chúng tôi vừa uống cà phê vừa trò chuyện.", "hint": "커피/마시다/이야기/나누다", "answer": "커피를 마시며 이야기를 나눴어요."}, {"vn": "Tôi vừa đi bộ vừa sắp xếp lại suy nghĩ.", "hint": "걷다/생각/정리하다", "answer": "걸으며 생각을 정리했어요."}]}, {"num": 64, "term": "-(이)랍시고", "meaning": "Tự cho mình là... (coi thường/mỉa mai việc ai đó tự nhận danh nghĩa gì đó)", "blocks": [["p", "Gắn vào danh từ, dùng khi coi thường, coi nhẹ một thực tế nào đó. Nếu âm cuối của danh từ đứng trước có phụ âm cuối (bachim) thì dùng <b>'-이랍시고'</b>, nếu không có phụ âm cuối thì dùng <b>'-랍시고'</b>."], ["ex", "자기가 <b>책임자랍시고</b> 일은 하지 않고 시키기만 한다.", "Tự cho mình là người chịu trách nhiệm/sếp nên chẳng chịu làm việc gì mà chỉ toàn sai bảo người khác."], ["ex", "나이 많은 <b>사람이랍시고</b> 아무에게나 반말하는 건 좋지 않아요.", "Cậy mình là người nhiều tuổi hơn rồi nói trống không với bất kỳ ai là điều không tốt."]], "practice": [{"vn": "Tự cho mình là người lớn nên nói năng tùy tiện với trẻ con.", "hint": "어른/아이/함부로/말하다", "answer": "자기가 어른이랍시고 아이에게 함부로 말한다."}, {"vn": "Tự cho mình là tiền bối nên chỉ toàn ra lệnh cho hậu bối.", "hint": "선배/후배/명령/하다", "answer": "선배랍시고 후배에게 명령만 한다."}, {"vn": "Tự cho mình là người có nhiều tiền nên coi thường người khác.", "hint": "돈/많다/사람/무시하다", "answer": "돈이 많다랍시고 사람을 무시한다."}]}], "jongeol": [{"num": 1, "term": "-거든요", "meaning": "Diễn đạt/thông báo một cách thân thiện, nhẹ nhàng (giải thích lý do, xác nhận)", "blocks": [["p", "Dùng để xác nhận một sự thật nào đó một cách tích cực để diễn đạt hoặc thông báo một cách thân thiện, nhẹ nhàng."], ["p", "<b>1. Thông báo cho đối phương biết một sự thật hay lý do nào đó một cách tích cực.</b>"], ["ex", "우리나라에는 겨울이 <b>없거든요</b>.", "Ở nước tôi không có mùa đông đâu đấy."], ["ex", "저에게는 좋은 생각이 <b>있거든요</b>.", "Tôi đang có một ý tưởng hay đấy."], ["p", "<b>2. Thể hiện ý nghĩa 'sự thật đó thì đúng là vậy nhưng đại thể sẽ là như thế'.</b>"], ["ex", "그 사람의 생각에도 일리는 <b>있거든요</b>.", "Suy nghĩ của người đó cũng có lý đấy chứ."], ["ex", "책을 쓴 사람의 생각이 이해는 <b>가거든요</b>.", "Tôi thì hiểu được suy nghĩ của người viết sách đấy."], ["p", "<b>3. Biểu thị một sự thật nào đó trở thành tiền đề dẫn dắt câu chuyện tiếp theo.</b>"], ["ex", "아까 서점에 가서 책을 <b>샀거든요</b>. 아주 재미있을 거예요.", "Hồi nãy tôi có đến hiệu sách mua một cuốn sách đấy. Chắc là sẽ hay lắm."], ["ex", "이번 학기에 제가 장학금을 <b>탔거든요</b>. 어머니가 기뻐하실 거예요.", "Học kỳ này tôi nhận được học bổng đấy. Chắc là mẹ sẽ vui lắm."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-거든요' và '-잖아요'</b>"]], ["table", [["<b>Cấu trúc</b>", "<b>Giải thích lý do</b>", "<b>Cung cấp thông tin</b>", "<b>Xác nhận, Nhấn mạnh, Đề xuất</b>"], ["<b>-거 든요</b>", "○ <i>(Lý do người nghe chưa biết)</i>", "○", "×"], ["<b>-잖 아요</b>", "○ <i>(Lý do người nghe đã biết)</i>", "×", "○"]], 1]], "practice": [{"vn": "Ở nước tôi không có mùa đông đâu đấy.", "hint": "우리나라/겨울/없다", "answer": "우리나라에는 겨울이 없거든요."}, {"vn": "Hồi nãy tôi có đến hiệu sách mua một cuốn sách đấy.", "hint": "아까/서점/책/사다", "answer": "아까 서점에 가서 책을 샀거든요."}, {"vn": "Học kỳ này tôi nhận được học bổng đấy.", "hint": "이번 학기/장학금/타다", "answer": "이번 학기에 제가 장학금을 탔거든요."}]}, {"num": 2, "term": "-게 되다", "meaning": "Trở nên..., biến đổi thành... (biến đổi do tác động bên ngoài, không do ý chí)", "blocks": [["p", "<b>1. Biến đổi: Ban đầu không như vậy nhưng sau đó đã trở nên thay đổi.</b>"], ["ex", "처음에는 김치를 못 먹었는데 지금은 <b>먹게 됐어요</b>.", "Mới đầu tôi không ăn được kim chi nhưng bây giờ thì ăn được rồi."], ["ex", "가을이 되면 나뭇잎이 <b>누렇게 됩니다</b>.", "Mùa thu đến thì lá cây chuyển sang màu vàng."], ["p", "<b>2. Bị động: Xảy ra không liên quan đến ý chí của chủ ngữ. Thường đi kèm với lý do nào đó.</b>"], ["ex", "시험을 본 결과 고급반에서 <b>공부하게 되었습니다</b>. *(내가 고급반을 선택한 것이 아님)", "Kết quả kỳ thi khiến tôi được vào học lớp cao cấp - Không phải do tôi tự chọn lớp cao cấp)."], ["ex", "부모님의 일 때문에 지방으로 <b>가게 됐습니다</b>. *(내가 스스로 지방에 가려고 한 것이 아님)", "Vì công việc của bố mẹ nên tôi phải chuyển về tỉnh sống - Không phải tự bản thân tôi muốn đi)."], ["p", "<b>3. Nói khéo/Nói giảm nói tránh: Không nói mang tính khẳng định tuyệt đối. Nói một cách nhẹ nhàng. Giảm bớt trách nhiệm người nói và gánh nặng cho người nghe.</b>"], ["ex", "이번 시험에서 1등을 <b>하게 되었습니다</b>. *(Nói khiêm tốn, hạ mình hơn so với '1등을 했습니다')", "Tôi đã may mắn đứng nhất trong kỳ thi lần này."], ["ex", "쓰레기를 아무 데나 버리면 벌금을 <b>내게 됩니다</b>. *(Cảnh báo nhẹ nhàng hơn so với '벌금을 냅니다')", "Nếu vứt rác bừa bãi thì sẽ bị phạt tiền đấy."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-게 되다' và '-아/어지다'</b>", "cả hai đều là biểu hiện chỉ sự biến đổi. Tuy nhiên diện mạo biến đổi", "có chút khác biệt:"]], ["table", [["<b>Cấu trúc</b>", "<b>Biến đổi</b>", "<b>Lý do biến đổi</b>"], ["<b>-게 되다</b>", "Biến đổi ngoại hình (Kết quả, diện mạo đã biến đổi)", "Do lý do khác tác động"], ["<b>-아/어 지다</b>", "Biến đổi nội tại (Biến đổi bản chất)", "Tự nhiên (Không liên quan ý chí chủ ngữ)"]], 1]], "practice": [{"vn": "Sau khi sống ở Hàn Quốc, tôi đã ăn được kim chi.", "hint": "한국/살다/김치/먹다", "answer": "한국에서 살다 보니 김치를 먹게 됐어요."}, {"vn": "Nhờ luyện tập nhiều nên tiếng Hàn của tôi đã giỏi lên.", "hint": "연습하다/한국어/잘하다", "answer": "많이 연습하다 보니 한국어를 잘하게 됐어요."}, {"vn": "Cuối cùng tôi cũng hiểu được lý do đó.", "hint": "결국/이유/이해하다", "answer": "결국 그 이유를 이해하게 됐어요."}]}, {"num": 3, "term": "-게 하다", "meaning": "Làm cho ai đó..., khiến cho... (sai khiến)", "blocks": [["p", "[Gắn vào động từ] Biểu hiện thể hiện việc bắt hoặc khiến người khác làm một việc nào đó. Vĩ tố '-게' kết hợp với động từ '하다'."], ["p", "<b>1. Thể hiện ý nghĩa bắt ai đó thực hiện một hành vi nào đó, hoặc khiến cho đồ vật vận hành/hoạt động.</b>"], ["ex", "윤수는 떠드는 아이들을 순식간에 <b>조용하게 했다</b>.", "Yun-su đã khiến cho những đứa trẻ đang ồn ào trở nên trật tự trong chớp mắt."], ["ex", "규민이는 고향에서 온 친구를 자기 집에 <b>머물게 했다</b>.", "Gyu-min đã bảo bạn từ quê lên ở lại nhà mình."], ["p", "<b>2. Thể hiện việc cho phép hoặc chấp thuận cho ai đó làm một hành vi nào đó.</b>"], ["ex", "그 사람은 내가 자신의 일에 <b>나서게 하지 않는다</b>.", "Người đó không cho phép tôi xen vào việc của anh ấy."], ["ex", "할머니는 손자를 방에 <b>들어오게 했다</b>.", "Bà đã cho phép cháu trai đi vào phòng."], ["bq", ["<b>Tìm hiểu thêm | Biểu hiện sai khiến ngoài '-게 하다'</b>", "<b>1.</b> Động từ sai khiến tạo thành từ các hậu tố '-이-, -히-, -리-,", "-기-, -우-, -구-, -추-' như '먹이다, 입히다, 울리다' chỉ dùng cho một", "số từ ngữ nhất định, còn '-게 하다' có thể dùng cho mọi từ ngữ.", "<b>2.</b> Việc dùng '-게 하다' và các hậu tố sai khiến có sự khác biệt về", "ý nghĩa như sau:"]], ["ex", "어머니가 아이에게 옷을 <b>입게 한다</b>. <i>(Mẹ bảo đứa trẻ tự mặc áo)</i>", ""], ["ex", "어머니가 아이에게 옷을 <b>입힌다</b>. *(Mẹ trực tiếp mặc áo cho đứa", "trẻ"]], "practice": [{"vn": "Mẹ đã bắt tôi dọn dẹp phòng.", "hint": "엄마/방/청소하다", "answer": "엄마는 내가 방을 청소하게 했다."}, {"vn": "Giáo viên đã cho học sinh nghỉ sớm.", "hint": "선생님/학생/일찍/쉬다", "answer": "선생님은 학생들을 일찍 쉬게 했다."}, {"vn": "Tôi đã làm cho bạn tôi cười.", "hint": "친구/웃다", "answer": "나는 친구를 웃게 했다."}]}, {"num": 4, "term": "-기로 하다", "meaning": "Quyết định (làm gì), dự định sẽ", "blocks": [["p", "Thể hiện sự quyết tâm hoặc hứa hẹn thực hiện hành động mà từ đứng trước biểu thị."], ["ex", "오늘 회의는 다섯 시에 <b>하기로 합시다</b>.", "Hôm nay chúng ta hãy quyết định họp lúc 5 giờ nhé."], ["ex", "나는 이번 방학 때 수영을 <b>배우기로 했다</b>.", "Tôi đã quyết định sẽ học bơi vào kỳ nghỉ lần này."], ["ex", "오늘 저녁에는 친구와 불고기를 <b>먹기로 했다</b>.", "Tối nay tôi đã hẹn ăn thịt nướng với bạn."]], "practice": [{"vn": "Chúng tôi đã quyết định gặp nhau vào cuối tuần.", "hint": "주말/만나다", "answer": "우리는 주말에 만나기로 했어요."}, {"vn": "Tôi đã quyết định bỏ thuốc lá từ năm nay.", "hint": "올해/담배/끊다", "answer": "올해부터 담배를 끊기로 했어요."}, {"vn": "Chúng tôi đã quyết định đi du lịch cùng nhau.", "hint": "같이/여행/가다", "answer": "우리는 같이 여행을 가기로 했어요."}]}, {"num": 5, "term": "-고 말다", "meaning": "...mất, ...luôn (kết thúc đáng tiếc/không mong muốn, hoặc nhẹ nhõm tùy ngữ cảnh)", "blocks": [["p", "<b>1. Tiếc nuối, buồn phiền về kết quả: Dùng khi xuất hiện kết quả không mong muốn.</b>"], ["ex", "오랫동안 사귄 애인과 <b>헤어지고 말았어요</b>.", "Tôi đã lỡ chia tay với người yêu quen nhau thời gian dài mất rồi."], ["ex", "친구와의 약속을 깜빡 <b>잊어버리고 말았다</b>.", "Tôi đã lỡ quên mất cuộc hẹn với bạn mất rồi."], ["ex", "축구 시합에서 우리 팀이 <b>지고 말았어요</b>.", "Trong trận đấu bóng đá, đội chúng tôi đã lỡ thua mất rồi."], ["p", "<b>2. Nhấn mạnh ý chí đối với một kết quả hoặc kết quả tốt.</b>"], ["ex", "대학 시험에 합격하고 <b>말겠습니다</b>.", "Tôi nhất định sẽ thi đỗ đại học."], ["ex", "드디어 너도 결혼하고 <b>마는구나</b>.", "Cuối cùng thì cậu cũng kết hôn rồi đấy nhỉ."], ["ex", "우리 팀이 결국 이기고 <b>말았습니다</b>.", "Đội chúng tôi cuối cùng đã giành chiến thắng rực rỡ."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-고 말다' và '-아/어 버리다'</b>", "Cả hai đều nhấn mạnh hành động. Tuy nhiên thái độ đối với hành động có", "sự khác biệt:"]], ["table", [["<b>Cấu trúc</b>", "<b>Nhấn mạnh hành động</b>", "<b>Tấm lòng sảng khoái/Nhẹ nhõm</b>", "<b>Tấm lòng tiếc nuối/Buồn phiền</b>"], ["<b>-고 말다</b>", "○", "△", "○"], ["<b>-아/어 버 리다</b>", "○", "○", "△"]], 1]], "practice": [{"vn": "Tôi đã lỡ làm mất chiếc ví rồi.", "hint": "지갑/잃어버리다", "answer": "지갑을 잃어버리고 말았어요."}, {"vn": "Cuối cùng anh ấy cũng đã khóc.", "hint": "결국/그/울다", "answer": "결국 그는 울고 말았다."}, {"vn": "Tôi đã lỡ nói ra bí mật đó mất rồi.", "hint": "비밀/말하다", "answer": "그 비밀을 말하고 말았어요."}]}, {"num": 6, "term": "-고 싶다", "meaning": "Muốn (làm gì) (mong muốn của bản thân)", "blocks": [["p", "Nói về hy vọng, hành động mà bản thân mong muốn."], ["ex", "여행을 <b>하고 싶어요</b>.", "Tôi muốn đi du lịch."], ["ex", "새 컴퓨터를 <b>사고 싶어요</b>.", "Tôi muốn mua một chiếc máy tính mới."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-고 싶다' và '-(으)면 좋겠다'</b>", "Cả hai đều thể hiện mong muốn của bản thân. Tuy nhiên có sự khác biệt", "về đối tượng:"]], ["table", [["<b>Cấu trúc</b>", "<b>Hy vọng của bản thân</b>", "<b>Mong muốn đối với người khác</b>"], ["<b>-고 싶다</b>", "○", "×"], ["<b>-(으)면 좋겠다</b>", "○", "○"]], 1]], "practice": [{"vn": "Tôi muốn đi du lịch Hàn Quốc.", "hint": "한국/여행/가다", "answer": "한국으로 여행을 가고 싶어요."}, {"vn": "Tôi muốn nghỉ ngơi ở nhà.", "hint": "집/쉬다", "answer": "집에서 쉬고 싶어요."}, {"vn": "Tôi muốn trở thành giáo viên tiếng Hàn.", "hint": "한국어/선생님/되다", "answer": "한국어 선생님이 되고 싶어요."}]}, {"num": 7, "term": "-ㄴ가/-나 보다", "meaning": "Có lẽ là... (suy đoán chủ quan dựa trên cảm nhận cá nhân)", "blocks": [["p", "Dùng khi có lý do hay căn cứ để suy đoán như vậy, nhưng vì chưa trực tiếp trải nghiệm nên không thể biết chắc chắn. Biểu hiện '-나?', '-가?' thể hiện thái độ nghi vấn của người nói."], ["ex", "(극장 앞에 사람이 많은 걸 보니까) 영화가 <b>재미있나 보다</b>.", "Thấy trước rạp chiếu phim đông người, chắc là phim hay lắm."], ["ex", "(해가 쨍쨍한 걸 보니까) 더울 <b>건가 봐요</b>.", "Thấy nắng chói chang thế này, chắc là sẽ nóng lắm đây."], ["ex", "(어머니의 표정이 안 좋은 걸 보니까) 기분이 안 <b>좋으신가 봅니다</b>.", "Thấy nét mặt của mẹ không tốt, chắc là tâm trạng không vui rồi."], ["ex", "(친구의 시험 점수가 나쁜 걸 보니까) 공부를 안 <b>했나 봅니다</b>.", "Thấy điểm thi của bạn kém, chắc là đã không học bài rồi."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-는 것 같다' và '-나 보다'</b>"]], ["table", [["<b>Cấu t rúc</b>", "<b>Không có căn cứ suy đoán (Suy đoán chủ quan)</b>", "<b>Có căn cứ suy đoán (Suy đoán khách quan)</b>", "<b>Có trải nghiệm (Nói giảm tránh)</b>", "<b>Không có trải nghiệm</b>"], ["<b>-는 것 같 다</b>", "○", "○", "○", "○"], ["<b>-나 보 다</b>", "×", "○", "×", "○"]], 1]], "practice": [{"vn": "Có lẽ trời sắp mưa.", "hint": "비/오다", "answer": "비가 오려나 보다."}, {"vn": "Có lẽ anh ấy đang bận.", "hint": "그/바쁘다", "answer": "그는 바쁜가 보다."}, {"vn": "Có lẽ món ăn này ngon.", "hint": "음식/맛있다", "answer": "이 음식이 맛있나 보다."}]}, {"num": 8, "term": "-는 듯하다", "meaning": "Có vẻ như... (suy đoán dựa trên căn cứ/quan sát)", "blocks": [["p", "[Gắn vào động từ, '있다/없다'] Dùng để suy đoán về thực tế hiện tại. Mang ý nghĩa giống với '그러는 것 같다' (có vẻ như thế)."], ["ex", "<b>부서지는 듯한</b> 소리였다.", "Đó là âm thanh nghe như thể đang vỡ vụn."], ["ex", "화창한 날씨가 오늘 두 사람의 결혼을 축복해 <b>주는 듯합니다</b>.", "Thời tiết nắng đẹp như đang chúc phúc cho cuộc kết hôn của hai người hôm nay."]], "practice": [{"vn": "Có vẻ như trời sắp mưa.", "hint": "비/오다", "answer": "비가 오는 듯하다."}, {"vn": "Có vẻ như anh ấy đã về nhà rồi.", "hint": "그/집/가다", "answer": "그는 집에 간 듯하다."}, {"vn": "Có vẻ như cô ấy rất mệt.", "hint": "그녀/피곤하다", "answer": "그녀는 피곤한 듯하다."}]}, {"num": 9, "term": "-는 중이다", "meaning": "Đang trong quá trình... (hành động đang diễn ra)", "blocks": [["p", "<b>1. [Gắn vào động từ] Biểu hiện thể hiện nội dung phía trước đang được tiến hành.</b>"], ["ex", "용진이는 아끼는 화분에 물을 <b>주는 중이다</b>.", "Yong-jin đang tưới nước cho chậu cây mình yêu thích."], ["ex", "정옥이는 아까부터 기타를 신나게 <b>치는 중이다</b>.", "Jeong-ok đang vui vẻ đánh đàn guitar từ hồi nãy đến giờ."], ["ex", "안내 방송에 따라 시험이 시작되기를 <b>기다리는 중이다</b>.", "Chúng tôi đang chờ kỳ thi bắt đầu theo lời phát thanh hướng dẫn."], ["p", "<b>2. Nếu từ đứng trước là danh từ thì dùng dạng '중이다'.</b>"], ["ex", "장마로 인해 부서진 시설물 <b>복구 중이에요</b>.", "Hiện đang trong quá trình phục hồi các công trình bị hư hại do mùa mưa."], ["ex", "건강을 위해 산 정상까지 열심히 <b>등산 중이다</b>.", "Tôi đang nỗ lực leo núi lên đến đỉnh vì sức khỏe."]], "practice": [{"vn": "Tôi đang ăn cơm.", "hint": "밥/먹다", "answer": "밥을 먹는 중이에요."}, {"vn": "Chúng tôi đang họp.", "hint": "회의/하다", "answer": "회의를 하는 중이에요."}, {"vn": "Anh ấy đang lái xe.", "hint": "그/운전하다", "answer": "그는 운전하는 중이에요."}]}, {"num": 10, "term": "-다니(요)/-라니(요)", "meaning": "Ơ, thế à (ngạc nhiên khi biết một thông tin mới)", "blocks": [["p", "Dùng khi nói về một sự việc gây kinh ngạc, không thể tin được, kỳ lạ, bất ngờ. Có thể đứng ở cuối câu hoặc đi kèm mệnh đề khác phía sau. Có thể dùng cho cả quá khứ, hiện tại, tương lai."], ["ex", "여름에 눈이 <b>오다니요</b>? *(여름에 눈이 오다니 믿을 수 없어요.)", "Tuyết rơi vào mùa hè ư? - Thật không thể tin nổi tuyết lại rơi vào mùa hè."], ["ex", "이번 학기에 시험이 <b>없다니요</b>? *(이번 학기에 시험이 없다니 믿을 수 없어요.)", "Học kỳ này không có thi ư? - Thật không thể tin nổi học kỳ này lại không có kỳ thi."]], "practice": [{"vn": "Ơ, anh ấy đã kết hôn rồi à?", "hint": "그/결혼하다", "answer": "그가 결혼했다니요?"}, {"vn": "Ơ, ngày mai là ngày nghỉ à?", "hint": "내일/휴일이다", "answer": "내일이 휴일이라니요?"}, {"vn": "Ơ, cô ấy đã chuyển nhà rồi à?", "hint": "그녀/이사하다", "answer": "그녀가 이사했다니요?"}]}, {"num": 11, "term": "-(느)ㄴ다면서요?", "meaning": "Nghe nói là... phải không? (xác nhận lại thông tin đã nghe)", "blocks": [["p", "Dùng khi muốn xác nhận lại câu chuyện đã nghe, hoặc nhấn mạnh lại điều mình đã biết. Không dùng '-다면서요?' cho sự thật mình biết quá rõ hoặc sự thật chính bản thân đã trực tiếp trải nghiệm."], ["p", "<b>1. Xác nhận câu chuyện nghe được qua người khác</b>"], ["ex", "가: 설악산은 단풍이 <b>아름답다면서요</b>?", "Nghe nói lá mùa thu ở núi Seorak đẹp lắm phải không?) <i>나: 네, 정말 아름다워요. 한번 가 보세요. </i>(Vâng, đẹp lắm. Bạn hãy đi thử một lần nhé."], ["ex", "가: 정 은 씨가 드디어 <b>결혼하신다면서요</b>?", "Nghe nói anh Jung-eun cuối cùng cũng kết hôn rồi phải không?) <i>나: 그래요? 정말 잘됐어요. </i>(Vậy sao? Thật là tốt quá."], ["p", "<b>2. Xác nhận / nhấn mạnh câu chuyện nghe được từ chính người nghe</b>"], ["ex", "가: 배고프다....... 이야기 확인)", "Bụng đói quá......) <i>나: 아까는 배가 안 <b>고프다면서요</b>? </i>(아까 들은 이야기 확인) (Hồi nãy nghe bảo không đói cơ mà? - Xác nhận lại lời vừa nghe lúc nãy) <i>가: 금방 배가 고파지네요. 우리 뭐 먹을까요? </i>(Tự dưng lại đói ngay đây này. Chúng mình ăn gì đi?) <i>나: 김치찌개요. </i>(Canh kim chi nhé.) <i>가: 네? 전에는 매운 음식을 못 <b>먹는다면서요</b>? </i>(전에 들은 (Hả? Nghe nói trước đây cậu không ăn được đồเผ็ด mà? - Xác nhận lại lời nghe trước đây) <i>나: 이제 먹을 수 있어요. </i>(Bây giờ tớ ăn được rồi."]], "practice": [{"vn": "Nghe nói anh sắp kết hôn phải không?", "hint": "곧/결혼하다", "answer": "곧 결혼한다면서요?"}, {"vn": "Nghe nói món ăn này rất ngon phải không?", "hint": "이 음식/맛있다", "answer": "이 음식이 맛있다면서요?"}, {"vn": "Nghe nói bạn chuyển công ty phải không?", "hint": "회사/옮기다", "answer": "회사를 옮긴다면서요?"}]}, {"num": 12, "term": "-더라고(요)", "meaning": "(Tôi thấy/nghe/trải nghiệm) là... đấy (kể lại điều đã trực tiếp trải nghiệm)", "blocks": [["p", "Dùng khi hồi tưởng lại sự thật bản thân đã trực tiếp cảm nhận (suy nghĩ) trong quá khứ. Dùng khi nói cho người khác biết sự thật mà mình đã trực tiếp trải nghiệm và cảm nhận trong quá khứ."], ["ex", "오늘부터 세일이어서 백화점에 사람이 <b>많더라고요</b>.", "Hôm nay bắt đầu giảm giá nên ở trung tâm thương mại tôi thấy đông người lắm."], ["ex", "어제 날씨가 <b>춥더라고요</b>.", "Hôm qua tôi thấy thời tiết lạnh lắm."], ["ex", "요즘 연아 씨가 공부를 열심히 <b>하더라고요</b>.", "Dạo này tôi thấy cô Yeon-ah học hành chăm chỉ lắm."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-더라고(요)', '-더라', '-더군(요)'</b>", "Đều dùng khi nhớ lại trải nghiệm/sự thật trong quá khứ, nhưng ý nghĩa", "có sự khác biệt nhỏ tùy tình huống:"]], ["table", [["<b>Cấu trúc</b>", "<b>Mức độ cảm thán</b>", "<b>Thông báo thông tin cho người nghe</b>", "<b>Thông tin người nghe đã biết</b>"], ["<b> -더라고 (요)</b>", "×", "○", "×"], ["<b> -더라</b>", "○", "△", "Không liên quan"], ["<b>-더군 (요)</b>", "△", "×", "Không liên quan"]], 1]], "practice": [{"vn": "Hôm qua trời lạnh lắm đấy.", "hint": "어제/춥다", "answer": "어제 날씨가 춥더라고요."}, {"vn": "Món ăn đó ngon lắm đấy.", "hint": "음식/맛있다", "answer": "그 음식이 맛있더라고요."}, {"vn": "Anh ấy làm việc rất chăm chỉ đấy.", "hint": "그/열심히/일하다", "answer": "그가 열심히 일하더라고요."}]}, {"num": 13, "term": "-던데(요)", "meaning": "(Tôi nhớ là) đã... (nhưng) (kể lại trải nghiệm quá khứ, kèm ý bổ sung/tương phản)", "blocks": [["p", "Thể hiện người nói đang thuật lại sự thật mà bản thân từng trải nghiệm như thể đang nhìn thấy trực tiếp."], ["ex", "그 식당 참 <b>좋던데요</b>.", "Nhà hàng đó tôi thấy rất tốt đấy chứ."], ["ex", "운동은 너무 <b>힘들던데요</b>.", "Tập thể thao tôi thấy mệt mỏi lắm đấy."]], "practice": [{"vn": "Lúc nãy trời còn nắng đấy, mà giờ lại mưa.", "hint": "아까/맑다", "answer": "아까는 날씨가 맑던데요."}, {"vn": "Tôi thấy anh ấy có vẻ mệt đấy.", "hint": "그/피곤해 보이다", "answer": "그가 피곤해 보이던데요."}, {"vn": "Món đó tôi ăn rồi, ngon lắm đấy.", "hint": "그 음식/맛있다", "answer": "그 음식이 맛있던데요."}]}, {"num": 14, "term": "-도록 하다", "meaning": "Hãy làm cho được, hãy cố gắng để (mệnh lệnh gián tiếp/khuyên nhủ)", "blocks": [["p", "[Gắn vào động từ] Biểu hiện thể hiện việc bắt hoặc bảo người khác làm một việc nào đó. Kết hợp giữa vĩ tố '-도록' và động từ '하다'."], ["p", "<b>1. Thể hiện ý nghĩa bắt/bảo ai đó thực hiện một hành vi nào đó, hoặc nếu là đồ vật thì làm cho nó hoạt động.</b>"], ["ex", "소영이는 고향에서 온 친구를 자기 집에 <b>머물도록 했다</b>.", "So-young đã bảo bạn đến từ quê ở lại nhà mình."], ["ex", "교수님께서 승현이에게 이 주제로 리포트를 <b>쓰도록 하셨다</b>.", "Giáo sư đã bảo Seung-hyun viết báo cáo về chủ đề này."], ["p", "<b>2. Thể hiện sự cho phép hoặc chấp thuận cho ai đó thực hiện một hành vi nào đó.</b>"], ["ex", "그는 나를 <b>쉬도록 했다</b>.", "Anh ấy đã cho phép tôi nghỉ ngơi."], ["ex", "내가 자신의 일에 <b>나서도록 하지 않는다</b>.", "Anh ấy không cho phép tôi can thiệp vào việc của anh ấy."], ["p", "<b>3. ['하다' dùng dưới dạng mệnh lệnh hoặc rủ rê] Thể hiện việc ra lệnh hoặc khuyên bảo người nghe thực hiện hành động nào đó.</b>"], ["ex", "건물 내에서는 흡연을 <b>삼가도록 하세요</b>.", "Hãy hạn chế hút thuốc trong tòa nhà nhé."], ["ex", "쓰레기는 반드시 분리배출을 <b>하도록 합시다</b>.", "Chúng ta hãy nhất định phân loại rác khi vứt nhé."], ["p", "<b>4. [Dùng dạng '-도록 하겠습니다'] Thể hiện ý chí, quyết tâm của người nói rằng sẽ thực hiện một hành vi nào đó.</b>"], ["ex", "선생님 말씀을 <b>따르도록 하겠습니다</b>.", "Tôi sẽ làm theo lời dặn của thầy/cô ạ."], ["ex", "앞으로 <b>조심하도록 하겠습니다</b>.", "Từ nay về sau tôi sẽ cẩn trọng ạ."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-도록 하다' và '-게 하다'</b>", "Với 용법 1 và 2 (ý nghĩa 1 và 2), có thể thay thế '-도록 하다' bằng", "'-게 하다'. Nhưng với 용법 3 và 4 (ý nghĩa 3 và 4), <b>không thể</b> thay", "thế thành '-게 하다'."]]], "practice": [{"vn": "Hãy cố gắng đến đúng giờ.", "hint": "제시간/오다", "answer": "제시간에 오도록 하세요."}, {"vn": "Hãy cố gắng ăn uống điều độ.", "hint": "규칙적으로/먹다", "answer": "규칙적으로 먹도록 하세요."}, {"vn": "Hãy cố gắng ngủ đủ giấc.", "hint": "충분히/자다", "answer": "충분히 자도록 하세요."}]}, {"num": 15, "term": "-(으)ㄹ 만하다", "meaning": "Đáng để..., xứng đáng... (mức độ chấp nhận được/xứng đáng)", "blocks": [["p", "<b>1. Có giá trị, có ý nghĩa: Dùng dưới dạng '-(으)ㄹ 만하다'.</b>"], ["ex", "서울에서 한번 <b>가볼 만한</b> 곳이 어디예요?", "Ở Seoul nơi đáng để đi thử một lần là ở đâu vậy?"], ["ex", "한글은 세계에 <b>자랑할 만한</b> 문자(글자)입니다.", "Hangeul là chữ viết đáng để tự hào với thế giới."], ["p", "<b>2. Vẫn còn tạm ổn/dùng được: Dùng dưới dạng '아직 -(으)ㄹ 만하다'.</b>"], ["ex", "오래된 물건이지만 <b>아직 쓸 만해요</b>.", "Tuy là đồ cũ nhưng vẫn còn dùng tốt/dùng tạm được."], ["ex", "몇 년 전에流行했던 옷이지만 <b>아직도 입을 만합니다</b>.", "Tuy là quần áo thịnh hành từ mấy năm trước nhưng vẫn còn mặc tốt."]], "practice": [{"vn": "Bộ phim này đáng để xem đấy.", "hint": "영화/보다", "answer": "이 영화는 볼 만해요."}, {"vn": "Món ăn này đáng để thử đấy.", "hint": "음식/먹다", "answer": "이 음식은 먹을 만해요."}, {"vn": "Công việc này cũng đáng để làm.", "hint": "일/하다", "answer": "이 일은 할 만해요."}]}, {"num": 16, "term": "-아/어/여서요", "meaning": "Vì... đấy (giải thích lý do một cách nhẹ nhàng, thân mật)", "blocks": [["p", "<b>1. Mệnh đề sau trở thành nguyên nhân cho mệnh đề trước. Lúc này, động từ ở mệnh đề sau không thể gắn vĩ tố thể hiện thì (thì quá khứ/tương lai), và vĩ tố kết thúc câu ở mệnh đề trước không dùng dạng mệnh lệnh hoặc rủ rê.</b>"], ["ex", "아이가 울고 있어요. 배가 <b>아파서요</b>.", "Đứa trẻ đang khóc. Vì nó bị đau bụng đấy ạ."], ["ex", "나뭇잎이 떨어졌어요. 바람이 심하게 <b>불어서요</b>.", "Lá cây đã rơi xuống rồi. Vì gió thổi mạnh đấy ạ."], ["p", "<b>2. Dùng khi thể hiện các hành động ở mệnh đề trước và mệnh đề sau nối tiếp nhau. Lúc này hành động làm trước đứng ở mệnh đề sau, hành động làm sau đứng ở mệnh đề trước.</b>"], ["ex", "여러 가지 물건을 사요. 시장에 <b>가서요</b>.", "Tôi mua nhiều đồ đạc. Vì đi chợ rồi mới mua đấy ạ."], ["ex", "잠깐만 기다리세요. 여기에 <b>앉아서요</b>.", "Xin hãy đợi một chút. Ngồi ở đây rồi đợi nhé ạ."]], "practice": [{"vn": "Vì tôi mệt quá đấy.", "hint": "너무/피곤하다", "answer": "너무 피곤해서요."}, {"vn": "Vì trời mưa đấy.", "hint": "비/오다", "answer": "비가 와서요."}, {"vn": "Vì tôi không có thời gian đấy.", "hint": "시간/없다", "answer": "시간이 없어서요."}]}, {"num": 17, "term": "-아/어/여지다", "meaning": "Trở nên... (biến đổi tự nhiên, không do tác động bên ngoài)", "blocks": [["p", "Có thể chia thành 2 trường hợp: kết hợp với động từ hành động và kết hợp với động từ trạng thái (tính từ)."], ["p", "<b>1. Kết hợp với động từ hành động: Dùng với nghĩa bị động (피동). Cấu trúc câu sẽ khác với cấu trúc của câu chủ động, điều này được thể hiện qua các trợ từ.</b>"], ["ex", "연필이 좋으니까 글씨가 잘 <b>써진다</b>.", "Vì bút chì tốt nên chữ được viết rất mượt/đẹp."], ["ex", "마침내 소원이 <b>이루어졌다</b>.", "Cuối cùng thì nguyện vọng cũng đã được thực hiện/thành hiện thực."], ["p", "<b>2. Kết hợp với động từ trạng thái (tính từ): Thể hiện quá trình trạng thái tự biến đổi từng chút một.</b>"], ["ex", "놀이터에서 모래 장난을 했더니 금세 옷이 <b>더러워졌다</b>.", "Chơi trò nghịch cát ở sân chơi một lúc mà quần áo đã bị bẩn ngay rồi."], ["ex", "한국 생활에 점점 <b>익숙해지지요</b>?", "Càng ngày càng trở nên quen thuộc với cuộc sống ở Hàn Quốc đúng không?"], ["bq", ["<b>Tìm hiểu thêm | So sánh '-아/어/여지다' và '-게 되다'</b>"]], ["table", [["<b>Cấu trúc</b>", "<b>Thể hiện quá trình biến đổi</b>", "<b>Thể hiện kết quả đã biến đổi</b>"], ["<b>-아 /어/여 지다</b>", "Thể hiện quá trình biến đổi <i>(Thường dùng chung với phó từ như '점점' - dần dần, '차츰' - từ từ)</i>", "×"], ["<b>-게 되다</b>", "×", "Thể hiện kết quả đã biến đổi <i>(Thường dùng chung với phó me như '결국' - rốt cuộc, '마침내' - cuối cùng, '드디어' - cuối cùng)</i>"]], 1]], "practice": [{"vn": "Trời đang dần trở nên ấm áp.", "hint": "날씨/점점/따뜻하다", "answer": "날씨가 점점 따뜻해져요."}, {"vn": "Tiếng Hàn của tôi đang dần tốt lên.", "hint": "한국어/점점/좋다", "answer": "한국어가 점점 좋아져요."}, {"vn": "Căn phòng đã trở nên sạch sẽ.", "hint": "방/깨끗하다", "answer": "방이 깨끗해졌어요."}]}, {"num": 18, "term": "-았/었/였으면 하다/좋겠다", "meaning": "Ước gì..., mong rằng... (mong muốn về một điều chưa xảy ra)", "blocks": [["p", "Thể hiện nguyện vọng, mong muốn tha thiết về một sự việc trong tương lai."], ["ex", "운동을 잘 <b>했으면 좋겠어요</b>.", "Tôi ước gì mình tập thể thao giỏi."], ["ex", "여행이나 <b>갔으면 좋겠다</b>.", "Giá mà đi du lịch thì tốt biết mấy."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)면 하다' và '-(으)면 좋겠다'</b>", "'-았/었/였으면 좋겠다' có thành tố '-았/었/였-' và '-겠-'. Ở đây chúng", "không mang ý nghĩa hoàn thành hay phỏng đoán hành động, mà dùng để thể", "hiện nguyện vọng một cách mạnh mẽ hơn. Đặc biệt, việc chèn thêm một âm", "tiết giúp câu mang sắc thái biểu đạt mạnh mẽ hơn. So với '-(으)면", "하다' thì '-(으)면 좋겠다' thể hiện nguyện vọng và hy vọng mạnh mẽ hơn", "hẳn."]]], "practice": [{"vn": "Ước gì tôi được đi du học.", "hint": "유학/가다", "answer": "유학을 갔으면 좋겠어요."}, {"vn": "Mong rằng ngày mai trời nắng đẹp.", "hint": "내일/날씨/좋다", "answer": "내일 날씨가 좋았으면 좋겠어요."}, {"vn": "Ước gì tôi có nhiều thời gian hơn.", "hint": "시간/많다", "answer": "시간이 더 많았으면 좋겠어요."}]}, {"num": 19, "term": "-잖아(요)", "meaning": "Chẳng phải là... hay sao, đúng là... mà (nhắc lại điều người nghe đã biết)", "blocks": [["p", "<b>1. Lý do: Nói về lý do mà người nghe cũng đã biết.</b>"], ["ex", "가: 발이 참 크네요. *(Bàn chân to thật đấy.)", "나: 키가 <b>크잖아요</b>. *(Thì chiều cao cao mà - Ai cũng thấy cao rồi)."], ["ex", "가: 오늘 비가 오겠네요. *(Hôm nay chắc là mưa đấy.)", "나: 왜요? <i>(Sao thế ạ?) </i>가: 하늘을 좀 보세요. 구름이 <b>끼었잖아요</b>. *(Hãy nhìn bầu trời xem. Mây kéo đến rồi kìa - Người nghe nhìn thấy mây)."], ["p", "<b>2. Xác nhận: Dùng khi nói nhằm nhấn mạnh. Nếu nói quá mạnh thì nghe có vẻ như đang giận dữ.</b>"], ["ex", "가: 내 책이 어디 있지? *(Sách của tớ ở đâu nhỉ?)", "나: 여기 <b>있잖아</b>. *(Ở đây chứ đâu!"], ["ex", "가: 결혼식이 언제라고 했지? *(Lễ cưới bảo là khi nào ấy nhỉ?)", "나: 또 잊어버렸니? 내가 몇 번이나 <b>말했잖아</b>. *(Lại quên rồi à? Tớ đã nói bao nhiêu lần rồi cơ mà!"], ["p", "<b>3. Đề xuất: Dạng '-(으)면 되잖아(요)'</b>"], ["ex", "가: 헤어지게 돼서 섭섭해요. *(Phải chia tay nên tớ buồn quá.)", "나: 자주 연락하면 <b>되잖아요</b>. *(Thì thường xuyên liên lạc là được mà."], ["ex", "가: 주말에 혼자 있으면 심심해. *(Cuối tuần ở một mình chán quá.)", "나: 책을 읽으면 <b>되잖아</b>. *(Thì đọc sách là được chứ sao."]], "practice": [{"vn": "Hôm nay là sinh nhật tôi mà.", "hint": "오늘/생일이다", "answer": "오늘 제 생일이잖아요."}, {"vn": "Tôi đã nói với anh rồi mà.", "hint": "제가/말하다", "answer": "제가 말했잖아요."}, {"vn": "Trời đang mưa mà, sao lại ra ngoài?", "hint": "비/오다", "answer": "비가 오잖아요."}]}, {"num": 20, "term": "-지 말다", "meaning": "Đừng (làm gì) (mệnh lệnh phủ định)", "blocks": [["p", "[Gắn vào động từ] Biểu hiện thể hiện sự cấm đoán một hành vi nào đó."], ["p", "<b>1. Thể hiện việc không cho phép người nghe thực hiện một hành vi nào đó.</b>"], ["ex", "여기서 사진을 찍지 <b>마세요</b>.", "Xin đừng chụp ảnh ở đây."], ["ex", "환경 오염을 시키지 <b>맙시다</b>.", "Chúng ta đừng làm ô nhiễm môi trường."], ["p", "<b>2. '-지 말다' chỉ dùng trong câu mệnh lệnh và câu rủ rê, nếu dùng trong câu trần thuật và câu nghi vấn là sai. Tuy nhiên, đứng trước các động từ mang ý nghĩa cầu nguyện, mong ước như '바라다, 기도하다, 빌다' thì có thể là trường hợp ngoại lệ.</b>"], ["p", "<b>3. Khi ra lệnh cho công chúng, độc giả chung chứ không phải một người nghe cụ thể trong văn bản, khẩu hiệu, tiêu đề, v.v., người ta cũng dùng biểu hiện như '-지 말라'.</b>"], ["p", "<b>4. Khi truyền đạt, trích dẫn gián tiếp nội dung mệnh lệnh cho người khác, nhất định phải dùng dạng '-지 말라고'.</b>"], ["ex", "어머니께서 너무 늦게 다니지 <b>말라고</b> 하셨어.", "Mẹ đã dặn là đừng có đi lại về quá muộn."], ["p", "<b>5. Khi kết hợp với vĩ tố dạng mệnh lệnh '-아, -아라', nó không biến thành '말아, 말아라' mà trở thành '마, 마라'.</b>"], ["p", "<b>6. Sau '-지' có thể gắn thêm các trợ từ như '를', '도', '는' để nhấn mạnh ý nghĩa.</b>"]], "practice": [{"vn": "Đừng lo lắng.", "hint": "걱정하다", "answer": "걱정하지 마세요."}, {"vn": "Đừng hút thuốc ở đây.", "hint": "여기/담배/피우다", "answer": "여기서 담배를 피우지 마세요."}, {"vn": "Đừng quên mang theo ô.", "hint": "우산/가져가다/잊다", "answer": "우산 가져가는 것을 잊지 마세요."}]}, {"num": 21, "term": "-지 않다", "meaning": "Không... (phủ định)", "blocks": [["p", "<b>1. [Gắn vào động từ] Phủ định một cách trung lập, đơn thuần về hành vi phía trước, hoặc thể hiện chủ ngữ không có ý chí, ý đồ thực hiện hành vi phía trước.</b>"], ["ex", "우리 회사는 토요일에 일하지 <b>않는다</b>.", "Công ty chúng tôi không làm việc vào thứ Bảy."], ["ex", "이번 방학에는 고향에 돌아가지 <b>않을 거예요</b>.", "Kỳ nghỉ lần này tôi sẽ không trở về quê hương."], ["p", "<b>2. [Gắn vào tính từ] Dùng khi phủ định đơn thuần về trạng thái phía trước.</b>"], ["ex", "전 배고프지 <b>않아요</b>.", "Tôi không đói."], ["ex", "이 책은 어렵지 <b>않다</b>.", "Cuốn sách này không khó."], ["p", "<b>3. '아니/안' hoặc '-지 않다' không thể dùng chung để phủ định các động từ thể hiện sự nhận thức của chủ ngữ như '알다' (biết), '깨닫다' (nhận ra), '지각하다' (nhận thức), '인식하다' (ý thức). Vì những trạng thái này diễn ra tự nhiên, không liên quan đến ý chí của chủ ngữ.</b>"], ["p", "<b>4. Không thể dùng chung với các động từ như '견디다' (chịu đựng) vốn thể hiện năng lực gánh vác việc gì đó của chủ ngữ về mặt ý nghĩa. Trong trường hợp này phải dùng '못' hoặc '-지 못하다'.</b>"]], "practice": [{"vn": "Tôi không thích cà phê.", "hint": "커피/좋아하다", "answer": "커피를 좋아하지 않아요."}, {"vn": "Trời hôm nay không lạnh.", "hint": "오늘/날씨/춥다", "answer": "오늘 날씨가 춥지 않아요."}, {"vn": "Anh ấy không đến trường.", "hint": "그/학교/오다", "answer": "그는 학교에 오지 않아요."}]}, {"num": 22, "term": "-(으)ㄴ/는/(으)ㄹ 걸(요)", "meaning": "Chắc là... đấy (phỏng đoán khá chắc chắn); hoặc tiếc nuối 'giá mà đã...'", "blocks": [["p", "Thể hiện ý chí, cảm xúc, sự đánh giá,... của người nói đối với một hành động hoặc trạng thái nào đó một cách mạnh mẽ, tự tin. Gắn vào động từ hành động, động từ trạng thái, '이다'. Tùy theo vĩ tố thì kết hợp mà phân loại như sau:"], ["p", "<b>1. Dùng với nghĩa nhấn mạnh, khẳng định tuyệt đối</b>"], ["ex", "오늘은 거기까지 갈 시간이 <b>없는걸</b>.", "Hôm nay làm gì còn thời gian để đi đến đó nữa cơ chứ."], ["ex", "구름을 보니 비가 <b>오겠는걸</b>.", "Nhìn mây thế này thì chắc chắn là trời sắp mưa rồi đấy."], ["p", "<b>2. Dùng khi giải thích suy nghĩ, chủ trương của bản thân hoặc đưa ra lý do trong cuộc hội thoại</b>"], ["ex", "가: 언제 결혼하세요? *(Khi nào bạn kết hôn thế?)", "나: 벌써 <b>했는걸요</b>. *(Tôi đã kết hôn từ lâu rồi mà."], ["p", "<b>3. '-(으)ㄹ 걸' gắn vào động từ hành động thể hiện sự hối hận hoặc tiếc nuối về việc trong quá khứ</b>"], ["p", "① Thể hiện trong quá khứ thực tế đã không thể làm như vậy."], ["p", "② Cụm '-(으)ㄹ 걸' trong câu mang nghĩa 'hối hận vì đã không làm như thế này...', tương đương với phần 'lẽ ra phải làm như thế...'."], ["p", "③ Dạng phủ định dùng '-지 말 걸'."], ["p", "④ Khi không phải lời nói một mình mà nói với người lớn tuổi/cần tôn trọng, dùng dạng '-(으)ㄹ 걸 그랬어요'."], ["ex", "좀 더 열심히 <b>공부할걸</b>.", "Biết thế mình đã học hành chăm chỉ hơn rồi."], ["ex", "그날 술을 마시고 운전하지 <b>말걸</b>.", "Biết thế ngày hôm đó mình đã không uống rượu rồi lái xe."], ["bq", ["<b>Tìm hiểu thêm | Mối quan hệ giữa chủ ngữ và '-ㄹ 걸'</b>", "Khi thể hiện sự hối hận hoặc tiếc nuối, tiền đề giả định '-(으)면' có", "thể làm mệnh đề đứng trước.", "<b>1.</b> Chủ ngữ có thể là ngôi thứ 3.", "<b>2.</b> Dùng dưới dạng '-(으)면 좋을 걸', '-(았/었/였)으면 좋(았)을", "걸', '-았/었/였더라면 좋(았)을 걸'."]], ["ex", "그 일은 박 선생이 좀 직접 하면 <b>좋을걸</b>.", "Việc đó giá mà thầy Park trực tiếp làm thì tốt biết mấy."], ["ex", "다른 사람들에게 좀 친절했더라면 인상이 <b>좋았을걸</b>.", "Giá mà thân thiện với người khác hơn một chút thì ấn tượng đã tốt rồi."], ["p", "<b>4. Trường hợp '-(으)ㄹ 걸' thể hiện sự phỏng đoán</b>"], ["p", "① Khi chủ ngữ là ngôi thứ 3."], ["p", "② Khi dùng chung với các phó từ chỉ thời gian trong tương lai."], ["p", "③ Khi kết hợp với vĩ tố thì quá khứ '-았/었/였-' thành dạng '-았/었/였을 걸'."], ["ex", "아마 철수는 내일 도서관에 <b>있을걸</b>.", "Có lẽ ngày mai Cheol-soo sẽ ở thư viện đấy."], ["ex", "지리산에 폭설이 <b>내렸을걸</b>.", "Chắc là tuyết rơi dày ở núi Jiri rồi đấy."], ["bq", ["<b>Tìm hiểu thêm | Chủ ngữ ngôi thứ 1 và '-ㄹ 걸'</b>", "Khi chủ ngữ là ngôi thứ 1, người nói đang nói bằng cách khách quan hóa", "chính bản thân mình."]], ["ex", "내일은 내가 집에 <b>없을걸</b>. *(Chắc ngày mai tớ không có ở nhà", "đâu)."], ["ex", "나라도 화를 <b>냈을걸</b>. <i>(Là tớ thì tớ cũng nổi giận thôi).</i>", ""]], "practice": [{"vn": "Anh ấy chắc sẽ đến đấy.", "hint": "그/오다", "answer": "그가 올걸요."}, {"vn": "Ngày mai chắc sẽ mưa đấy.", "hint": "내일/비/오다", "answer": "내일 비가 올걸요."}, {"vn": "Món đó chắc sẽ ngon đấy.", "hint": "그 음식/맛있다", "answer": "그 음식이 맛있을걸요."}]}, {"num": 23, "term": "-(으)ㄴ/는 편이다", "meaning": "Thuộc dạng, có xu hướng là (tính chất/xu hướng chung)", "blocks": [["p", "<b>1. Dùng khi nói rằng thay vì khẳng định tuyệt đối một thực tế nào đó, nhìn chung nó gần hoặc thuộc về một phía nào đó hơn.</b>"], ["ex", "그 사람은 한국어를 <b>잘하는 편이다</b>.", "Người đó thuộc dạng giỏi tiếng Hàn."], ["ex", "저는 좀 일찍 <b>자는 편이에요</b>.", "Tôi thuộc dạng ngủ khá sớm."], ["ex", "주말에는 거의 낮잠을 <b>자는 편이에요</b>.", "Cuối tuần tôi thuộc dạng hầu như toàn ngủ nướng."], ["ex", "제 동생은 또래에 비해서 키가 <b>작은 편이에요</b>.", "Em tôi thuộc dạng thấp so với bạn bè đồng lứa."], ["p", "<b>2. Khi nói về tình huống trong quá khứ, dùng dạng '-(으)ㄴ 편이다' đối với động từ.</b>"], ["ex", "나는 다른 친구에 비해 시험을 <b>못 본 편이다</b>.", "Tôi thuộc dạng thi kém hơn so với các bạn khác."], ["ex", "저는 발표를 <b>잘한 편이에요</b>.", "Tôi thuộc dạng đã phát biểu tốt."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-은 편이다', '-ㄴ 편이다', '-는 편이다'</b>", "<b>1. -은 편이다:</b> Gắn sau động từ và tính từ có phụ âm cuối (bachim),", "ngoại trừ 'ㄹ'."]], ["ex", "그는 인기가 <b>많은 편이다</b>. *(Anh ấy thuộc dạng được yêu thích", "nhiều)."], ["ex", "오늘은 밥을 많이 <b>먹은 편이다</b>. *(Hôm nay thuộc dạng đã ăn nhiều", "cơm)."], ["bq", ["<b>2. -ㄴ 편이다:</b> Gắn sau '이다', động từ và tính từ không có phụ âm", "cuối hoặc có phụ âm cuối là 'ㄹ', hoặc đứng sau '-으시-'."]], ["ex", "나는 <b>적극적인 편이다</b>. <i>(Tôi thuộc dạng người tích cực).</i>", ""], ["ex", "그녀는 키가 <b>큰 편이다</b>. <i>(Cô ấy thuộc dạng cao ráo).</i>", ""], ["bq", ["<b>3. -는 편이다:</b> Gắn sau tính từ, động từ kết thúc bằng '있다',", "'없다', '계시다' hoặc các từ kết thúc bằng '있다', '없다'."]], ["ex", "그 책은 <b>재미있는 편이다</b>. <i>(Cuốn sách đó thuộc dạng hay).</i>", ""], ["ex", "지갑에 돈이 <b>없는 편이다</b>. <i>(Trong ví thuộc dạng không có tiền).</i>", ""]], "practice": [{"vn": "Tôi thuộc dạng người ít nói.", "hint": "저/말/적다", "answer": "저는 말이 적은 편이에요."}, {"vn": "Quán này thuộc dạng rẻ.", "hint": "식당/싸다", "answer": "이 식당은 싼 편이에요."}, {"vn": "Anh ấy có xu hướng ăn nhiều.", "hint": "그/많이/먹다", "answer": "그는 많이 먹는 편이에요."}]}, {"num": 24, "term": "-(으)ㄴ/는/(으)ㄹ 것 같다", "meaning": "Có vẻ như là..., hình như là... (suy đoán dựa trên cảm nhận chung)", "blocks": [["p", "Dùng chung với động từ '같다' để thể hiện sự phỏng đoán mạnh mẽ của người nói về một sự thật hay trạng thái nào đó. Đối với động từ hành động: quá khứ dùng '-(으)ㄴ 것 같다', hiện tại dùng '-는 것 같다', tương lai dùng '-(으)ㄹ 것 같다'."], ["ex", "비가 <b>올 것 같아요</b>.", "Có vẻ như trời sắp mưa."], ["ex", "음식 매우 <b>맛있을 것 같군요</b>.", "Món ăn có vẻ rất ngon đấy nhỉ."], ["ex", "수업이 벌써 <b>끝난 것 같습니다</b>.", "Buổi học có vẻ như đã kết thúc rồi."]], "practice": [{"vn": "Hình như trời sắp mưa.", "hint": "비/오다", "answer": "비가 올 것 같아요."}, {"vn": "Có vẻ như món này ngon.", "hint": "이 음식/맛있다", "answer": "이 음식이 맛있을 것 같아요."}, {"vn": "Hình như anh ấy đang bận.", "hint": "그/바쁘다", "answer": "그가 바쁠 것 같아요."}]}, {"num": 25, "term": "-(으)ㄹ 리가 없다", "meaning": "Không có lý gì mà... (phủ định mạnh mẽ một khả năng)", "blocks": [["p", "Dùng khi nói về việc không có khả năng xảy ra như thế, việc không thể tin được, việc không thể có, việc kỳ lạ, v.v."], ["ex", "여름에 눈이 <b>올 리가 없어요</b>.", "Mùa hè thì làm gì có lý nào lại có tuyết rơi."], ["ex", "밤에 해가 <b>뜰 리가 없어요</b>.", "Ban đêm thì làm gì có lý nào mặt trời lại mọc."]], "practice": [{"vn": "Anh ấy không có lý gì mà không biết chuyện đó.", "hint": "그/그 일/모르다", "answer": "그가 그 일을 모를 리가 없어요."}, {"vn": "Món ăn này không có lý gì mà dở được.", "hint": "이 음식/맛없다", "answer": "이 음식이 맛없을 리가 없어요."}, {"vn": "Cô ấy không có lý gì mà quên được ngày đó.", "hint": "그녀/그날/잊다", "answer": "그녀가 그날을 잊을 리가 없어요."}]}, {"num": 26, "term": "-(으)ㄴ/는/(으)ㄹ 모양이다", "meaning": "Có vẻ như, dường như là... (suy đoán dựa trên dấu hiệu quan sát)", "blocks": [["p", "Dùng khi người nói phỏng đoán dựa trên hình dáng, tình trạng khách quan của sự vật."], ["ex", "밖에 비가 <b>오는 모양입니다</b>.", "Bên ngoài có vẻ như trời đang mưa."], ["ex", "차가 <b>밀리는 모양입니다</b>.", "Xe có vẻ như đang bị tắc."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-는 모양이다' và '-는 것 같다'</b>", "<b>1. -는 모양이다:</b> Người nói phỏng đoán dựa trên căn cứ thực tế", "khách quan.", "<b>2. -는 것 같다:</b> Có sự can thiệp của sự phỏng đoán chủ quan từ", "người nói."]]], "practice": [{"vn": "Có vẻ như trời sắp mưa.", "hint": "비/오다", "answer": "비가 올 모양이에요."}, {"vn": "Dường như anh ấy rất bận.", "hint": "그/바쁘다", "answer": "그가 바쁜 모양이에요."}, {"vn": "Có vẻ như cô ấy đã về nhà rồi.", "hint": "그녀/집/가다", "answer": "그녀가 집에 간 모양이에요."}]}, {"num": 27, "term": "-(으)ㄹ 뻔하다", "meaning": "Suýt nữa thì... (may mắn tránh được điều gì đó không mong muốn)", "blocks": [["p", "<b>1. May mắn: Tình huống nguy hiểm đã xảy ra. Tuy nhiên dùng khi thật may vì đã không trở nên như vậy.</b>"], ["ex", "그릇을 닦다가 <b>깰 뻔했어요</b>. *(깨지 않았다.)", "Lúc rửa bát tôi suýt chút nữa làm vỡ. - Thực tế không vỡ)."], ["ex", "뛰어가다가 <b>넘어질 뻔했다</b>. *(넘어지지 않았다.)", "Đang chạy tôi suýt chút nữa bị ngã. - Thực tế không ngã)."], ["ex", "길을 건너다가 교통사고가 <b>날 뻔했어요</b>. *(교통사고가 나지 않았다.)", "Lúc sang đường tôi suýt chút nữa gặp tai nạn giao thông. - Thực tế không xảy ra tai nạn)."], ["ex", "지갑을 떨어뜨려서 <b>잃어버릴 뻔했어</b>. *(잃어버리지 않았다.)", "Tôi đánh rơi ví nên suýt chút nữa bị mất. - Thực tế không mất)."], ["p", "<b>2. Tiếc nuối: Giá mà trở nên như thế thì tốt biết mấy. Tuy nhiên dùng khi tiếc nuối vì đã không trở nên như vậy.</b>"], ["ex", "작년에 유학 <b>갈 뻔했는데</b> 갑자기 사정이 생겼어요. *(유학을 못 갔다.)", "Năm ngoái tôi suýt chút nữa đi du học rồi nhưng đột nhiên lại có biến cố. - Thực tế không đi du học được)."], ["ex", "우리 팀이 <b>이길 뻔했는데</b> 마지막에 역전을 당했어요. *(이지지 못하고 졌다.)", "Đội chúng tôi suýt chút nữa thắng rồi nhưng phút cuối lại bị lội ngược dòng. - Thực tế không thắng được mà bị thua)."]], "practice": [{"vn": "Tôi suýt nữa thì bị trễ xe buýt.", "hint": "버스/놓치다", "answer": "버스를 놓칠 뻔했어요."}, {"vn": "Tôi suýt nữa thì bị ngã.", "hint": "넘어지다", "answer": "넘어질 뻔했어요."}, {"vn": "Chúng tôi suýt nữa thì bị lạc đường.", "hint": "길/잃다", "answer": "길을 잃을 뻔했어요."}]}, {"num": 28, "term": "-(으)ㄹ 수 있다/없다", "meaning": "Có thể/không thể (làm gì) (khả năng)", "blocks": [["p", "<b>1. Năng lực: Giỏi làm một việc gì đó.</b>"], ["ex", "나는 수영을 <b>할 수 있어요</b>.", "Tôi có thể bơi được."], ["ex", "선생님은 한국 음식을 <b>만들 수 있어요</b>?", "Thầy/cô có thể làm món ăn Hàn Quốc được không ạ?"], ["p", "<b>2. Khả năng: Nói về khả năng trong một tình huống hoặc điều kiện nào đó.</b>"], ["ex", "운동을 꾸준히 하면 <b>건강해질 수 있어요</b>.", "Nếu tập thể dục đều đặn thì bạn có thể trở nên khỏe mạnh."], ["ex", "공부를 열심히 하면 1등을 <b>할 수 있어요</b>.", "Nếu học hành chăm chỉ thì bạn có thể đứng nhất."], ["p", "<b>3. Chân lý thông thường: Biểu thị việc không thể tồn tại/xảy ra.</b>"], ["ex", "사람은 물을 마시지 않고 <b>살 수 없어요</b>.", "Con người không thể sống mà không uống nước."], ["ex", "한국에서 일본까지 <b>걸어갈 수 없어요</b>.", "Từ Hàn Quốc không thể đi bộ sang Nhật Bản được."]], "practice": [{"vn": "Tôi có thể nói được tiếng Hàn.", "hint": "한국어/말하다", "answer": "한국어를 말할 수 있어요."}, {"vn": "Tôi không thể đi được vào ngày mai.", "hint": "내일/가다", "answer": "내일은 갈 수 없어요."}, {"vn": "Bạn có thể giúp tôi được không?", "hint": "저/돕다", "answer": "저를 도와줄 수 있어요?"}]}, {"num": 29, "term": "-(으)ㄹ 수(가) 있어야지(요)", "meaning": "Chẳng còn cách nào khác là phải... (bắt buộc, không còn lựa chọn)", "blocks": [["p", "<b>1. Lời nói thể hiện việc không có năng lực để thực hiện một hành vi nào đó. Dùng khi muốn thể hiện sự phủ định một cách mạnh mẽ.</b>"], ["ex", "시끄러워서 얘기를 <b>할 수 있어야지</b>.", "Ồn ào thế này thì làm sao mà nói chuyện được chứ!"], ["ex", "어두워서 찾을 <b>수가 있어야지요</b>.", "Tối mờ tối mẫm thế này thì làm sao mà tìm được cơ chứ ạ!"], ["p", "<b>2. '있어야지(요)' làm vị ngữ mang nghĩa phản ngữ là 'không có'. Đây là dạng rút gọn của '-이/가 있어야 그렇게 하지, 없으니까 그렇게 못한다' (Phải có cái đó thì mới làm thế được, đằng này không có nên không làm thế được).</b>"], ["p", "<b>3. Vì là biểu hiện không tuân phục/phản bác lại lời của đối phương nên không dùng với nghĩa tôn kính.</b>"], ["ex", "여자 친구가 <b>있어야지요</b>. *(여자 친구가 없다.)", "Phải có bạn gái thì mới được chứ ạ - Thực tế không có bạn gái)."], ["ex", "주차할 데가 <b>있어야지요</b>. *(주차할 데가 없다.)", "Phải có chỗ đỗ xe thì mới được chứ ạ - Thực tế không có chỗ đỗ xe)."]], "practice": [{"vn": "Vì mưa quá to nên chẳng còn cách nào khác là phải ở nhà.", "hint": "비/많이/오다/집/있다", "answer": "비가 너무 많이 와서 집에 있을 수 있어야지요."}, {"vn": "Việc quá nhiều nên chẳng còn cách nào khác là phải làm thêm giờ.", "hint": "일/많다/야근하다", "answer": "일이 많아서 야근을 할 수 있어야지요."}, {"vn": "Đường tắc quá nên chẳng còn cách nào khác là phải đi bộ.", "hint": "길/막히다/걷다", "answer": "길이 막혀서 걸어갈 수 있어야지요."}]}, {"num": 30, "term": "-(으)ㄹ 줄 알다/모르다", "meaning": "Biết cách (làm gì)/không biết cách (kỹ năng đã học)", "blocks": [["p", "Khi có thể làm tốt việc gì đó thì dùng '-(으)ㄹ 줄 알다', khi không thể làm được thì dùng '-(으)ㄹ 줄 모르다'."], ["ex", "저는 술을 <b>마실 줄 몰라요</b>.", "Tôi không biết uống rượu."], ["ex", "운전할 <b>줄 알아요</b>?", "Bạn có biết lái xe không?"], ["ex", "한국 노래를 부를 <b>줄 알아요</b>?", "Bạn có biết hát bài hát tiếng Hàn không?"], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄹ 줄 알다' và '-(으)ㄹ 수 있다'</b>"]], ["table", [["<b>Cấu trúc</b>", "<b>Năng lực (Kỹ năng đã học/biết)</b>", "<b>Khả năng (Trong tình huống cụ thể)</b>"], ["<b>-(으)ㄹ 줄 알다</b>", "O", "X"], ["<b>-(으)ㄹ 수 있다</b>", "O", "O"]], 1]], "practice": [{"vn": "Tôi biết cách bơi.", "hint": "수영하다", "answer": "수영할 줄 알아요."}, {"vn": "Tôi không biết cách lái xe.", "hint": "운전하다", "answer": "운전할 줄 몰라요."}, {"vn": "Bạn có biết nấu ăn không?", "hint": "요리하다", "answer": "요리할 줄 알아요?"}]}, {"num": 31, "term": "-(으)ㄹ걸 (그랬다)", "meaning": "Đáng lẽ nên... (đã) (hối tiếc về việc đã/chưa làm)", "blocks": [["p", "Dùng khi hối hận hoặc tiếc nuối vì đã không thực hiện một việc nào đó. Thông thường có '그랬다' phía sau, nhưng cũng có thể lược bỏ."], ["ex", "속이 안 좋은데, 점심을 <b>굶을걸 (그랬어요)</b>.", "Bụng không tốt, biết thế tớ đã nhịn bữa trưa cho rồi."], ["ex", "오늘부터 연휴인 줄 알았더라면, 여행이라도 <b>갈걸 (그랬어요)</b>.", "Giá mà tớ biết từ hôm nay là kỳ nghỉ dài thì biết thế tớ đã đi du lịch rồi."]], "practice": [{"vn": "Đáng lẽ tôi nên học chăm chỉ hơn.", "hint": "열심히/공부하다", "answer": "열심히 공부할걸 그랬어요."}, {"vn": "Đáng lẽ tôi nên đi sớm hơn.", "hint": "일찍/가다", "answer": "일찍 갈걸 그랬어요."}, {"vn": "Đáng lẽ tôi nên nói sự thật.", "hint": "사실/말하다", "answer": "사실대로 말할걸 그랬어요."}]}, {"num": 32, "term": "-(으)ㄹ걸(요)", "meaning": "Chắc là... đấy (phỏng đoán, giọng thân mật)", "blocks": [["p", "Dùng khi phỏng đoán dựa trên kinh nghiệm hoặc thực tế. Chỉ có người nói mới có thông tin này. Ngữ điệu đi lên ở cuối câu."], ["ex", "가: 이번 시험이 어떨까요? *(Kỳ thi lần này thế nào nhỉ?)", "나: 아마 <b>어려울걸요</b>. ($nearrow$) <i>(Có lẽ sẽ khó đấy.) </i>가: 어떻게 알아요? <i>(Sao bạn biết?) </i>나: 선생님이 그렇게 말씀하셨어요. *(Thầy/cô đã nói như vậy đấy."], ["ex", "가: 저 옷 얼마나 할까? *(Bộ quần áo kia bao nhiêu tiền nhỉ?)", "나: 꽤 <b>비쌀걸</b>. ($nearrow$) <i>(Chắc là khá đắt đấy.) </i>가: 왜? <i>(Sao thế?) </i>나: 겨울옷은 비싸. *(Quần áo mùa đông đắt mà."], ["ex", "가: 이쪽은 차가 <b>막힐걸요</b>. ($nearrow$) *(Phía này chắc là tắc", "xe đấy.) <i>나: 그래요? 그럼 저쪽으로 가 봅시다. </i>(Thế à? Vậy chúng ta đi sang phía kia xem sao."]], "practice": [{"vn": "Chắc là anh ấy sẽ đến đấy.", "hint": "그/오다", "answer": "그가 올걸요."}, {"vn": "Chắc là trời sẽ lạnh đấy.", "hint": "날씨/춥다", "answer": "날씨가 추울걸요."}, {"vn": "Chắc là món đó ngon đấy.", "hint": "그 음식/맛있다", "answer": "그 음식이 맛있을걸요."}]}, {"num": 33, "term": "-(으)ㄹ게(요)", "meaning": "Tôi sẽ (làm gì) nhé (lời hứa/ý định của người nói)", "blocks": [["p", "Dùng khi người nói hứa hẹn hoặc thể hiện ý chí sẽ thực hiện một hành động nào đó với người nghe."], ["ex", "저녁에 퇴근하면서 <b>전화할게</b>.", "Tối nay lúc tan làm tớ sẽ gọi điện nhé."], ["ex", "오늘 점심은 저 혼자 <b>먹을게요</b>.", "Trưa nay một mình tớ sẽ ăn nhé."]], "practice": [{"vn": "Tôi sẽ giúp bạn nhé.", "hint": "제가/돕다", "answer": "제가 도와줄게요."}, {"vn": "Tôi sẽ gọi điện lại nhé.", "hint": "다시/전화하다", "answer": "다시 전화할게요."}, {"vn": "Tôi sẽ chờ ở đây nhé.", "hint": "여기/기다리다", "answer": "여기서 기다릴게요."}]}, {"num": 34, "term": "-(으)ㄹ래(요)", "meaning": "Tôi sẽ (làm gì)/Bạn có muốn... không? (ý định của người nói, hỏi ý người nghe)", "blocks": [["p", "Chủ ngữ là ngôi thứ 1 thì dùng ở dạng trần thuật để thể hiện ý chí của người nói. Tương tự như '-(으)려고 해요', '-겠어요'. Chủ ngữ là ngôi thứ 2 thì dùng ở dạng nghi vấn để hỏi ý định của người nghe về một việc nào đó. Không dùng trong câu mệnh lệnh và rủ rê. Đây là cách nói thân mật trong khẩu ngữ nên không mang lại cảm giác quá trang trọng."], ["ex", "심심하니까 친구 집에 갔다가 <b>올래</b>. *(1 ngôi, người nói có ý chí)", "Vì chán nên tớ sẽ sang nhà bạn chơi rồi về nhé."], ["ex", "무슨 차를 <b>드실래요</b>? *(2 ngôi, hỏi ý định của người nghe)", "Bạn muốn dùng loại trà nào ạ?"], ["ex", "누가 이기나 한번 해 <b>볼래요</b>?", "Muốn thử xem ai thắng không nào?"]], "practice": [{"vn": "Tôi sẽ ăn cơm trước.", "hint": "먼저/밥/먹다", "answer": "저는 먼저 밥을 먹을래요."}, {"vn": "Bạn có muốn đi cùng tôi không?", "hint": "같이/가다", "answer": "같이 갈래요?"}, {"vn": "Tôi sẽ không đi đâu.", "hint": "안/가다", "answer": "저는 안 갈래요."}]}, {"num": 35, "term": "-(으)러 가다/오다", "meaning": "Đi/đến để (làm gì) (mục đích di chuyển)", "blocks": [["p", "Vĩ tố nối '-(으)러' chỉ mục đích kết hợp với động từ '가다/오다' mang ý nghĩa di chuyển, thể hiện ý đồ hoặc mục đích di chuyển. Chỉ dùng được với động từ hành động."], ["ex", "그 사람은 도서관에 책을 <b>빌리러 갔다</b>.", "Người đó đã đến thư viện để mượn sách."], ["ex", "너 여기에 누구 <b>만나러 왔니</b>?", "Cậu đến đây để gặp ai thế?"], ["ex", "나는 점심을 <b>먹으러</b> 식당에 가다가 친구를 만났습니다.", "Tôi đang trên đường đến nhà hàng để ăn trưa thì gặp bạn."]], "practice": [{"vn": "Tôi đi mua đồ ăn.", "hint": "음식/사다/가다", "answer": "음식을 사러 가요."}, {"vn": "Bạn tôi đến thăm tôi.", "hint": "친구/놀다/오다", "answer": "친구가 놀러 왔어요."}, {"vn": "Tôi đi khám bệnh.", "hint": "병원/진료/받다/가다", "answer": "진료를 받으러 병원에 가요."}]}, {"num": 36, "term": "-(으)려고 하다", "meaning": "Định (làm gì) (ý định)", "blocks": [["p", "<b>1. Chỉ thể hiện ý đồ của chủ ngữ nên ở trong trạng thái chưa chuyển thành hành động thực tế.</b>"], ["ex", "동생에게 선물을 <b>부치려고 합니다</b>.", "Tôi định gửi quà cho em."], ["ex", "돈을 다 쓰기 전에 운동화를 <b>사려고 합니다</b>.", "Tôi định mua đôi giày thể thao trước khi tiêu hết tiền."], ["ex", "이번 방학에 배낭여행을 <b>가려고 해요</b>.", "Kỳ nghỉ lần này tôi định đi du lịch ba lô."], ["p", "<b>2. Trong khẩu ngữ, người ta thường thêm 'ㄹ' vào thành dạng '-(으)ㄹ려고 하다'.</b>"], ["ex", "<b>갈려고 하다</b>. <i>(Định đi)</i>", ""], ["ex", "<b>쉴려고 하다</b>. <i>(Định nghỉ ngơi)</i>", ""], ["ex", "<b>일어날려고 하다</b>. <i>(Định thức dậy)</i>", ""]], "practice": [{"vn": "Tôi định học tiếng Hàn.", "hint": "한국어/공부하다", "answer": "한국어를 공부하려고 해요."}, {"vn": "Tôi định đi du lịch vào tháng sau.", "hint": "다음 달/여행/가다", "answer": "다음 달에 여행을 가려고 해요."}, {"vn": "Tôi định nghỉ ngơi ở nhà.", "hint": "집/쉬다", "answer": "집에서 쉬려고 해요."}]}, {"num": 37, "term": "-(으)려던 참이다", "meaning": "Đang định (làm gì) (đúng lúc chuẩn bị làm)", "blocks": [["p", "Không dùng vĩ tố thì tương lai '-겠-'. Gắn vào động từ hành động thể hiện ý nghĩa 'đang trong lúc định thực hiện hành vi nào đó', dùng để hồi tưởng lại công việc lúc định làm."], ["ex", "지금 우리는 <b>외출하려던 참이에요</b>.", "Bây giờ chúng tôi đúng lúc đang định đi ra ngoài đây."], ["ex", "병원에 가서 검사를 받아 <b>보려던 참입니다</b>.", "Tôi đúng lúc đang định đến bệnh viện để kiểm tra xem sao đây."]], "practice": [{"vn": "Tôi đang định gọi điện cho bạn đấy.", "hint": "너/전화하다", "answer": "너한테 전화하려던 참이었어."}, {"vn": "Tôi đang định ra ngoài đấy.", "hint": "밖/나가다", "answer": "밖에 나가려던 참이었어요."}, {"vn": "Tôi đang định ăn cơm đấy.", "hint": "밥/먹다", "answer": "밥을 먹으려던 참이었어요."}]}, {"num": 38, "term": "-(으)ㅂ시다", "meaning": "Hãy cùng (làm gì) (đề nghị, rủ rê)", "blocks": [["p", "Là biểu hiện trang trọng dùng khi nói cùng làm một việc nào đó. Khi nói thân mật (bán ngữ) thì dùng '-자'."], ["ex", "같이 도서관에 <b>갑시다</b>.", "Chúng ta cùng đến thư viện nhé."], ["ex", "커피 한잔 <b>합시다</b>.", "Chúng ta uống một tách cà phê nhé."], ["ex", "영화 보러 <b>가자</b>.", "Đi xem phim đi."], ["bq", ["<b>Tìm hiểu thêm | Cách dùng, ngữ điệu và mức độ của câu rủ rê</b>", "<b>1.</b> Khi nói rất lịch sự với người lớn tuổi, không dùng", "'-(으)ㅂ시다'. Thay vào đó, dùng '-(으)시겠습니까?' hoặc '-(으)시지요'", "sẽ tự nhiên hơn. Lúc này ngữ điệu của '-(으)시지요' sẽ đi xuống. Ngoài", "ra, khi thân thiết nhưng không thể dùng nói trống không, thay vì '-자'", "người ta dùng '-아/아요'."]], ["ex", "어서 <b>식사하시지요</b>. ($searrow$) <i>(Mời ngài dùng bữa ạ.)</i>", ""], ["ex", "저랑 같이 한잔 <b>하시지요</b>. ($searrow$) *(Mời ngài cùng uống", "với tôi một ly ạ."], ["ex", "같이 도서관에 <b>가시지요</b>. ($searrow$) *(Mời ngài cùng đến thư", "viện ạ."], ["bq", ["<b>2. Mức độ rủ rê:</b> '-(으)ㅂ시다' $>$ '-(으)ㄹ까요?' $>$", "'-(으)ㄹ래요?'"]], ["ex", "수연 씨, 같이 <b>식사합시다</b>.", "$rightarrow$ Ý định của người nói là quan trọng nhất, không hỏi ý kiến Su-yeon mà định cùng ăn bữa tối."], ["ex", "수연 씨, 같이 <b>식사할까요</b>?", "$rightarrow$ Người nói muốn ăn nhưng hỏi xem suy nghĩ của Su-yeon thế nào."], ["ex", "수연 씨, 같이 <b>식사할래요</b>?", "$rightarrow$ Bất kể suy nghĩ của mình ra sao, hỏi xem Su-yeon có muốn ăn cơm trước không."], ["table", [["<b>Cấu trúc</b>", "<b>Suy nghĩ của người nói</b>", "<b>Suy nghĩ của người nghe</b>"], ["<b>-(으 )ㄹ래요?</b>", "○ (Sau)", "⊙ (Trước)"], ["<b>-(으 )ㄹ까요?</b>", "⊙ (Trước)", "○ (Sau)"], ["<b>-( 으)ㅂ시다</b>", "⊙ (Quan trọng nhất)", "× (Không hỏi)"]], 1], ["p", "III. TRỢ TỪ"]], "practice": [{"vn": "Chúng ta cùng bắt đầu nhé.", "hint": "시작하다", "answer": "시작합시다."}, {"vn": "Chúng ta cùng ăn trưa nhé.", "hint": "점심/먹다", "answer": "점심을 먹읍시다."}, {"vn": "Chúng ta cùng cố gắng nhé.", "hint": "열심히/하다", "answer": "열심히 합시다."}]}], "josa": [{"num": 1, "term": "같이", "meaning": "Như, giống như (so sánh) hoặc nhấn mạnh thời điểm", "blocks": [["p", "<b>1. Ví nét mặt hay hành động với danh từ đứng trước, thể hiện mức độ tương tự hoặc giống hệt nhau. '같이' có thể thay thế bằng trợ từ '처럼' mà không có sự khác biệt lớn về nghĩa, và trong một số trường hợp có thể thay bằng '만큼'.</b>"], ["ex", "수진이 얼굴은 <b>조각같이</b> 아름다워.", "Khuôn mặt Su-jin đẹp như một bức tượng điêu khắc."], ["ex", "제인은 한국 <b>사람같이</b> 말을 잘해.", "Jane nói chuyện giỏi như người Hàn Quốc."], ["p", "<b>2. [Gắn vào một số danh từ chỉ thời gian] Mang ý nghĩa nhấn mạnh thời gian đó.</b>"], ["ex", "부모님께서는 <b>새벽같이</b> 일어나 일하러 가셨다.", "Bố mẹ đã thức dậy từ tinh mơ sáng để đi làm."], ["ex", "어머니는 <b>매일같이</b> 기도하러 교회에 가셨다.", "Mẹ tôi đi đến nhà thờ để cầu nguyện gần như mỗi ngày."], ["p", "<b>3. Có thể dùng làm biểu hiện ẩn dụ mang tính quan dụng.</b>"], ["ex", "<b>앵두같이</b> 아름다운 입술.", "Làn môi đẹp như quả anh đào."], ["ex", "<b>별같이</b> 초롱초롱한 눈.", "Đôi mắt sáng long lanh như những ngôi sao."]], "practice": [{"vn": "Khuôn mặt Sujin đẹp như tạc tượng.", "hint": "수진/얼굴/조각/아름답다", "answer": "수진이 얼굴은 조각같이 아름다워."}, {"vn": "Bố mẹ đã dậy từ sáng sớm để đi làm.", "hint": "부모님/새벽/일어나다", "answer": "부모님께서는 새벽같이 일어나 일하러 가셨다."}, {"vn": "Mẹ đi nhà thờ cầu nguyện mỗi ngày.", "hint": "어머니/매일/기도하다", "answer": "어머니는 매일같이 기도하러 교회에 가셨다."}]}, {"num": 2, "term": "(이)나마", "meaning": "Dù chỉ là..., dù ít ỏi (nhưng vẫn còn hơn không có)", "blocks": [["p", "Thể hiện sự chấp nhận, nhượng bộ một cách miễn cưỡng dù trong lòng cảm thấy chưa đủ/chưa vừa ý."], ["ex", "<b>헌 우산이나마</b> 있으니 다행이다.", "Có chiếc ô cũ thế này thôi cũng là may mắn rồi."], ["ex", "형이 쓰던 <b>자전거나마</b> 한 대 있습니다.", "Có một chiếc xe đạp dù là đồ anh trai từng dùng."], ["bq", ["<b>Tìm hiểu thêm | So sánh '(이)나마' và '(이)라도'</b>", "<b>1.</b> '(이)나마' và '(이)라도' đều thể hiện sự nhượng bộ và chấp nhận", "nên trong một số trường hợp ý nghĩa tương tự nhau và có thể thay đổi", "cho nhau. Tuy nhiên, '(이)나마' là việc người nói dù chưa bất mãn", "nhưng miễn cưỡng làm hành động phía sau, còn '(이)라도' thể hiện việc", "phải lựa chọn mà không phân biệt cái này cái kia nên có trường hợp", "không thể thay thế."]], ["ex", "<b>비닐우산이나마</b> 쓰고 갑시다.", "$rightarrow$ Dù là chiếc ô nilon không vừa ý nhưng vẫn che rồi đi thôi."], ["ex", "<b>비닐우산이라도</b> 쓰고 갑시다.", "$rightarrow$ Trong số những cái có thể chọn thì chiếc ô nilon là tối ưu rồi, cứ che rồi đi thôi."], ["bq", ["**2. Khi đi cùng các từ như '누구, 무엇, 무슨, 언제, 어디, 어떤', có", "thể dùng '(이)라도' nhưng không thể dùng '(이)나마'.**"]], ["ex", "<b>누구라도</b> 오거든 이 편지를 전해 줘요. (O) / 누구나마 (X)", ""], ["ex", "<b>무슨 일이라도</b> 생기면 어떻게 하지요? (O) / 무슨 일이나마 (X)", ""]], "practice": [{"vn": "Dù ít tiền nhưng tôi cũng đã gửi giúp đỡ.", "hint": "적은 돈/도움을 주다", "answer": "적은 돈이나마 도움을 줬어요."}, {"vn": "Dù ngắn ngủi nhưng chúng tôi đã có thời gian vui vẻ.", "hint": "짧다/시간/즐겁다", "answer": "짧으나마 즐거운 시간을 보냈어요."}, {"vn": "Dù chỉ là lời nói nhưng tôi cũng cảm ơn bạn.", "hint": "말/뿐/감사하다", "answer": "말뿐이나마 감사드려요."}]}, {"num": 3, "term": "대로", "meaning": "Theo, đúng như (cách thức, mức độ tương ứng)", "blocks": [["p", "Thể hiện việc căn cứ vào lời nói phía trước, hoặc không có sự thay đổi, hoặc được phân chia riêng biệt."], ["p", "<b>1. Thể hiện việc căn cứ vào lời nói, tình huống, phương pháp, nội dung đứng trước hoặc không có sự thay đổi.</b>"], ["ex", "선생님의 <b>가르침대로</b> 하겠습니다.", "Tôi sẽ làm theo đúng lời dạy của thầy/cô."], ["ex", "사람들은 결국 저마다의 <b>방식대로</b> 살아가는 거야.", "Rốt cuộc con người ta ai cũng sống theo phương thức của riêng mình thôi."], ["p", "<b>2. Thể hiện sự phân chia riêng biệt.</b>"], ["ex", "대학은 <b>대학대로</b> 특성이 있어요.", "Trường đại học có đặc tính riêng của trường đại học."], ["ex", "너도 힘들겠지만 나는 <b>나대로</b> 한잠도 못 잤어.", "Cậu cũng mệt mỏi đấy nhưng tớ thì tớ cũng chẳng chợp mắt được tẹo nào."], ["p", "<b>3. '대로' cũng được dùng làm danh từ phụ thuộc đi cùng với vĩ tố '는', '은', '을'.</b>"], ["ex", "<b>아는 대로</b> 설명해 보세요.", "Hãy thử giải thích theo những gì bạn biết xem nào."], ["ex", "둘의 애정은 <b>식을 대로</b> 식었다.", "Tình cảm của hai người đã nguội lạnh đến mức không thể nguội hơn được nữa."]], "practice": [{"vn": "Hãy làm theo cách của bạn.", "hint": "네/마음/하다", "answer": "네 마음대로 해."}, {"vn": "Hãy làm theo đúng như quy định.", "hint": "규정/하다", "answer": "규정대로 하세요."}, {"vn": "Mỗi người có một tính cách riêng.", "hint": "사람/성격", "answer": "사람은 사람대로 성격이 다르다."}]}, {"num": 4, "term": "(이)든(지)", "meaning": "Dù là... đi nữa, bất kể là gì (liệt kê không quan trọng cái nào)", "blocks": [["p", "Dùng khi trao quyền lựa chọn cho người nghe mà không chọn một cái cụ thể nào."], ["p", "<b>1. Đứng sau từ nghi vấn để chỉ đối tượng không xác định, hoặc dùng lặp lại dưới dạng '-(이)든지 -(이)든지'.</b>"], ["ex", "<b>밥이든 빵이든</b> 좀 먹어야 힘을 내지.", "Phải ăn cơm hay ăn bánh mì vào thì mới có sức chứ."], ["ex", "<b>언제든지</b> 자기 잘못을 뉘우칠 때가 있을 거야.", "Bất cứ lúc nào rồi cũng sẽ có lúc nó ăn ăn hối cải về lỗi lầm của mình thôi."], ["p", "<b>2. Cũng có thể gắn sau các trợ từ như '에', '에게', '(으)로'.</b>"], ["ex", "<b>여름에든지 겨울에든지</b> 여행을 떠납시다.", "Dù là mùa hè hay mùa đông thì chúng ta hãy lên đường đi du lịch nhé."], ["ex", "법이란 <b>누구에게든지</b> 골고루 적용되는 거야.", "Pháp luật là thứ được áp dụng công bằng cho bất kỳ ai."]], "practice": [{"vn": "Dù là ai đi nữa cũng có thể tham gia.", "hint": "누구/참여하다", "answer": "누구든지 참여할 수 있어요."}, {"vn": "Dù là khi nào cũng được, hãy đến chơi.", "hint": "언제/놀다/오다", "answer": "언제든지 놀러 오세요."}, {"vn": "Dù là cái gì cũng được, hãy chọn cái bạn thích.", "hint": "무엇/좋아하다/고르다", "answer": "무엇이든지 좋아하는 것을 고르세요."}]}, {"num": 5, "term": "(이)라도", "meaning": "Dù là... cũng được (chấp nhận một lựa chọn không phải tốt nhất)", "blocks": [["p", "Thể hiện việc chọn cái đó dù chưa thật sự vừa ý trong số nhiều thứ vì không thể chọn cái hoàn toàn ưng ý."], ["ex", "음료수가 없으면 <b>물이라도</b> 한 잔 주세요.", "Nếu không có nước giải khát thì cho tôi xin ly nước lọc thôi cũng được."], ["ex", "심심한데 <b>바둑이라도</b> 두자.", "Đang chán quá, chúng mình chơi cờ cờ chăng/cờ tướng đi."]], "practice": [{"vn": "Nước cũng được, cho tôi xin một cốc.", "hint": "물/한 잔/주다", "answer": "물이라도 한 잔 주세요."}, {"vn": "Dù chỉ một chút thôi cũng được, hãy giúp tôi.", "hint": "조금/돕다", "answer": "조금이라도 도와주세요."}, {"vn": "Nếu không có xe buýt thì đi taxi cũng được.", "hint": "버스/없다/택시/타다", "answer": "버스가 없으면 택시라도 타야겠어요."}]}, {"num": 6, "term": "(이)라든가", "meaning": "Hay là, hoặc những thứ như (liệt kê ví dụ tương tự)", "blocks": [["p", "Thể hiện việc liệt kê các sự vật mà dù chọn cái nào thì cũng không quan trọng."], ["ex", "학생들이 자주 먹는 음식에는 <b>라면이라든가 떡볶이라든가</b> 하는 것이 있다.", "Trong số các món ăn học sinh thường ăn có những món như là mì gói hay bánh gạo cay."]], "practice": [{"vn": "Hãy uống cà phê hay trà gì đó.", "hint": "커피/차/마시다", "answer": "커피라든가 차라든가 마시세요."}, {"vn": "Ta có thể đi công viên hay là bảo tàng.", "hint": "공원/박물관/가다", "answer": "공원이라든가 박물관이라든가 가 봐요."}, {"vn": "Hãy mang theo sách hay là tạp chí gì đó.", "hint": "책/잡지/가져오다", "answer": "책이라든가 잡지라든가 가져오세요."}]}, {"num": 7, "term": "(으)로부터", "meaning": "Từ (nguồn gốc, xuất phát điểm, thường trang trọng hơn '에서')", "blocks": [["p", "Thể hiện đối tượng làm điểm xuất phát hoặc là nguồn gốc của một hành động nào đó."], ["ex", "<b>아버지로부터</b> 편지가 왔다.", "Thư từ bố đã gửi đến."]], "practice": [{"vn": "Tôi đã nhận được thư từ bạn.", "hint": "친구/편지/받다", "answer": "친구로부터 편지를 받았어요."}, {"vn": "Vấn đề này bắt đầu từ sự hiểu lầm nhỏ.", "hint": "작다/오해/시작되다", "answer": "이 문제는 작은 오해로부터 시작됐어요."}, {"vn": "Tôi đã học được nhiều điều từ thầy giáo.", "hint": "선생님/많이/배우다", "answer": "선생님으로부터 많이 배웠어요."}]}, {"num": 8, "term": "(으)로서", "meaning": "Với tư cách là, với vai trò là", "blocks": [["p", "Thể hiện danh từ đứng trước có một tư cách nào đó."], ["ex", "<b>학생으로서</b> 해야 할 일이 무엇이겠어요?", "Công việc phải làm với tư cách là một học sinh là gì cơ chứ?"], ["ex", "이 약수는 마시는 <b>물로서</b> 적당하지 않습니다.", "Nguồn nước khoáng này không thích hợp dùng làm nước uống."]], "practice": [{"vn": "Với tư cách là bạn, tôi khuyên cậu nên cẩn thận.", "hint": "친구/충고하다", "answer": "친구로서 충고할게."}, {"vn": "Với vai trò là giáo viên, tôi phải có trách nhiệm.", "hint": "교사/책임/지다", "answer": "교사로서 책임을 져야 해요."}, {"vn": "Với tư cách là học sinh, bạn nên học chăm chỉ.", "hint": "학생/열심히/공부하다", "answer": "학생으로서 열심히 공부해야 해요."}]}, {"num": 9, "term": "마저(도)", "meaning": "Đến cả..., ngay cả... (cũng), nhấn mạnh mức độ nghiêm trọng", "blocks": [["p", "<b>1. Dùng với nghĩa 'đến tận cái cuối cùng cũng không còn lại chút nào mà tất cả đều...'.</b>"], ["ex", "우린 하마터면 <b>목숨마저</b> 잃을 뻔했다.", "Chúng tôi suýt chút nữa đến cả tính mạng cũng bị mất rồi."], ["ex", "아버지는 빚을 갚으려고 <b>집마저</b> 다 팔아 버렸다.", "Để trả nợ, bố đã bán sạch đến cả căn nhà."], ["p", "<b>2. Thể hiện việc nhấn mạnh khi một sự thật nào đó rơi vào trường hợp ngoài dự đoán mang tính cực đoan.</b>"], ["ex", "<b>너희들마저</b> 가 버리면 여기 일은 누가 하니?", "Đến cả các cậu cũng bỏ đi thì công việc ở đây ai làm đây?"], ["ex", "<b>너마저</b> 모른다면 이젠 알 사람이 없어.", "Ngay cả cậu mà cũng không biết thì giờ chẳng còn ai biết nữa rồi."], ["p", "<b>3. Thể hiện sự cộng thêm vào hoàn cảnh vốn đã bất lợi/khó khăn.</b>"], ["ex", "눈이 오는데 <b>바람마저</b> 불어 대는구나.", "Trời đã đang mưa tuyết rồi mà đến cả gió cũng thổi bùng bùng nữa."], ["ex", "논도 밭도 그리고 <b>집마저도</b> 물에 잠겨 버렸다.", "Ruộng, vườn và đến cả nhà cửa cũng đã bị nhấn chìm trong nước mất rồi."]], "practice": [{"vn": "Ngay cả bạn thân nhất cũng đã rời xa tôi.", "hint": "가장/친한/친구/떠나다", "answer": "가장 친한 친구마저 떠났다."}, {"vn": "Đến cả tiền cũng chẳng còn.", "hint": "돈/없다", "answer": "돈마저 없다."}, {"vn": "Ngay cả trời cũng như đang khóc cùng tôi.", "hint": "하늘/울다", "answer": "하늘마저 우는 것 같다."}]}, {"num": 10, "term": "만큼(은)", "meaning": "Tùy theo mức độ, chỉ ở một chừng mực nhất định", "blocks": [["p", "Là trợ từ bổ trợ thể hiện sự giới hạn. Gắn vào sau trợ từ cách '에게' để giới hạn và nhấn mạnh một đối tượng nào đó. Là biểu hiện khẩu ngữ, có thể thay thế bằng trợ từ bổ trợ '은/는'."], ["ex", "<b>어머니에게만큼은</b> 잘해 드리려고 했는데.", "Tôi đã định là ít nhất đối với mẹ thì sẽ đối xử thật tốt."], ["ex", "이 일을 <b>너에게만큼은</b> 알리고 싶었다.", "Công việc này tôi đã muốn cho ít nhất là cậu được biết."]], "practice": [{"vn": "Tôi sẽ cố gắng hết mức có thể.", "hint": "할 수 있다/노력하다", "answer": "할 수 있는 만큼 노력할게요."}, {"vn": "Bạn cứ ăn theo sức của bạn.", "hint": "먹다/드시다", "answer": "드실 수 있는 만큼 드세요."}, {"vn": "Ít nhất thì cũng nên biết chào hỏi.", "hint": "인사/할 줄 알다", "answer": "인사만큼은 할 줄 알아야지요."}]}, {"num": 11, "term": "밖에", "meaning": "Chỉ (còn)... (phủ định, không có gì khác ngoài cái đó)", "blocks": [["p", "Đi cùng với danh từ và mệnh đề sau <b>nhất định phải là dạng phủ định</b>. Thể hiện chỉ có duy nhất danh từ đó mà thôi."], ["ex", "주머니에는 <b>천 원밖에</b> 없어요.", "Trong túi chỉ có vỏn vẹn 1.000 won mà thôi."], ["ex", "빨리 가요. 시간이 <b>조금밖에</b> 없어요.", "Mau đi thôi. Thời gian chỉ còn lại có một chút thôi."]], "practice": [{"vn": "Trong ví tôi chỉ còn mười nghìn won.", "hint": "지갑/만원/있다", "answer": "지갑에 만 원밖에 없어요."}, {"vn": "Tôi chỉ biết mỗi tiếng Hàn thôi.", "hint": "한국어/할 줄 알다", "answer": "한국어밖에 할 줄 몰라요."}, {"vn": "Chỉ còn ba ngày nữa là đến kỳ thi.", "hint": "시험/삼 일/남다", "answer": "시험이 삼 일밖에 안 남았어요."}]}, {"num": 12, "term": "보고", "meaning": "Với, cho (đối tượng của lời nói, khẩu ngữ, thường dùng khi nhờ vả/hỏi)", "blocks": [["p", "<b>1. Là phó trợ từ thể hiện đối tượng mà hành động hướng tới. Gắn sau danh từ chỉ đối tượng hữu tình (người hoặc động vật có suy nghĩ, cảm xúc). Tương đương với '에게' về mặt vị ngữ nhưng chủ yếu dùng trong khẩu ngữ và có phạm vi sử dụng hẹp hơn.</b>"], ["ex", "누가 <b>너보고</b> 그 일을 하라고 했니?", "Ai bảo cậu làm việc đó thế?"], ["ex", "그게 <b>누구보고</b> 하는 소리야?", "Đó là lời nói hướng vào ai thế?"], ["p", "<b>2. Chủ yếu dùng cùng với các từ như '말하다' (nói), '묻다' (hỏi), '욕하다' (chửi bới) để trích dẫn lời của người khác hoặc lấy đối phương làm đối tượng trực tiếp khi nói chuyện.</b>"]], "practice": [{"vn": "Bạn hãy hỏi thử cô ấy xem.", "hint": "그녀/물어보다", "answer": "그녀보고 물어보세요."}, {"vn": "Tôi đã bảo em tôi dọn phòng.", "hint": "동생/방/청소하다", "answer": "동생보고 방을 청소하라고 했어요."}, {"vn": "Đừng bảo tôi làm việc đó.", "hint": "저/일/하다", "answer": "저보고 그 일을 하라고 하지 마세요."}]}, {"num": 13, "term": "뿐", "meaning": "Chỉ, duy nhất (không có gì khác)", "blocks": [["p", "[Gắn sau danh từ hoặc một số trợ từ] Là trợ từ thể hiện từ đứng trước là cái duy nhất."], ["p", "<b>1. Dùng dưới dạng '뿐이다': Thể hiện không có cái khác hoặc chỉ duy nhất cái đứng trước.</b>"], ["ex", "내가 사랑하는 사람은 <b>너뿐이야</b>.", "Người mà tớ yêu chỉ có duy nhất mình cậu thôi."], ["ex", "제가 할 수 있는 외국어는 <b>영어뿐입니다</b>.", "Ngoại ngữ mà tôi có thể nói được chỉ duy nhất là tiếng Anh."], ["p", "<b>2. Chủ yếu dùng dưới cấu trúc '뿐(만) 아니라': Thể hiện ngoài từ đứng trước ra thì còn có thêm cái khác nữa.</b>"], ["ex", "자고 싶은 사람은 <b>너뿐 아니다</b>.", "Người muốn ngủ không chỉ có duy nhất mình cậu đâu."], ["ex", "남대문 시장은 <b>한국에서뿐만 아니라</b> 세계적으로 유명하다.", "Chợ Namdaemun không chỉ nổi tiếng ở Hàn Quốc mà còn nổi tiếng trên toàn thế giới."], ["p", "<b>3. Trợ từ '만' và '밖에' cũng có ý nghĩa tương tự như '뿐'. Nhưng khác với '뿐' có thể đi với '이다', '아니다', '밖에' chỉ đi với dạng phủ định, còn '만' đi với cả câu khẳng định và phủ định.</b>"], ["p", "<b>4. Khi đứng trước '뿐' là động từ, tính từ hoặc '이다', nó được dùng dưới dạng '-(으)ㄹ 뿐'. Lúc này, '뿐' không phải là trợ từ mà là danh từ phụ thuộc.</b>"], ["ex", "모두 구경만 <b>할 뿐이었다</b>.", "Tất cả mọi người chỉ đứng đứng xem mà thôi."], ["ex", "시간만 <b>보냈을 뿐이지</b> 한 일은 없다.", "Chỉ lãng phí thời gian chứ chẳng làm được việc gì cả."]], "practice": [{"vn": "Người mà tôi yêu chỉ có mỗi cậu thôi.", "hint": "사랑하다/사람/너", "answer": "내가 사랑하는 사람은 너뿐이야."}, {"vn": "Ngoại ngữ tôi biết chỉ có tiếng Anh thôi.", "hint": "외국어/영어", "answer": "제가 할 수 있는 외국어는 영어뿐입니다."}, {"vn": "Tất cả mọi người chỉ đứng xem mà thôi.", "hint": "모두/구경하다", "answer": "모두 구경만 할 뿐이었다."}]}, {"num": 14, "term": "(이)야/(이)야말로", "meaning": "Chính là, đặc biệt là (nhấn mạnh, chỉ định)", "blocks": [["p", "'(이)야' có nghĩa là 'chỉ định và nhấn mạnh', là trợ từ có chức năng thay thế cho các trợ từ cách. '(이)야말로' là dạng nhấn mạnh mạnh mẽ hơn của '(이)야', và không được kết nối với phó từ."], ["ex", "<b>나야</b> 뭐라고 말할 수 있겠니?", "Là tớ thì tớ có thể nói được gì cơ chứ?"], ["ex", "<b>용서야말로</b> 소중한 가치 덕목이다.", "Sự tha thứ chính là đức tính giá trị vô cùng quý giá."], ["ex", "방금 나갔는데 <b>멀리야</b> 갔겠어? (O)", "Vừa mới đi ra ngoài thì làm sao mà đi xa được cơ chứ?"], ["ex", "방금 나갔는데 멀리야말로 갔겠어? (X)", ""]], "practice": [{"vn": "Đúng lúc tôi cần đấy.", "hint": "필요하다/때", "answer": "필요할 때야."}, {"vn": "Chính bạn mới là người hiểu tôi nhất.", "hint": "너/나/이해하다", "answer": "너야말로 나를 제일 잘 이해해."}, {"vn": "Đây chính là cơ hội tốt nhất.", "hint": "이것/좋다/기회", "answer": "이것이야말로 최고의 기회예요."}]}, {"num": 15, "term": "에게서", "meaning": "Từ (ai đó) (nguồn gốc là người, dùng cho hành động nhận/nghe từ ai)", "blocks": [["p", "Là trợ từ phụ cách chỉ địa điểm/đối tượng phát sinh hành động."], ["p", "<b>1. Thể hiện điểm bắt đầu của hành động. Người hoặc động vật trở thành điểm bắt đầu.</b>"], ["ex", "나는 그 소문을 <b>동생에게서</b> 들었다.", "Tôi đã nghe tin đồn đó từ em tôi."], ["ex", "어미 <b>소에게서</b> 송아지가 생겼다.", "Bò mẹ đã sinh ra bò con."], ["p", "<b>2. Thể hiện địa điểm/đối tượng mà hành động đang được tiến hành.</b>"], ["ex", "그 노래는 <b>학생들에게서</b> 넓리 유행되던 노래이다.", "Bài hát đó là bài hát từng rất phổ biến trong giới học sinh."], ["ex", "이 화장품은 <b>여자들에게서</b> 많이 쓰인다.", "Mỹ phẩm này được sử dụng rất nhiều ở phái nữ."], ["p", "<b>3. Thể hiện việc diễn tả, chỉ định một đối tượng cùng tính chất, đặc điểm, dấu hiệu của nó.</b>"], ["ex", "<b>너에게서</b> 단점이 있다면 성급하다는 점이다.", "Ở cậu nếu có khuyết điểm thì đó chính là tính cẩn trọng, vội vàng."], ["ex", "<b>학생들에게서</b> 중요한 것은 공부에 힘쓰는 것이다.", "Ở các học sinh, điều quan trọng chính là nỗ lực vào việc học."], ["p", "<b>4. Thể hiện đối tượng thực hiện hành vi đối với chủ ngữ trong câu.</b>"], ["ex", "승화는 그 <b>여자에게서</b> 속임을 당했다.", "Seung-hwa đã bị người phụ nữ đó lừa gạt."], ["ex", "누리는 그 <b>남자에게서</b> 거절을 당했다.", "Nuri đã bị người đàn ông đó từ chối."], ["p", "<b>5. Thể hiện đối tượng trở thành 'ở trong số đó' khi một hành vi nào đó xảy ra.</b>"], ["ex", "실패의 원인은 우리 <b>자신에게서</b> 찾아야 한다.", "Nguyên nhân thất bại phải tìm kiếm từ chính bản thân chúng ta."], ["ex", "그런 장난은 <b>아이들에게서</b> 자주 볼 수 있다.", "Trò đùa như thế có thể thường xuyên nhìn thấy ở trẻ em."]], "practice": [{"vn": "Tôi đã nghe tin đó từ bạn tôi.", "hint": "친구/소식/듣다", "answer": "친구에게서 그 소식을 들었어요."}, {"vn": "Tôi đã nhận được món quà từ mẹ.", "hint": "어머니/선물/받다", "answer": "어머니에게서 선물을 받았어요."}, {"vn": "Tôi đã học được điều đó từ thầy giáo.", "hint": "선생님/그것/배우다", "answer": "선생님에게서 그것을 배웠어요."}]}, {"num": 16, "term": "에다가/에다", "meaning": "Vào, thêm vào (địa điểm/đối tượng thêm vào, mang tính liệt kê)", "blocks": [["p", "Là trợ từ phụ cách nhấn mạnh vị trí mà hành động nào đó được thực hiện. '에다' là dạng rút gọn của '에다가'."], ["p", "<b>1. Gắn vào danh từ để đưa ra vị trí của danh từ đó một cách nhấn mạnh.</b>"], ["ex", "<b>등에다가</b> 큰 가방을 메고 학교에 간다.", "Tôi đeo cái túi to trên lưng rồi đi đến trường."], ["ex", "그건 <b>옷장에다가</b> 넣어두어라.", "Cái đó hãy cất vào trong tủ quần áo đi."], ["p", "<b>2. Thể hiện chủ thể nhận hành động hoặc sự việc nào đó.</b>"], ["ex", "<b>꽃나무에다가</b> 물을 주었다.", "Tôi đã tưới nước vào cây hoa."], ["ex", "<b>학생에다가</b> 장학금을 주라고 했다.", "Người ta bảo hãy trao học bổng cho học sinh."], ["p", "<b>3. Thể hiện công cụ hoặc phương tiện.</b>"], ["ex", "이불을 <b>햇볕에다</b> 말리면 좋다.", "Phơi chăn dưới ánh nắng mặt trời thì rất tốt."], ["ex", "<b>차에다</b> 이삿짐을 실었다.", "Tôi đã chất đồ đạc chuyển nhà lên xe ô tô."], ["p", "<b>4. Thể hiện đối tượng so sánh hoặc đối tượng ẩn dụ.</b>"], ["ex", "사람들은 예쁜 사람을 <b>꽃에다가</b> 비유한다.", "Người ta thường so sánh người đẹp với hoa."], ["ex", "동생의 행위를 <b>형에다가</b> 비교하여 어떻다고 말한다.", "Người ta so sánh hành vi của em với anh rồi nhận xét thế này thế nọ."], ["p", "<b>5. Thể hiện sự cộng thêm vào một sự việc nào đó.</b>"], ["ex", "누가 <b>술에다</b> 물까지 탔다.", "Ai đó đã pha thêm cả nước vào rượu."], ["ex", "이번 달에는 <b>월급에다가</b> 상여금까지 붙는다.", "Tháng này ngoài tiền lương ra còn được cộng thêm cả tiền thưởng."], ["bq", ["<b>Tìm hiểu thêm | So sánh '에다가' và '에'</b>", "Cả hai đều là trợ từ chỉ vị trí nhất định, nhưng <b>'에다가'</b> được", "dùng khi muốn nhấn mạnh vào vị trí chính xác hơn so với <b>'에'</b>."]]], "practice": [{"vn": "Hãy viết tên vào đây.", "hint": "여기/이름/쓰다", "answer": "여기에다가 이름을 쓰세요."}, {"vn": "Tôi đã cho đường vào cà phê.", "hint": "커피/설탕/넣다", "answer": "커피에다가 설탕을 넣었어요."}, {"vn": "Đừng vứt rác ra đường.", "hint": "길/쓰레기/버리다", "answer": "길에다가 쓰레기를 버리지 마세요."}]}, {"num": 17, "term": "처럼", "meaning": "Như, giống như (so sánh)", "blocks": [["p", "Là trợ từ cách thể hiện hình dáng hoặc mức độ tương tự hoặc giống hệt nhau."], ["ex", "저는 <b>새처럼</b> 하늘을 날고 싶어요.", "Tôi muốn bay trên bầu trời như một chú chim."], ["ex", "<b>연습 때처럼</b> 최선을 다하면 후회하지 않을 거예요.", "Nếu nỗ lực hết sức như lúc tập luyện thì bạn sẽ không phải hối hận đâu."]], "practice": [{"vn": "Cô ấy đẹp như một ngôi sao.", "hint": "그녀/별/예쁘다", "answer": "그녀는 별처럼 예뻐요."}, {"vn": "Thời gian trôi nhanh như tên bắn.", "hint": "시간/화살/빠르다", "answer": "시간이 화살처럼 빠르다."}, {"vn": "Hãy sống như hôm nay là ngày cuối cùng.", "hint": "오늘/마지막/살다", "answer": "오늘이 마지막인 것처럼 사세요."}]}, {"num": 18, "term": "조차", "meaning": "Ngay cả... cũng (nhấn mạnh mức độ, thường mang sắc thái tiêu cực)", "blocks": [["p", "<b>1. '조차' thể hiện sự việc ngoài dự đoán của người nói lại tiếp tục xảy ra, có chức năng thay thế cho trợ từ cách. Không dùng trong câu mệnh lệnh hoặc câu rủ rê.</b>"], ["ex", "<b>너조차</b> 그런 말을 하니? *(Dùng thay cho trợ từ chủ cách)", "Đến cả cậu mà cũng nói lời như thế sao?"], ["ex", "강도가 나한테서 돈도 빼앗고 <b>시계조차</b> 빼앗아 갔다. *(Dùng thay", "cho trợ từ tân ngữ) (Tên trộm vừa cướp tiền của tớ mà đến cả đồng hồ cũng cướp đi mất."], ["p", "<b>2. Lý do các câu dưới đây thành câu sai ngữ pháp là do '조차' mang nghĩa ngoài dự đoán của người nói lại được dùng trong câu mệnh lệnh và câu rủ rê.</b>"], ["ex", "너조차 멀리 가버려라. (X)", "Đến cả cậu cũng hãy đi xa đi."], ["ex", "너조차 힘을 내자. (X)", "Đến cả cậu chúng mình cùng cố lên nào."]], "practice": [{"vn": "Ngay cả nước tôi cũng không uống nổi.", "hint": "물/마시다", "answer": "물조차 못 마시겠어요."}, {"vn": "Ngay cả tên anh ấy tôi cũng không nhớ.", "hint": "그/이름/기억하다", "answer": "그의 이름조차 기억이 안 나요."}, {"vn": "Ngay cả một lời cảm ơn cũng không có.", "hint": "고맙다는 말/없다", "answer": "고맙다는 말 한마디조차 없었어요."}]}, {"num": 19, "term": "치고", "meaning": "Nói chung là, thường thì (đặc điểm chung của một loại/nhóm)", "blocks": [["p", "Là trợ từ bổ trợ chủ yếu thể hiện ý nghĩa 'bao hàm toàn bộ không ngoại lệ'. Gắn sau danh từ thể hiện ý nghĩa 'bao hàm toàn bộ mà không có cái nào bị sót' hoặc 'có tư cách phù hợp một cách đương nhiên'."], ["p", "<b>1. Thể hiện ý nghĩa 'nếu nhìn bao hàm toàn bộ không có ngoại lệ'.</b>"], ["ex", "<b>교사치고</b> 자기 학생을 사랑하지 않는 사람은 없다.", "Đã là giáo viên thì không có ai là không yêu thương học sinh của mình."], ["ex", "<b>한국인치고</b> 김치 맛을 모르는 사람은 없다.", "Đã là người Hàn Quốc thì không có ai là không biết vị kim chi."], ["p", "<b>2. Thể hiện ý nghĩa 'ngoại lệ', tức là thoát khỏi trạng thái thông thường.</b>"], ["ex", "<b>외국인치고는</b> 한국말을 잘 하는 편이다.", "So với là người nước ngoài thì thuộc dạng nói tiếng Hàn giỏi."], ["ex", "<b>겨울치고는</b> 요즘 날씨는 춥지 않은 셈이다.", "So với là mùa đông thì thời tiết dạo này xem như là không lạnh."], ["p", "<b>3. Thể hiện việc bao hàm toàn bộ mọi trường hợp với nghĩa 'bất kể là cái nào đi nữa'.</b>"], ["ex", "이 <b>마을치고</b> 어느 집에나 컴퓨터가 없는 집이 없다.", "Ở cái làng này chẳng có nhà nào là không có máy tính."], ["ex", "사람 하나를 더 구하는 <b>셈치고</b> 구인 광고를 냈 다.", "Coi như là tìm thêm một người nữa, tôi đã đăng quảng cáo tuyển dụng."]], "practice": [{"vn": "Nói chung con trai thì thích chơi game.", "hint": "남자/게임/좋아하다", "answer": "남자치고 게임을 안 좋아하는 사람이 없다."}, {"vn": "Nói chung là mùa đông năm nay ấm.", "hint": "올해/겨울/따뜻하다", "answer": "올해 겨울은 겨울치고 따뜻하다."}, {"vn": "So với là học sinh mới thì cậu ấy giỏi quá.", "hint": "신입생/잘하다", "answer": "신입생치고 너무 잘한다."}]}, {"num": 20, "term": "한테서", "meaning": "Từ (ai đó) (giống '에게서', mang tính khẩu ngữ)", "blocks": [["p", "Là trợ từ cách kết hợp với danh từ chỉ người hoặc động vật trong câu để thể hiện hành động của vị ngữ phát sinh từ chủ thể đó."], ["bq", ["<b>Tìm hiểu thêm | So sánh '한테서' và '에게서'</b>", "Chủ yếu <b>'에게서'</b> dùng trong văn viết (문어체), còn <b>'한테서'</b>", "dùng trong văn nói (구어체)."]], ["ex", "이건 철수<b>에게서/한테서</b> 받은 선물이다.", "Đây là món quà tớ nhận được từ Cheol-soo."], ["ex", "이 강아지<b>에게서/한테서</b> 무슨 냄새가 납니다.", "Từ chú chó này phát ra mùi gì đó."], ["ex", "친구<b>에게서/한테서</b> 생일잔치 초대를 받았습니다.", "Tôi đã nhận được lời mời dự tiệc sinh nhật từ bạn."], ["p", "IV. BIỂU HIỆN KẾT HỢP"]], "practice": [{"vn": "Tôi đã nhận được lá thư từ bạn.", "hint": "친구/편지/받다", "answer": "친구한테서 편지를 받았어요."}, {"vn": "Tôi đã nghe tin đó từ anh trai.", "hint": "형/소식/듣다", "answer": "형한테서 그 소식을 들었어요."}, {"vn": "Tôi đã mượn tiền từ bạn tôi.", "hint": "친구/돈/빌리다", "answer": "친구한테서 돈을 빌렸어요."}]}], "boghap": [{"num": 1, "term": "-(으)ㄴ/는 수가 있다", "meaning": "Có khả năng/trường hợp là... (khả năng xảy ra, thường không mong muốn)", "blocks": [["p", "<b>1. Thể hiện khả năng của thực tế hoặc xác suất nhỏ xảy ra hành động.</b>"], ["ex", "차가 막히면 늦게 <b>오는 수가 있어요</b>.", "Nếu tắc đường thì cũng có khả năng là sẽ đến muộn đấy."], ["ex", "원숭이도 나무에서 <b>떨어지는 수가 있지요</b>.", "Khỉ cũng có lúc bị trượt ngã khỏi cây chứ."], ["p", "<b>2. Không mấy khi dùng với động từ trạng thái. Khi dùng với động từ trạng thái, nó chỉ thể hiện danh từ phụ thuộc '수' mang nghĩa 'phương pháp,手段 (thủ đoạn)'.</b>"], ["ex", "좋은 <b>수가 있으니</b> 걱정 마세요.", "Có phương án hay nên đừng lo lắng."]], "practice": [{"vn": "Nếu đi trễ có thể sẽ bị phạt đấy.", "hint": "늦다/벌/받다", "answer": "늦으면 벌을 받는 수가 있어요."}, {"vn": "Ngay cả khỉ cũng có lúc rơi từ trên cây.", "hint": "원숭이/나무/떨어지다", "answer": "원숭이도 나무에서 떨어지는 수가 있지요."}, {"vn": "Đôi khi cũng có trường hợp thất bại.", "hint": "가끔/실패하다", "answer": "가끔은 실패하는 수가 있어요."}]}, {"num": 2, "term": "-(으)면 몰라도", "meaning": "Nếu là... thì còn có thể (chấp nhận được), chứ...(thì không thể)", "blocks": [["p", "<b>1. Là lời nói nhấn mạnh mệnh đề đứng trước, bổ sung thêm một cách nhẹ nhàng rằng trong điều kiện giống như mệnh đề trước thì vẫn có ngoại lệ.</b>"], ["ex", "유명한 화가의 <b>작품이면 몰라도</b> 너무 비싸군요.", "Nếu là tác phẩm của họa sĩ nổi tiếng thì không nói làm gì, đằng này đắt quá đấy."], ["ex", "한국에 <b>살았으면 몰라도</b> 한국말을 그렇게 잘 하기는 힘들어요.", "Nếu đã từng sống ở Hàn Quốc thì không nói làm gì, đằng này nói tiếng Hàn giỏi như thế là rất khó."], ["p", "<b>2. Kết hợp với vĩ tố thể hiện sự trích dẫn dùng dưới các dạng: '(이)라면 몰라도', '-(으)ㄴ/는다면 몰라도', '-(느/으)냐면 몰라도', '-(으)라면 몰라도', '-자면 몰라도'.</b>"]], "practice": [{"vn": "Nếu là trẻ con thì còn có thể tha thứ, chứ người lớn thì không được như vậy.", "hint": "아이/이해하다/어른", "answer": "아이라면 몰라도 어른이 그러면 안 돼요."}, {"vn": "Nếu có tiền thì còn có thể đi, chứ bây giờ thì không đi được.", "hint": "돈/있다/가다", "answer": "돈이 있으면 몰라도 지금은 갈 수 없어요."}, {"vn": "Nếu khỏe thì còn có thể làm, chứ ốm thế này thì không làm được.", "hint": "건강하다/일하다", "answer": "건강하면 몰라도 아프면 일을 못 해요."}]}, {"num": 3, "term": "-(으)ㄴ/는 척하다", "meaning": "Giả vờ, làm ra vẻ...", "blocks": [["p", "[Gắn vào động từ hoặc '있다', '없다'] Là biểu hiện thể hiện việc giả vờ làm một hành vi nào đó một cách xảo quyệt. Vĩ tố định ngữ '-는' kết hợp với bổ động từ '척하다'."], ["p", "<b>1. Giả vờ một cách xảo quyệt như thể đang làm như vậy dù thực tế không làm hành vi đó.</b>"], ["ex", "만화책을 보면서 <b>공부하는 척했어요</b>.", "Vừa xem truyện tranh vừa giả vờ như đang học bài."], ["ex", "방에서 <b>자느 척했어요</b>.", "Ở trong phòng giả vờ như đang ngủ."], ["p", "<b>2. Khi nói về tình huống trong quá khứ, dùng dạng '-(으)ㄴ 척하다' đối với động từ.</b>"], ["ex", "나를 못 <b>본 척하더라</b>.", "Nó giả vờ như không nhìn thấy tớ."], ["ex", "밥을 먹지 않았는데도 <b>먹은 척했다</b>.", "Dù chưa ăn cơm nhưng vẫn giả vờ như đã ăn rồi."], ["p", "<b>3. '-는 체하다' mang ý nghĩa gần như tương đương với '-는 척하다'.</b>"], ["ex", "나는 답을 알고도 <b>모르는 체했다</b>.", "Tôi dù biết đáp án nhưng vẫn giả vờ như không biết."]], "practice": [{"vn": "Anh ấy giả vờ như không biết gì.", "hint": "그/모르다", "answer": "그는 모르는 척했다."}, {"vn": "Tôi đã giả vờ ngủ.", "hint": "자다", "answer": "자는 척했어요."}, {"vn": "Cô ấy giả vờ vui vẻ.", "hint": "그녀/기쁘다", "answer": "그녀는 기쁜 척했다."}]}, {"num": 4, "term": "-아/어/여 내다", "meaning": "Làm cho xong, hoàn thành (nỗ lực đến cùng để đạt được điều gì)", "blocks": [["p", "Thể hiện ý nghĩa dùng sức lực của chủ ngữ để hoàn thành, làm xong xuôi một việc nào đó."], ["ex", "꾸준히 노력은 기적을 <b>만들어 낸다</b>.", "Nỗ lực kiên trì sẽ tạo ra được kỳ tích."], ["ex", "그 사람은 고통을 <b>견뎌 내고</b> 마침내 건강을 되찾았어요.", "Người đó đã chịu đựng vượt qua đau đớn và cuối cùng đã lấy lại được sức khỏe."], ["bq", ["<b>Tìm hiểu thêm | Ứng dụng của '-아/어/여 내다'</b>", "<b>1.</b> Để thể hiện biểu hiện mạnh mẽ hơn, nó cũng được kết hợp sử dụng", "với các bổ động từ khác như '-고 말다', '-아/어 버리다'."]], ["ex", "그들은 결국 상대 팀을 <b>이겨 내고 말 것이다</b>.", "Rốt cuộc họ sẽ vượt qua và đánh bại đối thủ cho mà xem."], ["ex", "그 사람에게 반드시 사과를 <b>받아 내 버리고 말겠다</b>.", "Tôi nhất định sẽ đòi bằng được lời xin lỗi từ người đó."], ["bq", ["<b>2.</b> Kết hợp với vĩ tố nối '-아/어서', nhưng lược bỏ '-서' để dùng", "dưới dạng giống như bổ động từ. Lúc này '내다' là bản động từ mang", "nghĩa 'nộp/đệ trình'."]], ["ex", "자기 소개서와 이력서를 <b>써(서) 내세요</b>.", "Hãy viết rồi nộp bản giới thiệu bản thân và sơ yếu lý lịch nhé."], ["ex", "사진을 <b>붙여(서) 내</b> 주시기 바랍니다.", "Xin vui lòng dán ảnh rồi nộp ạ."]], "practice": [{"vn": "Tôi đã hoàn thành bài tập đến cuối cùng.", "hint": "숙제/끝내다", "answer": "숙제를 끝내 냈어요."}, {"vn": "Cuối cùng anh ấy cũng đã vượt qua được khó khăn.", "hint": "결국/어려움/이겨내다", "answer": "결국 어려움을 이겨 냈다."}, {"vn": "Tôi đã tìm ra được câu trả lời.", "hint": "답/찾다", "answer": "답을 찾아 냈어요."}]}, {"num": 5, "term": "-아/어/여 버리다", "meaning": "...luôn, ...mất (hoàn thành dứt khoát, thường mang ý nhẹ nhõm hoặc tiếc nuối)", "blocks": [["p", "Chứa đựng tâm trạng của người nói do hành động đã hoàn thành. Thể hiện sự nhẹ nhõm sảng khoái đến từ việc trút bỏ được gánh nặng tâm lý, sự tiếc nuối do đi trái với kỳ vọng, và sự nhấn mạnh hành động."], ["ex", "일을 다 <b>끝내 버렸어요</b>.", "Tôi đã giải quyết xong xuôi hết công việc rồi."], ["ex", "기분 나쁜 일은 기억에서 <b>지워 버리세요</b>.", "Những chuyện không vui hãy xóa sạch khỏi ký ức đi nhé."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-아/어/여 버리다' và '-고 말다'</b>", "<b>1. -아/어/여 버리다:</b> Chủ yếu thể hiện tâm lý của người nói."]], ["ex", "나는 너무 화가 나서 그가 준 편지를 <b>찢어 버렸다</b>.", "Tôi quá tức giận nên đã xé nát lá thư anh ấy đưa."], ["ex", "선생님께 혼이 날까 두려워 그만 거짓말을 <b>해 버렸다</b>.", "Sợ bị thầy/cô mắng nên tôi đã lỡ nói dối mất rồi."], ["bq", ["<b>2. -고 말다:</b> Chủ yếu thể hiện kết cục của sự thật hoặc sự việc."]], ["ex", "유민은 낮잠을 자서 학교에 지각을 <b>하고 말았다</b>.", "Yu-min ngủ nướng nên rốt cuộc đã bị trễ học."], ["ex", "민준은 지갑을 손에 들고 다니다가 <b>잃어버리고 말았다</b>.", "Min-jun cầm ví trên tay đi qua đi lại rồi rốt cuộc làm mất tiêu."]], "practice": [{"vn": "Tôi đã ăn hết sạch cả phần cơm luôn.", "hint": "밥/다/먹다", "answer": "밥을 다 먹어 버렸어요."}, {"vn": "Anh ấy đã rời đi mất rồi.", "hint": "그/떠나다", "answer": "그는 떠나 버렸다."}, {"vn": "Tôi đã vứt hết đồ cũ đi luôn.", "hint": "오래된 물건/버리다", "answer": "오래된 물건을 다 버려 버렸어요."}]}, {"num": 6, "term": "-(으)ㄴ/는 끝에", "meaning": "Sau khi (trải qua quá trình gì đó) cuối cùng", "blocks": [["p", "Dùng với nghĩa hành động ở mệnh đề sau được thực hiện sau khi đã làm hành động ở mệnh đề trước, thể hiện quá trình tiến hành hành động ở mệnh đề trước kéo dài và mệt mỏi/khó khăn."], ["p", "<b>1. Trường hợp kết hợp với động từ hành động: Thể hiện chuyển động hoặc hình dáng của động từ phía trước.</b>"], ["ex", "여기저기 <b>알아본 끝에</b> 친구가 부산에 산다는 것을 알게 되었어요.", "Sau khi tìm hiểu khắp nơi, tôi đã biết được việc bạn tôi đang sống ở Busan."], ["ex", "오랜 연구에 <b>매달린 끝에</b> 신제품 개발에 성공했다.", "Sau khi lao vào nghiên cứu thời gian dài, chúng tôi đã thành công phát triển sản phẩm mới."], ["p", "<b>2. Kết hợp với vĩ tố dạng định ngữ hồi tưởng '-던' thành dạng '-던 끝에': Có ý nghĩa hồi tưởng lại quá trình tiến hành của hành động phía trước.</b>"], ["ex", "며칠을 두고 하숙집을 <b>찾던 끝에</b> 방을 구했어요.", "Sau mấy ngày tìm kiếm nhà trọ, tôi đã tìm được phòng."], ["ex", "<b>궁리하던 끝에</b> 해결책을 찾았어요.", "Sau một hồi vắt óc suy nghĩ, tôi đã tìm ra phương án giải quyết."], ["p", "<b>3. Trường hợp dùng '끝에' sau danh từ chỉ hành động về mặt ý nghĩa: Lúc này bản thân danh từ đóng vai trò như một định ngữ.</b>"], ["ex", "<b>고생 끝에</b> 낙이 온다.", "Khổ tận cam lai / Sau gian khổ sẽ đến ngày vui)."], ["ex", "긴 <b>장마 끝에</b> 보는 햇빛이라 더욱 반가웠다.", "Là ánh nắng nhìn thấy sau đợt mưa dầm kéo dài nên lại càng đáng mừng hơn."]], "practice": [{"vn": "Sau nhiều lần cố gắng, cuối cùng tôi đã thành công.", "hint": "여러 번/노력하다/성공하다", "answer": "여러 번 노력한 끝에 성공했어요."}, {"vn": "Sau khi suy nghĩ nhiều, cuối cùng tôi đã quyết định.", "hint": "고민하다/결정하다", "answer": "고민한 끝에 결정했어요."}, {"vn": "Sau cuộc tranh luận dài, họ đã đạt được thỏa thuận.", "hint": "긴/토론/합의하다", "answer": "긴 토론 끝에 합의했다."}]}, {"num": 7, "term": "-기 나름이다", "meaning": "Tùy thuộc vào cách (làm gì) mà kết quả sẽ khác nhau", "blocks": [["p", "Chủ ngữ của câu là một mệnh đề danh từ nghi vấn, hoặc là thứ có tính hai mặt về mặt ý nghĩa, thể hiện ý nghĩa phụ thuộc vào ý nghĩa chứa đựng trong dạng danh từ '-기'."], ["ex", "찬성한 것이 잘한 것인지 아닌지는 <b>생각하기 나름입니다</b>.", "Việc tán thành là đúng hay không là tùy thuộc vào suy nghĩ của mỗi người."], ["ex", "가전제품의 수명은 <b>사용하기 나름입니다</b>.", "Tuổi thọ của đồ điện gia dụng là tùy thuộc vào cách sử dụng."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄹ 나름이다' và '나름(으로)'</b>", "<b>1.</b> Dùng dạng '-(으)ㄹ 나름이다' với ý nghĩa tương tự như '-기", "나름이다'."]], ["ex", "성공하고 못하고는 자기가 <b>할 나름이다</b>.", "Thành công hay không là tùy thuộc vào việc bản thân làm."], ["ex", "아이들의 인성은 부모가 <b>교육할 나름이다</b>.", "Nhân cách của trẻ em là tùy thuộc vào việc giáo dục của bố mẹ."], ["bq", ["<b>2.</b> '나름' cũng được dùng bằng cách gắn vào đại từ nhân xưng như", "'나' (tôi) hoặc đại từ thông thường để thể hiện ý nghĩa 'tự bản", "thân' hoặc 'tự suy đoán'."]], ["ex", "이번 일은 <b>나 나름으로</b> 신경을 썼다.", "Lần này tớ đã tâm huyết theo cách của riêng tớ."], ["ex", "형은 <b>형 나름으로</b> 가족을 위해 애쓴 것 같다.", "Anh trai có vẻ đã cố gắng vì gia đình theo cách riêng của anh ấy."]], "practice": [{"vn": "Hạnh phúc tùy thuộc vào cách suy nghĩ của mỗi người.", "hint": "행복/생각하다", "answer": "행복은 생각하기 나름이에요."}, {"vn": "Kết quả tùy thuộc vào cách bạn nỗ lực.", "hint": "결과/노력하다", "answer": "결과는 노력하기 나름이에요."}, {"vn": "Mọi việc đều tùy thuộc vào cách bạn làm.", "hint": "모든 일/하다", "answer": "모든 일은 하기 나름이에요."}]}, {"num": 8, "term": "-(으)ㄴ/는 김에", "meaning": "Nhân tiện (làm gì), tranh thủ lúc đang làm gì đó", "blocks": [["p", "Thể hiện tiện thể thực hiện hành động ở mệnh đề sau nhân cơ hội đang thực hiện hành động ở mệnh đề trước. Mục đích ban đầu nằm ở hành động ở mệnh đề trước."], ["ex", "여기까지 <b>온 김에</b> 친구를 만나 보고 가야겠어요.", "Tiện đường đã đến tận đây rồi, tớ phải gặp bạn một tẹo rồi mới đi."], ["ex", "슈퍼에 <b>간 김에</b> 아침에 먹을 빵도 샀다.", "Tiện thể đi siêu thị, tớ đã mua luôn cả bánh mì để ăn sáng."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄴ/는 김에' và '-는 길에'</b>", "<b>1. -(으)ㄴ/는 김에:</b> Có thể dùng cho mọi động từ hành động có thể", "làm kết hợp/kèm theo."]], ["ex", "문구점에 <b>가는 김에</b> 지우개도 사 와야겠어.", "Nhân tiện đi đến cửa hàng văn phòng phẩm, tớ phải mua luôn cả cục tẩy về mới được."], ["ex", "새 옷을 <b>입은 김에</b> 사진이나 많이 찍자.", "Nhân tiện đã mặc quần áo mới, chúng mình chụp thật nhiều ảnh nào."], ["bq", ["<b>2. -는 길에:</b> Chỉ có thể dùng với các động từ mang ý nghĩa di", "chuyển (như đi, về)."]], ["ex", "학교 <b>가는 길에</b> 꽃집에 들러서 꽃을 샀다.", "Trên đường đến trường tớ đã ghé vào cửa hàng hoa mua hoa."], ["ex", "경수는 <b>퇴근하는 길에</b> 승원이를 만나 저녁을 먹었다.", "Gyeong-su trên đường tan làm đã gặp Seung-won rồi ăn tối."]], "practice": [{"vn": "Nhân tiện đi chợ, tôi đã mua luôn rau.", "hint": "시장/가다/채소/사다", "answer": "시장에 간 김에 채소도 샀어요."}, {"vn": "Nhân tiện dọn dẹp, hãy vứt luôn đồ không cần.", "hint": "청소하다/필요없는 물건/버리다", "answer": "청소하는 김에 필요없는 물건도 버리세요."}, {"vn": "Nhân tiện ra ngoài, tôi đã ghé qua bưu điện.", "hint": "나가다/우체국/들르다", "answer": "나간 김에 우체국에 들렀어요."}]}, {"num": 9, "term": "-(으)ㄴ/는/(으)ㄹ 경우에", "meaning": "Trong trường hợp (nào đó xảy ra)", "blocks": [["p", "Gắn vào động từ để thể hiện điều kiện hoặc thời điểm như vậy."], ["ex", "급한 일이 <b>있는 경우에는</b> 비상벨을 누릅니다.", "Trong trường hợp có việc gấp thì hãy nhấn chuông khẩn cấp."], ["ex", "사고가 <b>발생했을 경우엔</b> 119로 전화를 하세요.", "Trong trường hợp xảy ra tai nạn thì hãy gọi điện đến số 119."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄹ 경우(에)' và '-(으)ㄹ 때(에)'</b>", "<b>1. -(으)ㄹ 경우(에):</b> Chủ yếu có khuynh hướng thể hiện tình huống."]], ["ex", "<b>아플 경우</b> 어떻게 할지 생각해 둡시다. *(Hãy suy nghĩ trước xem", "trong trường hợp bị ốm thì sẽ làm thế nào nhé."], ["ex", "실패가 계속해서 <b>반복될 경우</b> 우리는 우울증에 빠지기 쉽다. *(Trong", "trường hợp thất bại tiếp tục lặp đi lặp lại thì chúng ta rất dễ rơi vào trầm cảm."], ["bq", ["<b>2. -(으)ㄹ 때(에):</b> Chủ yếu có khuynh hướng thể hiện thời gian một", "cách cụ thể."]], ["ex", "내가 한국에 <b>올 때</b> 친구가 배웅을 해주었다. *(Lúc tôi đến Hàn", "Quốc, bạn tôi đã ra tiễn."], ["ex", "나는 <b>운동할 때</b> 주로 음악을 듣는다. *(Tôi thường nghe nhạc những", "lúc tập thể thao."]], "practice": [{"vn": "Trong trường hợp khẩn cấp hãy gọi số này.", "hint": "긴급하다/경우/전화하다", "answer": "긴급한 경우에 이 번호로 전화하세요."}, {"vn": "Trong trường hợp trời mưa, chúng ta sẽ hoãn lại.", "hint": "비/오다/경우/미루다", "answer": "비가 오는 경우에 미룰 거예요."}, {"vn": "Trong trường hợp thất bại thì hãy thử lại.", "hint": "실패하다/경우/다시/시도하다", "answer": "실패하는 경우에 다시 시도하세요."}]}, {"num": 10, "term": "-기에는/-기로는", "meaning": "Xét về mặt... thì (đánh giá từ một góc độ nhất định)", "blocks": [["p", "Dùng khi nói ra suy nghĩ của bản thân dựa trên điều suy đoán hoặc câu chuyện đã nghe được."], ["ex", "제가 <b>보기에는</b> 이 옷이 제일 잘 어울리는 것 같아요.", "Theo như tôi thấy thì bộ quần áo này có vẻ hợp nhất đấy."], ["ex", "내가 <b>듣기로는</b> 이번 주말에 영화를 보러 간대.", "Theo như tớ nghe nói thì cuối tuần này nó đi xem phim đấy."]], "practice": [{"vn": "Xét về giá cả thì hơi đắt.", "hint": "가격/비싸다", "answer": "가격이 비싸기에는 좀 그래요."}, {"vn": "Xét về thời gian thì hơi ngắn.", "hint": "시간/짧다", "answer": "시간이 짧기로는 좀 부족해요."}, {"vn": "Xét về chất lượng thì khá tốt.", "hint": "품질/좋다", "answer": "품질이 좋기로는 꽤 괜찮아요."}]}, {"num": 11, "term": "-ㄴ/는다든지", "meaning": "Đại loại như là..., hay như là...(liệt kê ví dụ, mang tính coi nhẹ)", "blocks": [["p", "Gắn vào động từ để thể hiện việc lựa chọn bất kỳ cái nào trong số nhiều sự thật, hoặc dù có lựa chọn cái nào trong số đó thì cũng không quan trọng."], ["ex", "건강이 좋지 않으니까 휴학을 <b>한다든지</b> 해야 할 것 같아요.", "Vì sức khỏe không tốt nên có lẽ phải làm những việc như xin bảo lưu học tập xem sao."], ["ex", "의견을 물으면 <b>좋다든지 나쁘다든지</b> 대답을 해야지요.", "Hỏi ý kiến thì phải trả lời xem là tốt hay xấu chứ."]], "practice": [{"vn": "Đại loại như là đi chơi hay là đi mua sắm.", "hint": "놀다/쇼핑하다", "answer": "논다든지 쇼핑한다든지 해요."}, {"vn": "Đại loại như là đọc sách hay xem phim.", "hint": "책/읽다/영화/보다", "answer": "책을 읽는다든지 영화를 본다든지 해요."}, {"vn": "Đại loại như là ngủ hay nghỉ ngơi ở nhà.", "hint": "자다/집/쉬다", "answer": "잔다든지 집에서 쉰다든지 해요."}]}, {"num": 12, "term": "-(으)랴 -(으)랴", "meaning": "Vừa phải..., vừa phải... (liệt kê nhiều việc phải làm cùng lúc, vất vả)", "blocks": [["p", "Dùng khi thể hiện bận rộn do phải làm từ hai hành vi trở lên cùng lúc, hoặc do bận rộn nên vất mệt mỏi. Do đó, mệnh đề sau thường đi kèm với các từ mang nghĩa bận rộn."], ["ex", "사무실에 나오면 이거 <b>하랴</b> 저거 <b>하랴</b> 눈코 뜰 새가 없습니다.", "Hễ đến văn phòng là nào làm cái này, nào làm cái kia, bận tối mắt tối mũi chẳng rảnh tay tẹo nào."], ["ex", "빨래<b>하랴</b> 설거지<b>하랴</b> 손에 물이 마를 날이 없어요.", "Nào là giặt giũ, nào là rửa bát, chẳng có ngày nào là tay được khô ráo."]], "practice": [{"vn": "Tôi vừa phải đi làm vừa phải chăm con, thật vất vả.", "hint": "일하다/아이/돌보다", "answer": "일하랴 아이를 돌보랴 정신이 없어요."}, {"vn": "Cô ấy vừa phải học vừa phải làm thêm.", "hint": "공부하다/아르바이트하다", "answer": "공부하랴 아르바이트하랴 바빠요."}, {"vn": "Tôi vừa phải nấu ăn vừa phải dọn dẹp.", "hint": "요리하다/청소하다", "answer": "요리하랴 청소하랴 정신없었어요."}]}, {"num": 13, "term": "-기에/(으)니까/길래 망정이지", "meaning": "May mà... (nếu không thì đã xảy ra chuyện xấu)", "blocks": [["p", "Dùng ở dạng '망정이지', kết hợp với từ phủ định để thể hiện ý nghĩa 'may mà đã... nên mới tốt/không sao'. Thường dùng phía sau '-(으)니', '-기에', '-길래'."], ["ex", "음식을 많이 <b>준비했으니 망정이지</b> 모자랄 뻔했어요.", "May mà đã chuẩn bị nhiều thức ăn đấy, chứ không suýt nữa thì thiếu rồi."], ["ex", "막차를 <b>탔기에 망정이지</b> 집에 못 들어왔을걸.", "May mà đã bắt kịp chuyến xe cuối đấy, chứ không thì chắc đã chẳng về được đến nhà rồi."]], "practice": [{"vn": "May mà tôi mang theo ô, nếu không thì đã bị ướt mưa rồi.", "hint": "우산/가져오다/젖다", "answer": "우산을 가져왔기에 망정이지 안 그랬으면 젖었을 거예요."}, {"vn": "May mà tôi đến sớm, nếu không thì đã bị trễ rồi.", "hint": "일찍/오다/늦다", "answer": "일찍 왔으니까 망정이지 늦을 뻔했어요."}, {"vn": "May mà tôi biết trước, nếu không thì đã bị lừa rồi.", "hint": "미리/알다/속다", "answer": "미리 알았기에 망정이지 속을 뻔했어요."}]}, {"num": 14, "term": "-기/게 마련이다", "meaning": "Vốn dĩ là như vậy, thường là như thế (quy luật tự nhiên)", "blocks": [["p", "<b>1. Thể hiện hành động hoặc sự thật đặt trước '-기' là điều tự nhiên hoặc đương nhiên. Do đó thường được dùng cho quy luật mang tính phổ biến hoặc chân lý, xuất hiện nhiều trong tục ngữ, thành ngữ.</b>"], ["ex", "주머니에 돈이 있으면 <b>쓰기 마련이다</b>.", "Trong túi mà có tiền thì đương nhiên là sẽ tiêu thôi."], ["ex", "팔은 안으로 <b>굽기 마련이다</b>.", "Máu chảy ruột mềm / Tay co vào trong chứ ai co ra ngoài)."], ["p", "<b>2. '-기 마련이다' được dùng với ý nghĩa tương tự như '-게 마련이다'. '-게 마련이다' dùng vĩ tố phó từ '-게' gắn vào động từ để bổ nghĩa cho '마련이다' đứng sau, có thể thay thế hoàn toàn cho '-기 마련이다'.</b>"]], "practice": [{"vn": "Con người vốn dĩ ai cũng sẽ già đi.", "hint": "사람/늙다", "answer": "사람은 늙기 마련이에요."}, {"vn": "Càng cố gắng thì càng đạt được kết quả tốt, đó là lẽ thường.", "hint": "노력하다/좋은 결과/얻다", "answer": "노력하면 좋은 결과를 얻기 마련이에요."}, {"vn": "Ai cũng sẽ mắc lỗi, đó là chuyện thường tình.", "hint": "실수/하다", "answer": "누구나 실수하기 마련이에요."}]}, {"num": 15, "term": "-(으)ㄴ/는 법이다", "meaning": "Vốn là quy luật, đạo lý là như vậy", "blocks": [["p", "Thể hiện quy luật tự nhiên hoặc 'việc đương nhiên sẽ trở nên như vậy'."], ["ex", "좋은 말도 여러 번 들으면 듣기 <b>싫은 법이다</b>.", "Lời hay ý đẹp nghe nhiều lần quá thì cũng thành ra chán nghe."], ["ex", "작은 고추가 <b>매운 법이다</b>.", "Ớt nhỏ thì mớiเผ็ด / Nhỏ mà có võ)."]], "practice": [{"vn": "Có vay thì có trả, đó là quy luật.", "hint": "빌리다/갚다", "answer": "빌린 것은 갚는 법이에요."}, {"vn": "Chăm chỉ thì sẽ thành công, đó là đạo lý.", "hint": "열심히/하다/성공하다", "answer": "열심히 하면 성공하는 법이에요."}, {"vn": "Có nhân quả thì ắt có kết quả, đó là lẽ tự nhiên.", "hint": "원인/있다/결과/있다", "answer": "원인이 있으면 결과가 있는 법이에요."}]}, {"num": 16, "term": "-ㄴ/는 이상", "meaning": "Một khi đã..., đã là... rồi thì", "blocks": [["p", "<b>1. [Gắn vào động từ] Dùng với nghĩa 'nếu cái đó đã là sự thật đã rồi (sự thật đã định)'.</b>"], ["ex", "한국어 공부를 <b>시작한 이상</b> 한국 친구 사귀기는 문제 없다.", "Một khi đã bắt đầu học tiếng Hàn thì việc kết bạn người Hàn Quốc không có vấn đề gì cả."], ["ex", "물러나기로 결심을 <b>굳힌 이상</b> 더 기다릴 필요가 없다고 판단했어요.", "Một khi đã hạ quyết tâm rút lui thì tôi nhận định rằng không cần phải chờ đợi thêm nữa."], ["p", "<b>2. [Gắn vào tính từ] Dùng với nghĩa 'nếu cái đó đã là sự thật đã được quyết định'.</b>"], ["ex", "그것이 문학의 <b>본질인 이상</b> 중요하게 다루지 않을 수 없다.", "Một khi đó đã là bản chất của văn học thì không thể không xử lý một cách quan trọng."], ["ex", "노동 운동가라 할지라도 근로자가 <b>아닌 이상은</b> 구성원이 될 수 없다.", "Dù có là nhà hoạt động lao động đi chăng nữa, một khi không phải là người lao động thì không thể trở thành thành viên được."]], "practice": [{"vn": "Một khi đã quyết định rồi thì hãy làm đến cùng.", "hint": "결정하다/끝까지/하다", "answer": "결정한 이상 끝까지 하세요."}, {"vn": "Một khi đã hứa rồi thì phải giữ lời.", "hint": "약속하다/지키다", "answer": "약속한 이상 지켜야 해요."}, {"vn": "Đã là học sinh rồi thì phải học hành chăm chỉ.", "hint": "학생/열심히/공부하다", "answer": "학생인 이상 열심히 공부해야 해요."}]}, {"num": 17, "term": "-다가도", "meaning": "Đang... thì bỗng (thay đổi đột ngột, trái ngược)", "blocks": [["p", "Là biểu현 thể hiện một hành vi hay trạng thái nào đó dễ dàng chuyển sang một hành vi hay trạng thái khác. Là sự kết hợp giữa vĩ tố '-다가' và trợ từ '도'."], ["p", "<b>1. Thể hiện một hành vi hay trạng thái dễ dàng chuyển sang hành vi hay trạng thái khác.</b>"], ["ex", "아이는 <b>자다가도</b> 사탕이라면 벌떡 일어난다.", "Đứa trẻ dù đang ngủ mà nghe nói đến kẹo là bật dật ngay."], ["ex", "아이들은 원래 <b>웃다가도</b> 우는 법이다.", "Trẻ con vốn dĩ đang cười đấy rồi lại khóc ngay được."], ["p", "<b>2. Có biểu hiện quan dụng như '알다가도 모를 일이다/모르겠다' thể hiện ý nghĩa một sự việc nào đó không thể dễ dàng hiểu nổi.</b>"], ["ex", "어른들의 세계는 정말 <b>알다가도 모르겠어요</b>.", "Thế giới của người lớn thật sự là hiểu thế nào cũng không tài nào hiểu nổi."]], "practice": [{"vn": "Trời đang nắng bỗng lại mưa.", "hint": "날씨/맑다/비/오다", "answer": "날씨가 맑다가도 비가 온다."}, {"vn": "Cô ấy đang vui bỗng lại buồn.", "hint": "그녀/기쁘다/슬퍼하다", "answer": "그녀는 기쁘다가도 슬퍼한다."}, {"vn": "Tôi đang khỏe bỗng lại mệt.", "hint": "건강하다/피곤하다", "answer": "건강하다가도 피곤해진다."}]}, {"num": 18, "term": "-는 둥 마는 둥 (하다)", "meaning": "Làm nửa vời, không hoàn chỉnh", "blocks": [["p", "Là biểu hiện thể hiện việc không làm một hành vi nào đó một cách đàng hoàng, tử tế. Thể hiện sự kết hợp giữa vĩ tố '-다가' và trợ từ '도'."], ["p", "<b>1. Thể hiện việc thực hiện hành động phía sau trong trạng thái không thực hiện đàng hoàng hành động phía trước.</b>"], ["ex", "잠을 <b>자는 둥 마는 둥 하고</b> 일찍 나왔어요.", "Tôi ngủ chập chờn chẳng ra ngủ rồi dậy đi sớm."], ["ex", "회사 일이 바빠서 집안일을 <b>하는 둥 마는 둥</b> 통 신경을 못 쓴다.", "Công việc ở công ty bận rộn nên việc nhà làm qua loa đại khái, chẳng thể bận tâm đến được."], ["p", "<b>2. Khi nói về tình huống quá khứ dùng dạng '-(은)ㄴ 둥 만 둥', khi nói về tình huống tương lai dùng dạng '-(으)ㄹ 둥 말 둥' cho động từ.</b>"], ["ex", "얼굴을 <b>본 둥 만 둥</b> 그냥 지나갔다. *(Nhìn lướt qua mặt chẳng rõ", "rồi cứ thế đi qua."], ["ex", "아기가 잠을 <b>잘 둥 말 둥 하다가</b> 스르르 잠들었다. *(Em bé thiu", "thiu chập chờn rồi từ từ thiếp đi."]], "practice": [{"vn": "Tôi đã ăn cơm một cách nửa vời.", "hint": "밥/먹다", "answer": "밥을 먹는 둥 마는 둥 했어요."}, {"vn": "Anh ấy đã nghe một cách nửa vời.", "hint": "그/듣다", "answer": "그는 듣는 둥 마는 둥 했다."}, {"vn": "Tôi đã ngủ chập chờn không ngon giấc.", "hint": "자다", "answer": "자는 둥 마는 둥 했어요."}]}, {"num": 19, "term": "-(으)ㄹ까 말까 생각/고민 중이다", "meaning": "Đang phân vân có nên... hay không", "blocks": [["p", "Dùng khi chủ ngữ chưa thể lựa chọn và quyết định chắc chắn về ý định đối với hành động mà đang phân vân, do dự. Phía sau có thể dùng động từ khác thay cho '말다'. Chủ yếu chỉ hợp đi với động từ hành động."], ["ex", "너한테 이 비밀을 <b>얘기할까 말까 생각 중이다</b>.", "Tớ đang suy nghĩ xem có nên nói bí mật này với cậu hay không."], ["ex", "다음 학기에는 학교에 <b>올까 말까 고민 중이에요</b>.", "Học kỳ tới tớ đang trăn trở xem có nên đến trường nữa hay không."]], "practice": [{"vn": "Tôi đang phân vân có nên đi hay không.", "hint": "가다/고민", "answer": "갈까 말까 고민 중이에요."}, {"vn": "Tôi đang phân vân có nên mua hay không.", "hint": "사다/고민", "answer": "살까 말까 고민 중이에요."}, {"vn": "Tôi đang phân vân có nên nói với anh ấy hay không.", "hint": "그/말하다/생각", "answer": "그에게 말할까 말까 생각 중이에요."}]}, {"num": 20, "term": "-(으)ㄹ 겸(해서)", "meaning": "Nhân tiện để (làm gì đó luôn, kết hợp hai mục đích)", "blocks": [["p", "Thể hiện hành động đứng trước và hành động đứng sau được thực hiện đồng thời cùng một lúc."], ["ex", "한국말도 <b>배울 겸</b> 친척도 <b>만날 겸</b> 서울에 왔습니다.", "Tôi đến Seoul vừa để học tiếng Hàn vừa kết hợp gặp người thân luôn."], ["ex", "취미 생활도 <b>할 겸</b> 돈도 <b>벌 겸해서</b> 꽃 가게를 차렸습니다.", "Tôi đã mở cửa hàng hoa vừa kết hợp làm thỏa đam mê vừa kiếm tiền luôn."]], "practice": [{"vn": "Tôi đi mua sắm nhân tiện gặp bạn luôn.", "hint": "쇼핑하다/친구/만나다", "answer": "쇼핑할 겸 친구를 만날 겸 나갔어요."}, {"vn": "Tôi đi bộ để tập thể dục luôn.", "hint": "운동하다/산책하다", "answer": "운동할 겸 산책했어요."}, {"vn": "Tôi về quê để thăm bố mẹ luôn.", "hint": "고향/부모님/뵙다", "answer": "고향에 부모님을 뵐 겸 갔어요."}]}, {"num": 21, "term": "-(으)ㄹ 테지만", "meaning": "Chắc là sẽ... nhưng (dự đoán kèm nhượng bộ)", "blocks": [["p", "Thể hiện người nói chắc chắn về nội dung đứng trước, nhưng nội dung đứng sau có thể sẽ khác với điều đó."], ["ex", "지금은 놀면 <b>재미있을 테지만</b> 나중에 후회하게 될 거야.", "Bây giờ chơi thì chắc là vui đấy nhưng sau này sẽ phải hối hận đấy."], ["ex", "처음에는 익숙하지 <b>않을 테지만</b> 살다 보면 적응이 되기 마련이다.", "Ban đầu chắc là sẽ không quen đâu nhưng sống dần rồi thì đương nhiên sẽ thích nghi thôi."]], "practice": [{"vn": "Chắc là sẽ khó nhưng tôi vẫn muốn thử.", "hint": "어렵다/시도하다", "answer": "어려울 테지만 시도해 볼게요."}, {"vn": "Chắc là sẽ bận nhưng hãy cố gắng đến.", "hint": "바쁘다/오다", "answer": "바쁠 테지만 와 주세요."}, {"vn": "Chắc là sẽ mệt nhưng chúng ta phải làm xong.", "hint": "피곤하다/끝내다", "answer": "피곤할 테지만 끝내야 해요."}]}, {"num": 22, "term": "-기도 하고 -기도 하다", "meaning": "Lúc thì..., lúc thì... (thay đổi qua lại giữa hai trạng thái)", "blocks": [["p", "Thể hiện hành động hoặc trạng thái ở mệnh đề trước và mệnh đề sau xảy ra cùng một loại/song song."], ["ex", "주말에는 책을 <b>읽기도 하고</b> 낮잠을 <b>자기도 한다</b>.", "Cuối tuần tôi vừa đọc sách lại vừa ngủ nướng nữa."], ["ex", "점심을 <b>먹기도 하고</b> 안 먹고 <b>굶기도 해요</b>.", "Bữa trưa có khi tôi ăn, có khi lại không ăn mà nhịn luôn."]], "practice": [{"vn": "Tôi lúc thì vui lúc thì buồn.", "hint": "기쁘다/슬프다", "answer": "기쁘기도 하고 슬프기도 해요."}, {"vn": "Món ăn này lúc thì cay lúc thì ngọt.", "hint": "음식/맵다/달다", "answer": "이 음식은 맵기도 하고 달기도 해요."}, {"vn": "Anh ấy lúc thì chăm chỉ lúc thì lười biếng.", "hint": "그/부지런하다/게으르다", "answer": "그는 부지런하기도 하고 게으르기도 해요."}]}, {"num": 23, "term": "은/는 고사하고", "meaning": "Đừng nói tới..., chưa nói đến... (mà còn tệ hơn)", "blocks": [["p", "[Gắn vào danh từ] Là biểu hiện thể hiện việc so sánh danh từ trước và danh từ sau, để nói rằng danh từ đứng trước thì miễn bàn/chẳng cần nói tới, đó là việc không thể hoặc rất khó khăn. Là biểu hiện dùng trợ từ '는' kết hợp với động từ '고사하다'."], ["p", "<b>1. Thể hiện ý nghĩa danh từ trước khó/không thể đến mức miễn bàn, và ngay cả trường hợp mệnh đề sau dễ hơn mà cũng không dễ dàng hoặc hy vọng đạt được cái đó.</b>"], ["ex", "반에서 <b>일등은 고사하고</b> 꼴찌나 면했으면 좋겠습니다.", "Đứng nhất lớp thì miễn bàn rồi, ước gì trút được cái hạng bét là tốt lắm rồi."], ["ex", "<b>된장찌개는 고사하고</b> 라면도 잘 못 끓여요.", "Canh tương đậu thì miễn bàn rồi, ngay cả mì gói tôi cũng chẳng biết nấu cho ngon nữa."], ["p", "<b>2. Tình huống dùng '는 고사하고' nhìn chung mang tính phủ định. Do đó các câu sau là câu sai:</b>"], ["ex", "반에서 일등은 고사하고 전교에서도 일등이다. (X)", ""], ["ex", "저는 한국 요리는 고사하고 중국 요리도 잘합니다. (X)", ""], ["p", "<b>3. '는 고사하고' có thể thay thế bằng '는커녕' hoặc '는 말할 것도 없고'. Tuy nhiên '는 말할 것도 없고' dùng được cho cả tình huống tiêu cực lẫn tích cực, còn '는 고사하고' và '는커녕' chỉ dùng trong tình huống tiêu cực.</b>"], ["ex", "<b>된장찌개는 고사하고</b> 라면이라도 잘 끓였으면 좋겠어요. (O)", ""], ["ex", "<b>된장찌개는커녕</b> 라면이라도 잘 끓이면 좋겠어요. (O)", ""], ["ex", "<b>된장찌개는 말할 것도 없고</b> 라면이라도 잘 끓이면 좋겠어요. (O)", ""], ["ex", "반에서 일등은 고사하고 전교에서도 일등이다. (X)", ""], ["ex", "반에서 일등은커녕 전교에서도 일등이다. (X)", ""], ["ex", "<b>반에서 일등은 말할 것도 없고</b> 전교에서도 일등이다. (O)", ""]], "practice": [{"vn": "Đừng nói tới lời khen, tôi còn bị mắng.", "hint": "칭찬/야단맞다", "answer": "칭찬은 고사하고 야단맞았어요."}, {"vn": "Chưa nói đến việc giúp đỡ, anh ấy còn gây thêm rắc rối.", "hint": "돕다/문제/일으키다", "answer": "돕기는 고사하고 문제만 일으켰다."}, {"vn": "Đừng nói đến lương cao, công việc còn không ổn định.", "hint": "높은 월급/불안정하다", "answer": "높은 월급은 고사하고 일자리도 불안정해요."}]}, {"num": 24, "term": "-(으)려야 -(으)ㄹ 수가 없다", "meaning": "Dù có muốn... cũng không thể", "blocks": [["p", "Thể hiện dù người nói có ý chí và nỗ lực đến đâu đi nữa thì cũng không thể làm thêm được nữa, hoặc hành động đó là bất khả thi."], ["ex", "구경꾼이 많아서 <b>앉으려야 앉을 수가 없군요</b>.", "Người xem đông quá nên có muốn ngồi cũng chẳng thể nào ngồi được."], ["ex", "이제 나도 더 <b>참으려야 도저히 참을 수가 없다</b>.", "Bây giờ ngay cả tớ dù có muốn nhẫn nại thêm nữa thì cũng hoàn toàn không thể nhẫn nại nổi."]], "practice": [{"vn": "Dù có muốn quên cũng không thể quên được.", "hint": "잊다", "answer": "잊으려야 잊을 수가 없어요."}, {"vn": "Dù có muốn dừng lại cũng không thể dừng được.", "hint": "멈추다", "answer": "멈추려야 멈출 수가 없어요."}, {"vn": "Dù có muốn tin cũng không thể tin được.", "hint": "믿다", "answer": "믿으려야 믿을 수가 없어요."}]}, {"num": 25, "term": "에 비해(서)/비하여", "meaning": "So với... (thì)", "blocks": [["p", "[Gắn vào danh từ] Là biểu hiện thể hiện đối tượng so sánh."], ["p", "<b>1. Dùng khi danh từ đứng trước trở thành đối tượng so sánh và cho ra kết quả như nội dung phía sau.</b>"], ["ex", "승화는 <b>누리에 비해</b> 영어를 잘한다.", "Seung-hwa so với Nuri thì nói tiếng Anh giỏi hơn."], ["ex", "그 사람은 <b>아는 것에 비해서</b> 표현을 잘 못해.", "Người đó so với những gì biết được thì lại biểu đạt không tốt."], ["p", "<b>2. Có thể dùng dạng '에 비하면' mà không có sự khác biệt lớn về nghĩa. Nếu dùng dưới các dạng '에 비할 수 없다', '에 비할 것 없다', '에 비할 데 없다', '에 비할 바 아니다', '에 비할 것 아니다' thì mang ý nghĩa có giá trị đặc biệt đến mức không thể so sánh với cái khác.</b>"]], "practice": [{"vn": "So với năm ngoái, năm nay lạnh hơn.", "hint": "작년/올해/춥다", "answer": "작년에 비해서 올해가 더 추워요."}, {"vn": "So với giá cả, chất lượng khá tốt.", "hint": "가격/품질/좋다", "answer": "가격에 비해 품질이 좋아요."}, {"vn": "So với tuổi, cô ấy trông trẻ hơn.", "hint": "나이/젊어 보이다", "answer": "나이에 비해 젊어 보여요."}]}, {"num": 26, "term": "-는 것이 (더) 좋다", "meaning": "Tốt hơn nên...", "blocks": [["p", "Thể hiện ý nghĩa làm theo nội dung phía sau thì tốt hơn khi so sánh nội dung phía trước và nội dung phía sau."], ["ex", "결혼을 하기보다는 <b>유학을 가는 것이 더 좋을 것 같아</b>.", "So với việc kết hôn thì có vẻ đi du học sẽ tốt hơn đấy."]], "practice": [{"vn": "Tốt hơn là nên nghỉ ngơi.", "hint": "쉬다", "answer": "쉬는 것이 좋겠어요."}, {"vn": "Tốt hơn là nên nói thật.", "hint": "사실대로/말하다", "answer": "사실대로 말하는 것이 좋겠어요."}, {"vn": "Tốt hơn là nên đi sớm.", "hint": "일찍/가다", "answer": "일찍 가는 것이 더 좋겠어요."}]}, {"num": 27, "term": "-기 일쑤이다", "meaning": "Thường hay (làm gì đó không tốt, theo thói quen)", "blocks": [["p", "Thể hiện ý nghĩa 'thường xuyên theo thói quen làm sai việc gì đó hoặc trở nên không như mong muốn'."], ["ex", "요즘은 금방 생각했던 것도 <b>잊어버리기 일쑤입니다</b>.", "Dạo này ngay cả điều vừa mới nghĩ xong tớ cũng thường xuyên quên mất tiêu."], ["ex", "안경을 안 쓰면 숫자를 잘못 <b>보기가 일쑤다</b>.", "Nếu không đeo kính thì thường xuyên nhìn lầm chữ số."]], "practice": [{"vn": "Anh ấy thường hay đi trễ.", "hint": "그/지각하다", "answer": "그는 지각하기 일쑤예요."}, {"vn": "Tôi thường hay quên chìa khóa.", "hint": "열쇠/잊어버리다", "answer": "열쇠를 잊어버리기 일쑤예요."}, {"vn": "Cô ấy thường hay bỏ bữa sáng.", "hint": "아침/거르다", "answer": "아침을 거르기 일쑤예요."}]}, {"num": 28, "term": "-아/어/여 대다", "meaning": "Cứ liên tục (làm gì) (lặp đi lặp lại, mang tính phàn nàn)", "blocks": [["p", "Thể hiện ý nghĩa lặp đi lặp lại hành động liên tục đến mức thái quá/quá độ."], ["ex", "왜 그렇게 <b>떠들어 대니</b>?", "Sao lại cứ làm ầm ĩ lên liên tục thế hả?"], ["ex", "그 사람은 괜히 <b>웃어 댑니다</b>.", "Người đó cứ cười vô cớ liên tục."], ["ex", "며칠 동안 책을 <b>읽어 댔더니</b> 눈이 아파요.", "Mấy ngày liền cứ đọc sách liên tục nên giờ mắt tớ bị đau rồi."]], "practice": [{"vn": "Đứa trẻ cứ khóc mãi không thôi.", "hint": "아이/울다", "answer": "아이가 울어 대요."}, {"vn": "Anh ấy cứ nói mãi không dứt.", "hint": "그/말하다", "answer": "그는 말해 대요."}, {"vn": "Họ cứ ồn ào suốt.", "hint": "그들/떠들다", "answer": "그들은 떠들어 댔어요."}]}, {"num": 29, "term": "-곤 하다", "meaning": "Thường hay (làm gì) (thói quen trong quá khứ)", "blocks": [["p", "[Gắn vào động từ] Là biểu hiện thể hiện sự lặp đi lặp lại của một tình huống nào đó. Là dạng rút gọn của '-고는 하다'."], ["ex", "승화는 가끔 그곳에 <b>가곤 했어요</b>.", "Seung-hwa thỉnh thoảng vẫn thường hay đến nơi đó."], ["ex", "정은이는 예전에 자주 놀러 <b>오곤 했다</b>.", "Jung-eun ngày trước thường hay ghé sang chơi."]], "practice": [{"vn": "Ngày xưa tôi thường hay đến đây chơi.", "hint": "예전/여기/놀다/오다", "answer": "예전에 여기 놀러 오곤 했어요."}, {"vn": "Bà thường hay kể chuyện cổ tích cho tôi nghe.", "hint": "할머니/옛날이야기/해 주다", "answer": "할머니는 옛날이야기를 해 주곤 하셨어요."}, {"vn": "Chúng tôi thường hay cùng nhau ăn trưa.", "hint": "같이/점심/먹다", "answer": "같이 점심을 먹곤 했어요."}]}, {"num": 30, "term": "-아/어/여 두다/놓다", "meaning": "Làm sẵn, để sẵn (chuẩn bị trước cho việc sau)", "blocks": [["p", "Thể hiện trạng thái sau khi hành động kết thúc vẫn được bảo tồn, giữ nguyên như thế trong thời gian dài."], ["ex", "지금 피곤하니까 그냥 <b>내버려 두세요</b>.", "Bây giờ tớ đang mệt nên cứ để mặc tớ yên nhé."], ["ex", "이름을 <b>써 놓고</b> 들어 가세요.", "Hãy viết sẵn tên lại rồi hẵng đi vào nhé."], ["ex", "손수건은 서랍에다가 <b>넣어 놓았어요</b>.", "Tôi đã để sẵn khăn tay vào trong ngăn kéo rồi."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-아/어/여 두다' và '-아/어/여 놓다'</b>", "<b>'-아/어/여 두다'</b> thể hiện thời gian duy trì/bảo tồn trạng thái kéo", "dài lâu hơn so với <b>'-아/어/여 놓다'</b>."]]], "practice": [{"vn": "Tôi đã nấu sẵn cơm.", "hint": "밥/짓다", "answer": "밥을 지어 놓았어요."}, {"vn": "Tôi đã đặt sẵn vé trước.", "hint": "표/예매하다", "answer": "표를 예매해 두었어요."}, {"vn": "Tôi đã dọn dẹp sẵn phòng.", "hint": "방/청소하다", "answer": "방을 청소해 두었어요."}]}, {"num": 31, "term": "-(으)ㄴ/는/(으)ㄹ 바에(는) (차라리)", "meaning": "Thà là... còn hơn (so sánh, chọn phương án ít tệ hơn)", "blocks": [["p", "Là lời nói thể hiện thà làm hành vi phía sau còn tốt hơn là làm hành vi phía trước. Do đó nó mang lại cảm giác kiên quyết khi lựa chọn 1 trong 2. Có thể dùng thêm phó từ '차라리' (thà rằng) để nhấn mạnh việc hành vi phía sau tốt hơn, hoặc dùng '아예' để thể hiện việc chọn hành vi phía sau ngay từ đầu."], ["ex", "하루 종일 누워만 <b>있을 바에는 차라리</b> 밖으로 나가요.", "Thà rằng đi ra ngoài còn hơn là cứ nằm lì cả ngày."], ["ex", "심술을 부리면서 심부름을 <b>할 바에야</b> 안 하는 것이 낫다.", "Thà không làm còn hơn là vừa cằn nhằn vừa đi làm sai vặt."], ["ex", "수박 겉핥기식으로 관람을 <b>할 바에는 차라리</b> 다음 기회로 미룹시다.", "Thà lùi sang cơ hội lần sau còn hơn là đi tham quan kiểu cưỡi ngựa xem hoa."]], "practice": [{"vn": "Thà nghỉ việc còn hơn là làm việc như thế này.", "hint": "이렇게/일하다/그만두다", "answer": "이렇게 일할 바에는 차라리 그만두겠어요."}, {"vn": "Thà ở nhà còn hơn là đi trong thời tiết này.", "hint": "이런 날씨/가다/집/있다", "answer": "이런 날씨에 갈 바에는 차라리 집에 있겠어요."}, {"vn": "Thà không làm còn hơn là làm dở dang.", "hint": "대충/하다/안 하다", "answer": "대충 할 바에는 차라리 안 하겠어요."}]}, {"num": 32, "term": "-ㄴ/는댔자", "meaning": "Dù có... đi chăng nữa thì cũng (chỉ trích, coi nhẹ giả định)", "blocks": [["p", "Thể hiện dù có công nhận thực tế hiện tại đi chăng nữa thì sự thật đã được công nhận đó cũng không đạt tới kỳ vọng hoặc coi thường đến mức không đáng kể."], ["ex", "우리가 <b>먹는댔자</b> 얼마나 먹는다고 화를 내세요?", "Chúng tôi ăn thì ăn được bao nhiêu cơ chứ mà anh lại nổi giận?"], ["ex", "이제 <b>말했댔자</b> 무슨 소용이 있어요?", "Bây giờ có nói ra đi chăng nữa thì còn có tác dụng gì cơ chứ?"]], "practice": [{"vn": "Dù anh ấy có xin lỗi thì cũng chẳng ích gì.", "hint": "그/사과하다/소용없다", "answer": "그가 사과한댔자 소용없어요."}, {"vn": "Dù cậu có nói thì cũng chẳng ai nghe.", "hint": "네/말하다/듣다", "answer": "네가 말한댔자 아무도 안 들을 거야."}, {"vn": "Dù có cố gắng thì cũng chẳng thay đổi được gì.", "hint": "노력하다/달라지다", "answer": "노력한댔자 달라질 게 없어요."}]}, {"num": 33, "term": "-기가 무섭게", "meaning": "Ngay khi vừa mới... (một cách nhanh chóng)", "blocks": [["p", "[Gắn vào động từ] Là biểu hiện cường điệu hóa việc ngay khi một việc vừa kết thúc thì việc tiếp theo xảy ra ngay lập tức. Được kết hợp giữa vĩ tố '-기', trợ từ '가' và dạng chia phó từ '무섭게' của tính từ '무섭다'."], ["ex", "집에 <b>들어오기가 무섭게</b> 밥부터 먹었다.", "Vừa mới về đến nhà cái là nó ăn cơm ngay lập tức."], ["ex", "말이 <b>끝나기 무섭게</b> 자기 방으로 들어가 버렸다.", "Lời vừa mới dứt cái là nó đi chui tọt vào phòng ngay."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-기가 무섭게' và '-기가 바쁘게'</b>", "<b>1.</b> Phía trước hoặc phía sau của <b>'-기가 무섭게'</b> không thể đi", "với tính từ. Nếu gắn '-아/어/여지다' vào tính từ để biến thành động từ", "thì có thể dùng được."]], ["ex", "날씨가 어둡기가 무섭게 추웠다. (X)", ""], ["ex", "<b>날씨가 어두워지기 무섭게</b> 추워졌다. (O)", ""], ["ex", "기분이 좋기가 무섭게 우울했다. (X)", ""], ["ex", "<b>기분이 좋아지기가 무섭게</b> 우울해졌다. (O)", ""], ["bq", ["<b>2.</b> <b>'-기가 바쁘게'</b> cũng được sử dụng với ý nghĩa tương tự như", "<b>'-기가 무섭게'</b>."]], ["ex", "점심 식사가 <b>끝나기가 바쁘게</b> 다시 회의가 시작되었다. *(Bữa ăn", "trưa vừa kết thúc cái là cuộc họp lại bắt đầu ngay."], ["ex", "너무 피곤해서 집에 <b>오기가 바쁘게</b> 침대에 누웠다. *(Vì quá mệt mỏi", "nên vừa về đến nhà cái là tớ nằm ngay lên giường."]], "practice": [{"vn": "Vừa mới ra khỏi cửa là trời đổ mưa ngay.", "hint": "문/나가다/비/오다", "answer": "문을 나서기가 무섭게 비가 왔어요."}, {"vn": "Vừa mới đặt món là đã được mang ra ngay.", "hint": "주문하다/나오다", "answer": "주문하기가 무섭게 나왔어요."}, {"vn": "Vừa mới nói xong là anh ấy đã làm ngay.", "hint": "말하다/하다", "answer": "말하기가 무섭게 했어요."}]}, {"num": 34, "term": "-기에 앞서(서)", "meaning": "Trước khi (làm gì)", "blocks": [["p", "<b>1. Thể hiện việc thực hiện hành vi ở mệnh đề sau trước khi thực hiện hành vi ở mệnh đề trước.</b>"], ["ex", "회의를 <b>시작하기에 앞서</b> 여러분께 감사의 말씀을 드립니다.", "Trước khi bắt đầu cuộc họp, tôi xin gửi lời cảm ơn đến quý vị."], ["ex", "대학원에 <b>진학하기에 앞서</b> 필요한 지식을 쌓아라.", "Trước khi học lên cao học, hãy tích lũy những kiến thức cần thiết."], ["p", "<b>2. Mang ý nghĩa tương tự như '-기 전에', nhưng '-기 전에' hay dùng trong hội thoại hàng ngày, còn '-기에 앞서(서)' chủ yếu dùng trong các tình huống trang trọng như họp hành, diễn thuyết, báo cáo.</b>"], ["ex", "잠을 <b>자기 전에</b> 음식을 먹는 것은 좋지 않다고 한다. (O)", "Người ta bảo ăn uống trước khi đi ngủ là không tốt."], ["ex", "잠을 자기에 앞서 음식을 먹는 것은 좋지 않다고 한다. (X)", ""]], "practice": [{"vn": "Trước khi bắt đầu, tôi xin giới thiệu bản thân.", "hint": "시작하다/소개하다", "answer": "시작하기에 앞서 제 소개를 하겠습니다."}, {"vn": "Trước khi ra ngoài, hãy kiểm tra thời tiết.", "hint": "나가다/날씨/확인하다", "answer": "나가기에 앞서 날씨를 확인하세요."}, {"vn": "Trước khi quyết định, hãy suy nghĩ kỹ.", "hint": "결정하다/생각하다", "answer": "결정하기에 앞서 잘 생각해 보세요."}]}, {"num": 35, "term": "-(으)ㄴ/는데도 불구하고", "meaning": "Mặc dù... (nhưng vẫn)", "blocks": [["p", "Mệnh đề sau xảy ra hoàn toàn không liên quan đến sự thật ở mệnh đề trước. Là biểu hiện nhấn mạnh của '-(으)ㄴ/는데도'."], ["ex", "항상 열심히 <b>공부하는데도 불구하고</b> 시험을 못 봐요.", "Dù lúc nào cũng học hành chăm chỉ nhưng tôi vẫn thi kém."], ["ex", "좋아하는 사람이 <b>있었는데도 불구하고</b> 헤어졌어요.", "Mặc dù đã từng có người mình thích nhưng chúng tôi vẫn chia tay."], ["ex", "시간이 <b>많았는데도 불구하고</b> 아무것도 못 했어요.", "Mặc dù đã có nhiều thời gian nhưng tôi vẫn chẳng làm được gì cả."], ["bq", ["**Tìm hiểu thêm | So sánh '-(으)ㄴ/는데도 불구하고',", "'-(으)ㄴ/는데도', '-(으)ㄴ/는데'**", "Đều có ý nghĩa 'tương phản/đối lập', nhưng có sự khác biệt về mức độ", "nhấn mạnh:", "<b>-(으)ㄴ/는데</b> $<$ <b>-(으)ㄴ/는데도</b> $<$ **-(으)ㄴ/는데도", "불구하고**"]]], "practice": [{"vn": "Mặc dù đã cố gắng nhiều nhưng vẫn thất bại.", "hint": "노력하다/실패하다", "answer": "노력했는데도 불구하고 실패했어요."}, {"vn": "Mặc dù trời mưa nhưng chúng tôi vẫn đi.", "hint": "비/오다/가다", "answer": "비가 오는데도 불구하고 갔어요."}, {"vn": "Mặc dù bận nhưng anh ấy vẫn giúp tôi.", "hint": "바쁘다/돕다", "answer": "바쁜데도 불구하고 도와줬어요."}]}, {"num": 36, "term": "-는 한이 있어도/있더라도", "meaning": "Dù có phải... đi chăng nữa (quyết tâm, chấp nhận cái giá phải trả)", "blocks": [["p", "Thể hiện một tình huống cực đoan ở mệnh đề trước mà bản thân phải chấp nhận chịu đựng hoặc hy sinh để thực hiện hành vi ở mệnh đề sau."], ["ex", "굶어 <b>죽는 한이 있어도</b> 그에게 손을 벌리지 않겠다.", "Dù có chết đói đi chăng nữa tớ cũng nhất quyết không ngửa tay xin hắn đâu."], ["ex", "아르바이트를 <b>하는 한이 있어도</b> 공부를 계속하겠다.", "Dù có phải làm thêm đi chăng nữa tớ vẫn sẽ tiếp tục việc học."]], "practice": [{"vn": "Dù có phải thức trắng đêm cũng phải hoàn thành.", "hint": "밤새다/끝내다", "answer": "밤을 새우는 한이 있어도 끝낼 거예요."}, {"vn": "Dù có phải chịu khó khăn cũng phải thực hiện.", "hint": "고생하다/이루다", "answer": "고생하는 한이 있어도 이룰 거예요."}, {"vn": "Dù có phải hy sinh cũng phải bảo vệ gia đình.", "hint": "희생하다/가족/지키다", "answer": "희생하는 한이 있어도 가족을 지킬 거예요."}]}, {"num": 37, "term": "-ㄴ/는답손/(이)라손 치더라도", "meaning": "Cho dù có nói là... đi nữa thì (nhượng bộ mạnh, văn viết/cổ điển)", "blocks": [["p", "Thể hiện việc nội dung mệnh đề trước và nội dung mệnh đề sau không liên quan đến nhau. Có ý nghĩa tương tự như '아무리 -ㄴ/는다고 하더라도', '아무리 -ㄴ/는다고 치더라도'."], ["ex", "아무리 버릇이 <b>없답손 치더라도</b> 어른에게 반말을 할 수 있어요?", "Dù cho có vô lễ đi chăng nữa thì làm sao có thể nói trống không với người lớn được cơ chứ?"], ["ex", "아무리 <b>친구라손 치더라도</b> 이번만은 절대 들어 줄 수 없어요.", "Dù cho có là bạn bè đi chăng nữa thì riêng lần này tớ tuyệt đối không thể giúp được."]], "practice": [{"vn": "Cho dù có nói là bận đi nữa thì cũng nên đến.", "hint": "바쁘다/오다", "answer": "바쁘다손 치더라도 와야지요."}, {"vn": "Cho dù có nói là đúng đi nữa thì vẫn cần xem xét lại.", "hint": "맞다/다시/생각하다", "answer": "맞다손 치더라도 다시 생각해 봐야 해요."}, {"vn": "Cho dù có nói là khó đi nữa thì cũng phải thử.", "hint": "어렵다/시도하다", "answer": "어렵다손 치더라도 시도해야지요."}]}, {"num": 38, "term": "-기 십상이다", "meaning": "Rất dễ (xảy ra điều gì đó không tốt)", "blocks": [["p", "Chỉ kết hợp với một số động từ hành động mang ý nghĩa tiêu cực, là lời nói suy đoán rằng 'trong 10 phần thì có đến 8, 9 phần chắc chắn sẽ trở nên như thế, chắc chắn không ngoại lệ'."], ["ex", "말을 잘못했다가는 <b>망신당하기 십상입니다</b>.", "Nói năng không cẩn thận là rất dễ bị mất mặt/bẽ mặt đấy."], ["ex", "여기서 자다가는 <b>얼어 죽기 십상이다</b>.", "Ngủ ở đây thì rất dễ bị chết rét đấy."]], "practice": [{"vn": "Nếu bất cẩn thì rất dễ bị tai nạn.", "hint": "부주의하다/사고/나다", "answer": "부주의하면 사고가 나기 십상이에요."}, {"vn": "Nếu ăn nhiều đồ ngọt thì rất dễ bị sâu răng.", "hint": "단 것/많이 먹다/충치/생기다", "answer": "단 것을 많이 먹으면 충치가 생기기 십상이에요."}, {"vn": "Nếu không cẩn thận thì rất dễ mắc lỗi.", "hint": "조심하지 않다/실수하다", "answer": "조심하지 않으면 실수하기 십상이에요."}]}, {"num": 39, "term": "-기만 하다", "meaning": "Chỉ (làm mỗi việc đó) mà thôi", "blocks": [["p", "Là biểu hiện thể hiện chỉ thực hiện duy nhất một hành vi hoặc một trạng thái nào đó tiếp diễn."], ["p", "<b>1. [Gắn vào động từ] Thể hiện không làm hành động nào khác mà chỉ thực hiện duy nhất một hành động.</b>"], ["ex", "누리가 먹지는 않고 <b>울기만 해요</b>.", "Nuri không ăn uống gì mà chỉ toàn khóc thôi."], ["ex", "승화는 <b>놀기만 하고</b> 공부는 하지 않는다.", "Seung-hwa chỉ toàn chơi chứ không chịu học."], ["ex", "그때 저는 아무 말도 할 수 없어서 <b>웃기만 했어요</b>.", "Lúc đó tớ không thể nói được câu gì nên chỉ biết cười thôi."], ["p", "<b>2. [Gắn vào tính từ] Thể hiện một trạng thái nào đó tiếp diễn mà không bị ảnh hưởng bởi lời nói hay tình huống khác, hoặc không liên quan đến điều đó.</b>"], ["ex", "그냥 무섭고 <b>떨리기만 했어요</b>.", "Tớ chỉ thấy sợ hãi và run rẩy thôi."], ["ex", "사람이 없으니까 집이 <b>적막하기만 합니다</b>.", "Không có người nên nhà cửa chỉ thấy vắng lặng tịch mịch thôi."]], "practice": [{"vn": "Anh ấy chỉ ngồi im mà thôi.", "hint": "그/가만히/앉다", "answer": "그는 가만히 앉아만 있어요."}, {"vn": "Tôi chỉ nghe mà thôi, không nói gì cả.", "hint": "듣다", "answer": "듣기만 했어요."}, {"vn": "Đứa trẻ chỉ khóc mà thôi.", "hint": "아이/울다", "answer": "아이는 울기만 해요."}]}, {"num": 40, "term": "-(으)ㄴ 나머지", "meaning": "Vì quá... (đến mức) nên (kết quả do mức độ quá cao gây ra)", "blocks": [["p", "Thể hiện kết quả của việc thực hiện hành vi mà từ đứng trước biểu thị hoặc trở thành trạng thái như vậy, rồi tiếp nối nói về nội dung ở mệnh đề sau. Mang ý nghĩa tương tự như '너무 -아/어서', '-(으)ㄹ 수밖에 없다'."], ["ex", "심덕은 밤을 <b>새운 나머지</b> 다음 날 지각하고 말았다.", "Sim-deok do thức trắng đêm nên kết quả là ngày hôm sau đã bị trễ giờ."], ["ex", "시험을 앞두고 너무 <b>초조한 나머지</b> 배탈이 나고야 말았다.", "Trước kỳ thi do quá hồi hộp chần chừ nên kết quả là bị đau bụng mất tiêu."]], "practice": [{"vn": "Vì quá vui mừng nên cô ấy đã bật khóc.", "hint": "너무/기쁘다/울다", "answer": "너무 기쁜 나머지 울고 말았어요."}, {"vn": "Vì quá lo lắng nên tôi không ngủ được.", "hint": "너무/걱정하다/못 자다", "answer": "너무 걱정한 나머지 잠을 못 잤어요."}, {"vn": "Vì quá mệt nên anh ấy đã ngủ quên.", "hint": "너무/피곤하다/잠들다", "answer": "너무 피곤한 나머지 잠들어 버렸다."}]}, {"num": 41, "term": "-(으)ㄹ까 싶다/하다/보다", "meaning": "Có lẽ là... (dự đoán không chắc chắn lắm)", "blocks": [["p", "Thể hiện người nói có ý định thử thực hiện hành vi đó mang tính thử nghiệm."], ["ex", "머리가 아프니 일찍 <b>누울까 싶다</b>.", "Vì đau đầu nên tớ định nằm nghỉ sớm xem sao."], ["ex", "오늘은 말을 <b>할까 하다</b>.", "Hôm nay tớ định sẽ nói ra xem sao."], ["ex", "거실에다 이 그림을 <b>걸까 봐요</b>.", "Tớ định treo bức tranh này ở phòng khách xem sao."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄹ까 하다' và '-(으)ㄹ까 보다'</b>", "Nhìn chung <b>'-(으)ㄹ까 하다'</b> và <b>'-(으)ㄹ까 보다'</b> có thể thay", "thế cho nhau. Tuy nhiên, khi mệnh đề trước thể hiện sự lo lắng/lo sợ", "tình huống nào đó xảy ra thì chủ yếu dùng <b>'-(으)ㄹ까 보다'</b>."]], ["ex", "오랜만에 고향에 좀 <b>다녀올까 봐</b>. *(Lâu lắm rồi tớ định về thăm", "quê xem sao)."], ["ex", "아이는 소풍 가는 날에 비가 <b>올까 봐</b> 벌써부터 걱정을 한다. *(Đứa", "trẻ e rằng ngày đi dã ngoại trời sẽ mưa nên đã lo lắng từ bây giờ)."]], "practice": [{"vn": "Có lẽ anh ấy sẽ đến.", "hint": "그/오다", "answer": "그가 올까 싶어요."}, {"vn": "Có lẽ trời sẽ mưa.", "hint": "비/오다", "answer": "비가 올까 싶어요."}, {"vn": "Có lẽ tôi nên đi khám bác sĩ.", "hint": "병원/가다", "answer": "병원에 가 볼까 싶어요."}]}, {"num": 42, "term": "-(으)려고 들다", "meaning": "Cố tình muốn... (một cách gượng ép, không tự nhiên)", "blocks": [["p", "Gắn vào động từ hành động, thể hiện việc mang ý định thực hiện hành vi đó và tích cực xúc tiến đẩy mạnh. Đây là biểu hiện mang lại cảm giác gay gắt/mạnh mẽ hơn so với '-(으)려고 하다'."], ["ex", "이야기를 자꾸 <b>숨기려고 드니까</b> 더 궁금해요.", "Càng cố tình giấu câu chuyện thì tớ lại càng tò mò hơn."], ["ex", "용희가 무엇이든 <b>알리려고 들다</b>.", "Yong-hee cái gì cũng cố bới móc để cho biết."], ["ex", "개가 화가 나서 주인을 <b>물려고 들다</b>.", "Con chó nổi giận xông vào định cắp/cắn chủ."], ["p", "<b>1. Trong các từ trên, từ có thể lược bỏ '-고' để dùng dưới dạng '-(으)려 들다' bao gồm '숨기려 들다', '알리려 들다'. Còn từ chỉ có thể dùng dạng '-(으)려고 들다' là '물려고 들다'.</b>"], ["p", "<b>2. Có trường hợp '-(으)려 들다' gắn vào động từ hành động để củng cố thành một động từ phức hợp.</b>"], ["ex", "사람들이 범인에게 <b>달려들어</b> 도망가는 범인을 잡았다.", "Mọi người xông vào tên tội phạm và bắt giữ tên tội phạm đang bỏ chạy."], ["ex", "나는 친구들의 계획에 <b>말려들어</b> 예정에 없던 여행을 다녀왔다.", "Tôi bị cuốn vào kế hoạch của lũ bạn nên đã đi một chuyến du lịch không có trong kế hoạch."]], "practice": [{"vn": "Anh ấy cố tình muốn gây sự.", "hint": "그/싸우다", "answer": "그는 싸우려고 든다."}, {"vn": "Cô ấy cố tình muốn hiểu theo cách khác.", "hint": "그녀/다르게/이해하다", "answer": "그녀는 다르게 이해하려고 든다."}, {"vn": "Đứa trẻ cố tình muốn làm theo ý mình.", "hint": "아이/자기 마음대로/하다", "answer": "아이는 자기 마음대로 하려고 든다."}]}, {"num": 43, "term": "-(으)ㄹ 양으로", "meaning": "Với ý định là..., với mục đích là (văn viết)", "blocks": [["p", "Gắn vào thân động từ hành động, thể hiện người nói mang ý đồ hoặc ý định giống như nội dung ở mệnh đề trước để thực hiện hành vi ở mệnh đề sau. Thường dùng đi kèm với trợ từ '-(으)로'."], ["ex", "불우한 이웃을 <b>도울 양으로</b> 이야기를 하더군요.", "Thấy bảo là định giúp đỡ những hàng xóm khó khăn đấy."], ["ex", "집을 한 채 <b>지을 양으로</b> 설계 중입니다.", "Tôi đang thiết kế với ý định xây một căn nhà."]], "practice": [{"vn": "Với ý định gây bất ngờ, tôi đã chuẩn bị món quà.", "hint": "놀라게 하다/선물/준비하다", "answer": "놀라게 할 양으로 선물을 준비했어요."}, {"vn": "Với ý định giúp đỡ, tôi đã đến sớm.", "hint": "돕다/일찍/오다", "answer": "도울 양으로 일찍 왔어요."}, {"vn": "Với ý định học tập, tôi đã sang Hàn Quốc.", "hint": "공부하다/한국/가다", "answer": "공부할 양으로 한국에 갔어요."}]}, {"num": 44, "term": "-(으)로 인해/인해서/인하여/인한", "meaning": "Do, vì (nguyên nhân, thường trang trọng/văn viết)", "blocks": [["p", "Thể hiện danh từ đứng trước trở thành nguyên nhân dẫn đến kết quả ở mệnh đề sau. Thường được dùng nhiều trong các văn bản chính thức hoặc văn viết."], ["ex", "말 <b>한마디로 인해서</b> 싸움이 시작된 것이다.", "Cuộc ẩu đả đã bắt đầu chỉ vì một lời nói."], ["ex", "부동산 투기 <b>사건으로 인해서</b> 세상은 발칵 뒤집혔습니다.", "Thế giới đã bị đảo lộn bàng hoàng do vụ án đầu cơ bất động sản."]], "practice": [{"vn": "Do bão nên nhiều nhà bị hư hại.", "hint": "태풍/집/피해를 입다", "answer": "태풍으로 인해 많은 집이 피해를 입었다."}, {"vn": "Do tai nạn giao thông nên đường bị tắc.", "hint": "교통사고/길/막히다", "answer": "교통사고로 인해 길이 막혔어요."}, {"vn": "Do sự cố đó mà công việc bị chậm trễ.", "hint": "그 사고/일/늦어지다", "answer": "그 사고로 인해 일이 늦어졌어요."}]}, {"num": 45, "term": "-(으)로 말미암아", "meaning": "Bởi vì, do (nguyên nhân, văn viết trang trọng)", "blocks": [["p", "Thể hiện danh từ đứng trước trở thành nguyên nhân dẫn đến kết quả ở mệnh đề sau."], ["ex", "남편의 뜻하지 않은 <b>승진으로 말미암아</b> 과장 부인이 되었다.", "Nhờ việc thăng chức ngoài dự kiến của chồng mà cô ấy đã trở thành phu nhân trưởng phòng."], ["ex", "<b>환경 오염으로 말미암아</b> 생태계는 큰 변화를 맞게 되었다.", "Do ô nhiễm môi trường mà hệ sinh thái đã phải đối mặt với sự biến đổi lớn."], ["bq", ["**Tìm hiểu thêm | So sánh '-(으)로 말미암아', '-는 바람에', '-(으)로", "인해서'**", "<b>1. -(으)로 말미암아:</b> Mang lại cảm giác được hệ thống hóa và chỉnh", "chu với nghĩa 'bởi ảnh hưởng nào đó từ mệnh đề trước'. Do đó dùng", "nhiều trong văn viết hoặc tình huống chính thức. <b>2. -는 바람에:</b>", "[Gắn vào động từ] Mang ý nghĩa 'do ảnh hưởng của mệnh đề trước'.", "<b>3. -(으)로 인해서:</b> Mang lại cảm giác nguyên nhân có liên quan trực", "tiếp đến mệnh đề trước."]]], "practice": [{"vn": "Do sự bất cẩn của anh ấy mà xảy ra tai nạn.", "hint": "그/부주의/사고/나다", "answer": "그의 부주의로 말미암아 사고가 났다."}, {"vn": "Do chiến tranh mà nhiều người đã mất nhà cửa.", "hint": "전쟁/많은 사람/집/잃다", "answer": "전쟁으로 말미암아 많은 사람이 집을 잃었다."}, {"vn": "Do sự hiểu lầm đó mà hai người đã cãi nhau.", "hint": "그 오해/두 사람/싸우다", "answer": "그 오해로 말미암아 두 사람이 싸웠다."}]}, {"num": 46, "term": "을/를 막론하고", "meaning": "Bất kể, không phân biệt", "blocks": [["p", "Thể hiện việc không tính toán hay phân biệt nội dung phía trước. Có ý nghĩa tương tự như '을/를 불문하고'."], ["ex", "환경 오염은 <b>동서양을 막론하고</b> 해결해야 할 문제야.", "Ô nhiễm môi trường là vấn đề phải giải quyết bất kể là Đông hay Tây."], ["ex", "k-pop이라면 <b>장르를 막론하고</b> 즐겨 들을 정도로 좋아해요.", "Nếu là K-pop thì tớ thích đến mức nghe giải trí bất kể thể loại nào."]], "practice": [{"vn": "Bất kể tuổi tác, ai cũng có thể tham gia.", "hint": "나이/참여하다", "answer": "나이를 막론하고 참여할 수 있어요."}, {"vn": "Bất kể nam nữ, mọi người đều bình đẳng.", "hint": "남녀/평등하다", "answer": "남녀를 막론하고 평등해요."}, {"vn": "Bất kể lý do gì, việc đó là sai.", "hint": "이유/그 일/잘못이다", "answer": "이유를 막론하고 그 일은 잘못이에요."}]}, {"num": 47, "term": "-은/는 통에", "meaning": "Do sự việc/tình huống (gây ra), trong lúc hỗn loạn của", "blocks": [["p", "<b>1. Dùng khi thể hiện nguyên nhân hoặc tình huống dẫn đến một kết quả tiêu cực nào đó.</b>"], ["ex", "옆에서 <b>떠드는 통에</b> 중요한 이야기를 못 들었다.", "Do bên cạnh cứ làm ồn nên tớ không nghe được câu chuyện quan trọng."], ["ex", "아이가 <b>밤새 우는 통에</b> 한잠도 자지 못했어요.", "Do đứa trẻ khóc suốt đêm nên tớ chẳng chợp mắt được tẹo nào."], ["p", "<b>2. '-은/는 통에' chủ yếu là biểu hiện dùng chung với nguyên nhân gây ra kết quả tiêu cực. Do đó nếu dùng chung với nguyên nhân gây ra kết quả tích cực sẽ thành câu gượng gạo, lúc này phải dùng dạng '-(으)ㄴ/는 덕분에'.</b>"], ["p", "<b>3. Khi nói về tình huống quá khứ, dùng dạng '-은/는 통에' cho động từ.</b>"], ["p", "<b>4. Biểu hiện tương tự với '-은/는 통에' có thể dùng '-(으)ㄴ/는 바람에', '-(으)ㄴ/는 탓에/으로'.</b>"]], "practice": [{"vn": "Trong lúc cãi nhau, cốc đã bị vỡ.", "hint": "싸우다/컵/깨지다", "answer": "싸우는 통에 컵이 깨졌어요."}, {"vn": "Trong lúc mọi người ồn ào, tôi không nghe rõ.", "hint": "떠들다/못 듣다", "answer": "떠드는 통에 못 들었어요."}, {"vn": "Do sự cố đó mà tôi phải đi làm trễ.", "hint": "그 일/늦게/출근하다", "answer": "그 일이 있는 통에 늦게 출근했어요."}]}, {"num": 48, "term": "-(으)ㄹ락 말락 하다", "meaning": "Gần như (nhưng chưa hẳn), suýt soát", "blocks": [["p", "Thể hiện hành động của động từ nằm ở ranh giới giữa việc suýt thực hiện được rồi lại không thực hiện được. Thể hiện trạng thái của hành động."], ["ex", "안개 때문에 앞차가 <b>보일락 말락 한다</b>.", "Do sương mù nên xe phía trước cứ mờ mờ suýt thấy lại suýt không thấy."], ["ex", "옷이 약간 <b>젖을락 말락 할</b> 정도로 비를 맞았다.", "Tớ bị mắc mưa ở mức độ quần áo hơi suýt ướt suýt không."]], "practice": [{"vn": "Cánh cửa gần như mở nhưng lại không mở hẳn.", "hint": "문/열리다", "answer": "문이 열릴락 말락 해요."}, {"vn": "Bông hoa gần như nở nhưng chưa nở hẳn.", "hint": "꽃/피다", "answer": "꽃이 필락 말락 해요."}, {"vn": "Mắt tôi gần như nhắm lại vì buồn ngủ.", "hint": "눈/감기다", "answer": "눈이 감길락 말락 해요."}]}, {"num": 49, "term": "-기 짝이 없다", "meaning": "Vô cùng, cực kỳ (nhấn mạnh mức độ, thường tiêu cực)", "blocks": [["p", "[Gắn vào tính từ] Là biểu hiện nhấn mạnh sự vô cùng, hết sức, không gì so sánh bằng. Là sự kết hợp giữa vĩ tố '-기', danh từ '짝', trợ từ '이', và tính từ '없다'."], ["ex", "고생하며 사는 딸을 보니 <b>애처롭기 짝이 없다</b>.", "Nhìn con gái sống vất vả mà thấy thương xót không gì bằng."], ["ex", "십 년 만에 친구를 만나니 <b>기쁘기 짝이 없네요</b>.", "Gặp lại bạn sau 10 năm thật là vui mừng vô cùng."], ["ex", "예전의 글을 지금 읽어 보면, <b>유치하기 짝이 없습니다</b>.", "Bây giờ đọc lại những dòng chữ ngày trước thấy ấu trĩ không chịu nổi."]], "practice": [{"vn": "Thái độ của anh ấy vô cùng đáng ghét.", "hint": "그/태도/얄밉다", "answer": "그의 태도가 얄밉기 짝이 없어요."}, {"vn": "Tình huống này vô cùng khó xử.", "hint": "상황/난처하다", "answer": "이 상황이 난처하기 짝이 없어요."}, {"vn": "Kết quả này thật đáng tiếc vô cùng.", "hint": "결과/아쉽다", "answer": "이 결과가 아쉽기 짝이 없어요."}]}, {"num": 50, "term": "-기(가) 이를 데 없다", "meaning": "Đến mức không thể diễn tả được, vô cùng", "blocks": [["p", "<b>1. Thể hiện trạng thái của động từ/tính từ tuyệt vời đến mức không thể nói thêm được nữa.</b>"], ["ex", "정은이는 <b>꼼꼼하기가 이를 데 없는</b> 사람이에요.", "Jung-eun là người tỉ mỉ không còn gì để nói."], ["ex", "연말이라서 교통이 <b>복잡하기가 이를 데 없다</b>.", "Vì là cuối năm nên giao thông tắc nghẽn không còn gì để nói."], ["p", "<b>2. '-기가 이를 데 없다' có thể đổi sang dùng dạng phó từ '이를 데 없이'.</b>"], ["ex", "사랑스럽기가 이를 데 없다 → <b>이를 데 없이</b> 사랑스럽다", "Đáng yêu không còn gì để nói → Đáng yêu vô cùng"]], "practice": [{"vn": "Cảnh đẹp đến mức không thể diễn tả được.", "hint": "경치/아름답다", "answer": "경치가 아름답기 이를 데 없어요."}, {"vn": "Tôi vui đến mức không thể diễn tả được.", "hint": "기쁘다", "answer": "기쁘기 이를 데 없어요."}, {"vn": "Anh ấy tốt bụng đến mức không thể diễn tả được.", "hint": "그/친절하다", "answer": "그는 친절하기 이를 데 없어요."}]}, {"num": 51, "term": "-(으)ㄹ 지경이다", "meaning": "Đến mức độ (nghiêm trọng) là...", "blocks": [["p", "Thể hiện hoàn cảnh/tình trạng đã đạt đến mức độ gần như cực hạn vì lý do mà mệnh đề trước chỉ ra."], ["ex", "답답해서 <b>숨이 막힐 지경이다</b>.", "Ngột ngạt đến mức nghẹt thở."], ["ex", "누리는 많이 먹어서 <b>배가 터질 지경이다</b>.", "Nuri ăn nhiều đến mức bụng sắp nổ tung ra đến nơi."]], "practice": [{"vn": "Tôi mệt đến mức không thể đứng dậy nổi.", "hint": "피곤하다/일어나다", "answer": "일어날 수 없을 지경이에요."}, {"vn": "Anh ấy đau đến mức không thể chịu đựng được.", "hint": "그/아프다/참다", "answer": "참을 수 없을 지경이에요."}, {"vn": "Việc nhiều đến mức không thể xử lý hết.", "hint": "일/많다/처리하다", "answer": "일이 많아서 처리 못 할 지경이에요."}]}, {"num": 52, "term": "-는 가운데", "meaning": "Trong bối cảnh, giữa lúc (điều gì đó đang diễn ra)", "blocks": [["p", "<b>1. Thể hiện bối cảnh hoặc tình huống bao quanh một hành vi hay sự kiện nào đó đang tiếp diễn.</b>"], ["ex", "모든 사람들이 <b>지켜보는 가운데</b> 마침내 결혼식이 시작되었다.", "Trong lúc mọi người đang dõi theo, cuối cùng lễ kết hôn cũng đã bắt đầu."], ["ex", "비가 <b>오는 가운데</b> 경기는 계속되었다.", "Trận đấu vẫn tiếp tục trong lúc trời đang mưa."], ["p", "<b>2. Phía sau '-는 가운데' có thể gắn thêm các trợ từ như '에, 에서, 도, 에서도' để thể hiện ý nghĩa nhấn mạnh.</b>"], ["ex", "많은 사람이 <b>지켜보는 가운데에</b> 졸업식이 시작되었다.", "Buổi lễ tốt nghiệp đã bắt đầu giữa lúc rất nhiều người đang dõi theo."]], "practice": [{"vn": "Trong lúc bận rộn, tôi vẫn cố gắng nghỉ ngơi chút ít.", "hint": "바쁘다/조금/쉬다", "answer": "바쁜 가운데 조금 쉬었어요."}, {"vn": "Giữa lúc khó khăn, mọi người vẫn giúp đỡ lẫn nhau.", "hint": "어렵다/서로/돕다", "answer": "어려운 가운데 서로 도왔어요."}, {"vn": "Trong lúc mưa to, chúng tôi vẫn tiếp tục làm việc.", "hint": "비/많이 오다/일하다", "answer": "비가 많이 오는 가운데 일을 계속했어요."}]}, {"num": 53, "term": "-(으)ㄴ 채(로)", "meaning": "Trong trạng thái... (giữ nguyên trạng thái để làm việc khác)", "blocks": [["p", "Là lời nói thể hiện ý nghĩa 'giữ nguyên trạng thái vốn có không thay đổi'. Thể hiện hành động ở mệnh đề sau được thực hiện trong trạng thái đang làm hành động ở mệnh đề trước."], ["ex", "과자를 손에 <b>쥔 채</b> 잠이 들었다.", "Nó đã ngủ thiếp đi trong khi tay vẫn đang cầm chiếc bánh quy."], ["ex", "문을 열어 <b>놓은 채로</b> 자더니 감기가 들었어요.", "Tôi ngủ trong khi vẫn để mở cửa nên đã bị cảm mất rồi."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄴ 채로' và '-는 대로'</b>", "<b>1. -(으)ㄴ 채로:</b> Thể hiện trạng thái dừng lại hoặc tiếp diễn của", "một hành động nào đó không bị thay đổi."]], ["ex", "고개를 <b>숙인 채로</b> 말대답을 한다.", "→ Nói đáp trả trong trạng thái đang cúi đầu."], ["bq", ["<b>2. -는 대로:</b> Thể hiện ý nghĩa 'giống như hình dáng hành động đang", "diễn ra'."]], ["ex", "내가 고개를 <b>숙이는 대로</b> 너희도 숙여 봐.", "→ Đưa ra lời khuyên bảo hãy làm theo hình dáng tớ đang cúi đầu."]], "practice": [{"vn": "Tôi đã ngủ quên trong khi vẫn mặc quần áo.", "hint": "옷/입다/자다", "answer": "옷을 입은 채로 잤어요."}, {"vn": "Anh ấy đã ra ngoài trong khi cửa vẫn mở.", "hint": "문/열다/나가다", "answer": "문을 연 채로 나갔어요."}, {"vn": "Tôi đã ngồi im trong trạng thái không nói gì.", "hint": "아무 말/하지 않다/앉다", "answer": "아무 말도 하지 않은 채로 앉아 있었어요."}]}, {"num": 54, "term": "-(으)ㄴ/는 마당에", "meaning": "Trong tình huống mà... (đã đến nước này)", "blocks": [["p", "Thể hiện khung cảnh hoặc tình huống mà sự kiện ở mệnh đề sau xảy ra tiếp nối mệnh đề trước, không có sự hạn chế đối với động từ ở mệnh đề trước."], ["ex", "모두들 <b>일하는 마당에</b> 너만 놀아서 되겠니?", "Trong tình cảnh mọi người đều đang làm việc mà chỉ có mình cậu chơi đùa thế có được không?"], ["ex", "내가 나 자신도 <b>못 믿는 마당에</b> 누구를 믿겠어?", "Trong tình cảnh ngay cả bản thân mình tớ còn chẳng tin nổi thì tớ tin được ai cơ chứ?"]], "practice": [{"vn": "Trong tình huống đã như vậy rồi, chúng ta phải quyết định thôi.", "hint": "이렇게 되다/결정하다", "answer": "이렇게 된 마당에 결정해야지요."}, {"vn": "Đã đến nước này rồi thì phải nói thật.", "hint": "이런 상황/사실대로/말하다", "answer": "이런 상황인 마당에 사실대로 말해야지요."}, {"vn": "Đã bị phát hiện rồi thì phải thừa nhận thôi.", "hint": "들키다/인정하다", "answer": "들킨 마당에 인정해야지요."}]}, {"num": 55, "term": "-(으)ㄴ/는/(으)ㄹ 듯하다/듯싶다", "meaning": "Có vẻ như, hình như là", "blocks": [["p", "Gắn vào động từ thể hiện ý nghĩa '-는 것 같다' (có vẻ như). Là từ kết hợp giữa '-듯' (thể hiện sự tương đồng) và '-싶다' (thể hiện tâm trí hướng về đâu đó), thể hiện sự phỏng đoán có sự can thiệp đánh giá chủ quan của người nói."], ["ex", "참새 한 마리가 나뭇가지에 <b>앉을 듯싶었는데</b> 그냥 날아갑니다.", "Một chú chim sẻ tưởng như sắp đậu xuống cành cây nhưng rồi lại cứ thế bay đi."], ["ex", "병이 <b>호전되는 듯싶더니</b> 다시 악화되었어요.", "Bệnh tình tưởng như đã biến chuyển tốt hơn nhưng rồi lại trở nặng."], ["ex", "며칠 전부터 우리가 나타나기를 <b>기다린 듯싶습니다</b>.", "Có vẻ như từ mấy ngày trước họ đã chờ đợi chúng tôi xuất hiện."]], "practice": [{"vn": "Có vẻ như trời sắp mưa.", "hint": "비/오다", "answer": "비가 올 듯해요."}, {"vn": "Hình như anh ấy đã về rồi.", "hint": "그/가다", "answer": "그가 간 듯해요."}, {"vn": "Có vẻ như món này ngon.", "hint": "이 음식/맛있다", "answer": "이 음식이 맛있을 듯해요."}]}, {"num": 56, "term": "-(으)ㄹ 법하다", "meaning": "Có thể xảy ra, hợp lý là...", "blocks": [["p", "Thể hiện sự phỏng đoán mang nghĩa 'có vẻ như thế'. '법' là danh từ thể hiện việc suy ra từ một sự thật nào đó là đương nhiên hoặc đã thành thói quen, chỉ dùng được trong tình huống phù hợp với điều đó."], ["ex", "다음 주에는 답장이 <b>올 법합니다</b>.", "Chắc là tuần tới sẽ có thư trả lời thôi."], ["ex", "책이 여기 어디쯤에 <b>있을 법합니다</b>.", "Sách chắc là nằm đâu đó quanh đây thôi."]], "practice": [{"vn": "Việc anh ấy tức giận cũng là điều dễ hiểu.", "hint": "그/화내다", "answer": "그가 화낼 법도 해요."}, {"vn": "Trời lạnh thế này thì có tuyết rơi cũng hợp lý.", "hint": "날씨/춥다/눈/오다", "answer": "날씨가 추우니까 눈이 올 법해요."}, {"vn": "Với năng lực đó thì đậu cũng là điều dễ hiểu.", "hint": "그 실력/합격하다", "answer": "그 실력이면 합격할 법해요."}]}, {"num": 57, "term": "-(으)ㄹ 성싶다", "meaning": "Có vẻ như (dự đoán mang tính chủ quan, ít dùng)", "blocks": [["p", "Thể hiện sự phỏng đoán, dự đoán giống như '-는 것 같다'. Dù dùng trong văn nói nhiều hơn văn viết nhưng trong thời hiện đại không mấy khi sử dụng. Có thể thay thế bằng '듯싶다'."], ["ex", "내일은 눈이 <b>올 성싶군요</b>.", "Ngày mai chắc là tuyết sẽ rơi đấy nhỉ."], ["ex", "<b>될 성싶은</b> 나무는 떡잎부터 알아본다.", "Cây mà thành tài thì nhìn thấy được từ tận mầm cây / Cây lớn từ mầm."]], "practice": [{"vn": "Có vẻ như trời sẽ mưa.", "hint": "비/오다", "answer": "비가 올 성싶어요."}, {"vn": "Có vẻ như việc này sẽ khó.", "hint": "이 일/어렵다", "answer": "이 일이 어려울 성싶어요."}, {"vn": "Có vẻ như anh ấy sẽ đồng ý.", "hint": "그/동의하다", "answer": "그가 동의할 성싶어요."}]}, {"num": 58, "term": "-(으)ㄴ/는 감이 있다", "meaning": "Có cảm giác là hơi... (nhận xét nhẹ nhàng, mang tính chủ quan)", "blocks": [["p", "'감' là danh từ thể hiện cảm giác, dùng khi người nói có suy nghĩ giống mệnh đề trước nhưng không khẳng định tuyệt đối."], ["ex", "수연이가 일을 너무 <b>서두르는 감이 있다</b>.", "Có cảm giác là Su-yeon đang xử lý công việc hơi quá vội vàng."], ["ex", "색이 약간 <b>진한 감이 있지만</b> 얼굴에 잘 어울린다.", "Tuy có cảm giác màu sắc hơi đậm một chút nhưng lại rất hợp với khuôn mặt."]], "practice": [{"vn": "Bộ phim này có cảm giác hơi dài.", "hint": "영화/길다", "answer": "이 영화는 좀 긴 감이 있어요."}, {"vn": "Giá này có cảm giác hơi đắt.", "hint": "가격/비싸다", "answer": "이 가격은 좀 비싼 감이 있어요."}, {"vn": "Cách nói đó có cảm giác hơi thẳng thắn quá.", "hint": "그 말투/직설적이다", "answer": "그 말투는 좀 직설적인 감이 있어요."}]}, {"num": 59, "term": "-(으)려나 보다", "meaning": "Có lẽ là... (phỏng đoán)", "blocks": [["p", "Là lời nói thể hiện sự phỏng đoán ý đồ của chủ ngữ là gì, chủ ngữ sẽ làm như thế nào dựa trên việc suy đoán từ một sự thật nào đó."], ["ex", "친구들이 오늘은 여기서 자고 <b>가려나 봐요</b>.", "Có vẻ như hôm nay các bạn định ngủ lại đây rồi mới đi."]], "practice": [{"vn": "Có lẽ anh ấy sẽ đến.", "hint": "그/오다", "answer": "그가 오려나 봐요."}, {"vn": "Có lẽ trời sẽ lạnh.", "hint": "날씨/춥다", "answer": "날씨가 추우려나 봐요."}, {"vn": "Có lẽ cô ấy đang bận.", "hint": "그녀/바쁘다", "answer": "그녀가 바쁘려나 봐요."}]}, {"num": 60, "term": "-(으)ㄹ 뻔하다", "meaning": "Suýt nữa thì (đã xảy ra điều gì đó, nhưng may mắn tránh được)", "blocks": [["p", "<b>1. Thể hiện nội dung ở mệnh đề trước dù không xảy ra nhưng đã chạm đến trạng thái ngay trước khi xảy ra.</b>"], ["ex", "급하게 뛰어오다 <b>넘어질 뻔했다</b>.", "Vội vã chạy lại nên tớ suýt chút nữa bị ngã."], ["ex", "지하철을 타지 않았으면 <b>늦을 뻔했어요</b>.", "Nếu không đi tàu điện ngầm thì tớ suýt nữa là bị trễ rồi."], ["p", "<b>2. Cũng có khi dùng dưới dạng '-(아/어)서 죽을 뻔했다' để phóng đại một trạng thái nào đó trong quá khứ.</b>"], ["ex", "네가 없으니 심심해서 <b>죽을 뻔했어</b>.", "Không có cậu tớ chán muốn chết đi được."], ["ex", "말이 통하지 않아서 답답해서 <b>죽을 뻔했다</b>.", "Không bất đồng ngôn ngữ nên tớ ngột ngạt ức chế muốn chết."]], "practice": [{"vn": "Tôi suýt nữa thì bị ngã.", "hint": "넘어지다", "answer": "넘어질 뻔했어요."}, {"vn": "Tôi suýt nữa thì quên mất chìa khóa.", "hint": "열쇠/잊어버리다", "answer": "열쇠를 잊어버릴 뻔했어요."}, {"vn": "Chúng tôi suýt nữa thì bị trễ tàu.", "hint": "기차/놓치다", "answer": "기차를 놓칠 뻔했어요."}]}, {"num": 61, "term": "-(으)ㄹ 게 뻔하다", "meaning": "Chắc chắn là sẽ... (dự đoán gần như chắc chắn)", "blocks": [["p", "Khi nhìn vào những việc cho đến nay, sẽ có kết quả được dự đoán trong tương lai. Thường dùng nhiều khi kết quả không tốt đến. Dùng khi sự việc quá đương nhiên không cần phải nói đến. Dùng được cho cả việc của 'tôi' và 'người khác'. Tuy nhiên không dùng được cho việc có thể quyết định bằng ý chí của 'tôi'."], ["ex", "공부를 안 해서 시험을 <b>못 볼 게 뻔해요</b>. *(Đương nhiên là sẽ thi", "kém rồi). (Chẳng chịu học hành gì nên chắc chắn là sẽ thi kém thôi."], ["ex", "마이클 씨는 매일 지각하니까 오늘도 <b>지각할 게 뻔해요</b>. *(Đương", "nhiên là sẽ đi trễ rồi). (Michael ngày nào cũng đi trễ nên hôm nay chắc chắn cũng sẽ đi trễ thôi."], ["ex", "어제 잠을 늦게 잤으니까 오늘 <b>피곤할 게 뻔해요</b>. *(Đương nhiên là", "sẽ mệt mỏi rồi). (Hôm qua ngủ muộn nên hôm nay chắc chắn là sẽ mệt mỏi thôi."], ["ex", "온다고 말은 했지만 바빠서 <b>안 올 게 뻔해요</b>. *(Đương nhiên là sẽ", "không đến rồi). (Nói là sẽ đến đấy nhưng bận rộn thế chắc chắn là sẽ không đến đâu."]], "practice": [{"vn": "Chắc chắn anh ấy sẽ tức giận.", "hint": "그/화내다", "answer": "그가 화낼 게 뻔해요."}, {"vn": "Chắc chắn trời sẽ mưa.", "hint": "비/오다", "answer": "비가 올 게 뻔해요."}, {"vn": "Chắc chắn việc đó sẽ thất bại.", "hint": "그 일/실패하다", "answer": "그 일이 실패할 게 뻔해요."}]}, {"num": 62, "term": "-(으)ㄴ/는 셈이다", "meaning": "Coi như là..., xem như là", "blocks": [["p", "Thể hiện ý nghĩa 'xem xét kỹ ra thì rốt cuộc cũng giống như thế này thế nọ'."], ["ex", "이 집에서 십 년을 <b>산 셈이지요</b>.", "Tính ra là tớ đã sống ở căn nhà này được 10 năm rồi đấy nhỉ."], ["ex", "한국어 공부를 쉬지 않고 한 걸 보면 그는 꽤 <b>착실한 셈입니다</b>.", "Nhìn vào việc cậu ấy học tiếng Hàn không nghỉ ngơi thì xem ra cậu ấy thuộc dạng khá cần cù đấy."]], "practice": [{"vn": "Xem như là tôi đã thành công rồi.", "hint": "성공하다", "answer": "성공한 셈이에요."}, {"vn": "Coi như bài tập tôi đã làm xong.", "hint": "숙제/끝내다", "answer": "숙제를 끝낸 셈이에요."}, {"vn": "Xem như chúng tôi đã thắng rồi.", "hint": "이기다", "answer": "이긴 셈이에요."}]}, {"num": 63, "term": "-만 해도", "meaning": "Chỉ riêng... đã (nhấn mạnh một phần cũng đã đủ lớn/nhiều)", "blocks": [["p", "Thể hiện ý nghĩa 'dù trong lòng cân nhắc nhiều thứ nhưng chỉ cần nói về một danh từ đứng trước trong số đó thôi thì cũng đủ biết là thế nào rồi'. Do đó đây là biểu hiện mang tính nhấn mạnh."], ["ex", "<b>며칠 전까지만 해도</b> 덥다고 했는데 이젠 제법 쌀쌀해요.", "Mới chỉ đến mấy ngày trước thôi còn bảo là nóng, đằng này giờ đã khá se lạnh rồi."]], "practice": [{"vn": "Chỉ riêng tiền nhà thôi đã tốn rất nhiều.", "hint": "집세/많이/들다", "answer": "집세만 해도 많이 들어요."}, {"vn": "Chỉ riêng số lượng học sinh thôi đã hơn một trăm người.", "hint": "학생 수/백 명/넘다", "answer": "학생 수만 해도 백 명이 넘어요."}, {"vn": "Chỉ riêng năm ngoái thôi tôi đã đi ba lần rồi.", "hint": "작년/세 번/가다", "answer": "작년만 해도 세 번 갔어요."}]}, {"num": 64, "term": "-(으)ㄹ 따름이다", "meaning": "Chỉ là... mà thôi (giới hạn, khiêm tốn)", "blocks": [["p", "Thể hiện nội dung câu đứng trước 'chỉ là cái đó' và loại trừ những cái khác. Tương tự như '-(으)ㄹ 뿐이다'."], ["ex", "규민이는 놀기만 하니 <b>한심할 따름입니다</b>.", "Gyu-min chỉ toàn chơi đùa nên tớ chỉ thấy thảm hại/thất vọng mà thôi."], ["ex", "말 많은 세상이니, 그저 <b>조심할 따름이에요</b>.", "Thế gian lắm lời nhiều tiếng nên tớ chỉ biết cẩn trọng mà thôi."]], "practice": [{"vn": "Tôi chỉ làm hết sức mình mà thôi.", "hint": "최선/다하다", "answer": "최선을 다할 따름이에요."}, {"vn": "Tôi chỉ biết cảm ơn mà thôi.", "hint": "감사하다", "answer": "감사할 따름이에요."}, {"vn": "Đó chỉ là suy nghĩ của tôi mà thôi.", "hint": "제/생각", "answer": "제 생각일 따름이에요."}]}]};
